insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk6-l29', 'hsk6', 'HSK6B', 29, '“笑”的备忘录', '“Xiào” de bèiwànglù', 'A memorandum of laughing', '{"level": "hsk6", "lesson": 29, "book": "HSK6B", "title_zh": "“笑”的备忘录", "title_pinyin": "“Xiào” de bèiwànglù", "title_en": "A memorandum of laughing", "textbook": {"ref": {"book": "textbook", "pages": [95, 96, 97, 98, 99, 100, 101, 102, 103, 104, 105]}, "warmup": [{"instruction_zh": "你爱笑吗？你能听出别人是真笑还是假笑吗？怎么分辨出来的？对健康来说，笑是有益的还是有害的？有哪些益处或害处？", "instruction_en": "Warm-up", "items": ["你根据什么分辨真笑、假笑？ | 表情、声音、其他", "笑是否有益于健康？ | 益处、害处"], "pictures_desc_en": ["a tree diagram on a pale yellow background: a smiling yellow smiley face at the top branches into two boxes (你根据什么分辨真笑、假笑？ with three sub-boxes 表情 / 声音 / 其他 ; and 笑是否有益于健康？ with two sub-boxes 益处 / 害处 )"]}, {"instruction_zh": "想一想下列词语之间有什么联系。", "items": ["表 | 表态、表示、表达、表决、表白、表明、表情、表现、表演、表露", "违 | 违心、违反、违背、违法、违抗、违禁、违例、违约、违章、违法乱纪、事与愿违", "活 | 激活、灵活、活动、活络、活水、活血、活扣、活期、活性", "隐 | 隐含、隐藏、隐蔽、隐居、隐瞒、隐秘、隐情、隐忍、隐士、隐私、隐退、隐姓埋名"]}], "texts": [{"n": 1, "title_zh": "大脑能“听”出笑声的真假", "kind": "narrative", "lines": [{"zh": "真是岂有此理，难道我们听到庸俗、不上档次的笑话假笑两声、敷衍一下也不可以吗？"}, {"zh": "可是，好像确实不行。"}, {"zh": "诸位，如果你不想难堪，不想让别人发现你发出的是虚伪、违背心意的笑声，你可以回避，可以不表态，可以把话题岔开，可以装聋装哑，但不要画蛇添足，违心地笑。"}, {"zh": "因为只要你笑，不管你多机灵，不管你掩饰得多么周密，别人都能看出你的笑是真心实意，还是虚情假意、装模作样。"}, {"zh": "有人不禁要问，人是通过什么途径识别“笑”背后的真实情感呢？"}, {"zh": "研究者发现，我们在听到发自内心的笑声和虚假的笑声时，大脑会呈现出完全不同的反应。"}, {"zh": "假笑声会激活大脑中用于破译情感信息的特定区域，同时大脑会自动分析假笑的缘故，假笑者想隐瞒什么，以及假笑者的意向；诚挚的笑声则会激活大脑中与快乐和积极情绪相关的区域。"}, {"zh": "为了证实这一理论，一丝不苟的研究者让志愿者倾听网站视频中的笑声，同时记录他们大脑的反应，并将志愿者听到真笑与假笑时大脑的反应做对比。"}, {"zh": "测试结果一目了然，志愿者在预先未被告知测试目的的情况下，仅凭直觉就能准确地分辨出假笑声。"}, {"zh": "天呀，人的大脑中竟然深藏着一双能够探测他人喜悦之情真伪的眼睛！"}, {"zh": "研究者指出：“人类大脑对于笑声中所隐含的社会和情感信息非常敏感，这不完全是智商问题。"}, {"zh": "当志愿者听到笑声时，会开启大脑中与心智相关的区域，从而获知他人的情感或精神状态，有些志愿者还动用了大脑中控制运动和感知的部分，进而更精准地提炼出真假笑声背后的信息。”"}], "new_words": [{"n": 1, "zh": "备忘录", "pinyin": "bèiwànglù", "pos": "n.", "en": "memorandum", "text": 1}, {"n": 2, "zh": "岂有此理", "pinyin": "qǐyǒucǐlǐ", "en": "How unreasonable!", "text": 1}, {"n": 3, "zh": "庸俗", "pinyin": "yōngsú", "pos": "adj.", "en": "vulgar", "text": 1}, {"n": 4, "zh": "档次", "pinyin": "dàngcì", "pos": "n.", "en": "level", "text": 1}, {"n": 5, "zh": "诸位", "pinyin": "zhūwèi", "pos": "pron.", "en": "everybody", "text": 1}, {"n": 6, "zh": "难堪", "pinyin": "nánkān", "pos": "adj.", "en": "embarrassed", "text": 1}, {"n": 7, "zh": "虚伪", "pinyin": "xūwěi", "pos": "adj.", "en": "hypocritical", "text": 1}, {"n": 8, "zh": "违背", "pinyin": "wéibèi", "pos": "v.", "en": "to violate, to go against", "text": 1}, {"n": 9, "zh": "回避", "pinyin": "huíbì", "pos": "v.", "en": "to avoid, to dodge", "text": 1}, {"n": 10, "zh": "岔", "pinyin": "chà", "pos": "v.", "en": "to change the topic or subject of conversation", "text": 1}, {"n": 11, "zh": "装聋装哑", "pinyin": "zhuānglóng zhuāngyǎ", "en": "to pretend to be deaf and dumb, to pretend to be ignorant of sth.", "text": 1}, {"n": 11, "zh": "聋哑", "pinyin": "lóngyǎ", "pos": "adj.", "en": "deaf and dumb", "text": 1}, {"n": 12, "zh": "画蛇添足", "pinyin": "huàshé-tiānzú", "en": "to paint a snake with feet—superfluous", "text": 1}, {"n": 13, "zh": "机灵", "pinyin": "jīling", "pos": "adj.", "en": "smart, clever", "text": 1}, {"n": 14, "zh": "周密", "pinyin": "zhōumì", "pos": "adj.", "en": "careful, thorough", "text": 1}, {"n": 15, "zh": "途径", "pinyin": "tújìng", "pos": "n.", "en": "way, approach", "text": 1}, {"n": 16, "zh": "虚假", "pinyin": "xūjiǎ", "pos": "adj.", "en": "false, deceptive", "text": 1}, {"n": 17, "zh": "特定", "pinyin": "tèdìng", "pos": "adj.", "en": "specific", "text": 1}, {"n": 18, "zh": "缘故", "pinyin": "yuángù", "pos": "n.", "en": "reason, cause", "text": 1}, {"n": 19, "zh": "意向", "pinyin": "yìxiàng", "pos": "n.", "en": "intention, purpose", "text": 1}, {"n": 20, "zh": "诚挚", "pinyin": "chéngzhì", "pos": "adj.", "en": "sincere", "text": 1}, {"n": 21, "zh": "一丝不苟", "pinyin": "yìsī-bùgǒu", "en": "to be scrupulous about every detail", "text": 1}, {"n": 22, "zh": "倾听", "pinyin": "qīngtīng", "pos": "v.", "en": "to listen attentively to", "text": 1}, {"n": 23, "zh": "视频", "pinyin": "shìpín", "pos": "n.", "en": "video", "text": 1}, {"n": 24, "zh": "一目了然", "pinyin": "yímù-liǎorán", "en": "to be clear at a glance", "text": 1}, {"n": 25, "zh": "预先", "pinyin": "yùxiān", "pos": "adv.", "en": "in advance, beforehand", "text": 1}, {"n": 26, "zh": "直觉", "pinyin": "zhíjué", "pos": "n.", "en": "intuition", "star": true, "text": 1}, {"n": 27, "zh": "探测", "pinyin": "tàncè", "pos": "v.", "en": "to detect", "text": 1}, {"n": 28, "zh": "智商", "pinyin": "zhìshāng", "pos": "n.", "en": "intelligence", "text": 1}, {"n": 29, "zh": "提炼", "pinyin": "tíliàn", "pos": "v.", "en": "to refine, to extract", "text": 1}]}, {"n": 2, "title_zh": "笑未必是最佳良药", "kind": "narrative", "lines": [{"zh": "中国人喜欢听相声，因为它逗笑。"}, {"zh": "“笑有益于健康”几乎得到了全世界的认可，“笑一笑十年少”“一笑解千愁”不仅被大家认可，甚至被一些人当作生活的座右铭。"}, {"zh": "中国人深信开怀大笑也好，哈哈傻笑也罢，哪怕是私下里偷偷地笑，都会是生活中最通用，而且管用的治病良方。"}, {"zh": "有研究证实，笑可以调节情绪，可以促进血液循环和腹肌收缩，100次捧腹大笑所吸收的氧气相当于用桨划船10分钟的吸氧量。"}, {"zh": "有人做过这样的试验，开怀大笑一整天，可以燃烧掉2000卡路里，从而帮助消耗脂肪，减轻体重，同时，笑有助于缓解动脉硬化，有助于消除紧张感，这就是笑有利于健康的实质性的证据。"}, {"zh": "然而，笑，真的是人生旅途中的最佳良药吗？"}, {"zh": "答案似乎不是那么肯定。"}, {"zh": "有研究人员表示，笑也不是有百益而无一害的，有时它还会产生副作用。"}, {"zh": "有医生就碰到过这样的案例：有人在肆无忌惮地笑过后因心跳加速而昏迷，而大笑到“几乎笑破肚皮”可能会导致岔气，心脏不舒服，甚至损坏人体健康。"}, {"zh": "新的研究结果对笑“有百益而无一害”的观点提出了挑战，似乎更倾向于笑不是坏事，但分寸要掌握得恰到好处。"}, {"zh": "可是多数人还是深信，笑的是非无须探讨，任何形式的幽默，伤害风险都不高，其收益则是显而易见的，况且，真是好朋友在一起，高兴了，起起哄，或是遇到了开心事，哪里还顾得上斟酌分寸掌握得恰当不恰当呢？"}], "new_words": [{"n": 30, "zh": "相声", "pinyin": "xiàngsheng", "pos": "n.", "en": "crosstalk", "text": 2}, {"n": 31, "zh": "座右铭", "pinyin": "zuòyòumíng", "pos": "n.", "en": "motto", "text": 2}, {"n": 32, "zh": "通用", "pinyin": "tōngyòng", "pos": "v.", "en": "to be in common use, to be universal", "text": 2}, {"n": 33, "zh": "调节", "pinyin": "tiáojié", "pos": "v.", "en": "to regulate", "text": 2}, {"n": 34, "zh": "循环", "pinyin": "xúnhuán", "pos": "v.", "en": "to circulate", "text": 2}, {"n": 35, "zh": "收缩", "pinyin": "shōusuō", "pos": "v.", "en": "to shrink", "text": 2}, {"n": 36, "zh": "氧气", "pinyin": "yǎngqì", "pos": "n.", "en": "oxygen", "text": 2}, {"n": 37, "zh": "桨", "pinyin": "jiǎng", "pos": "n.", "en": "paddle", "text": 2}, {"n": 38, "zh": "试验", "pinyin": "shìyàn", "pos": "v.", "en": "to test, to do an experiment", "text": 2}, {"n": 39, "zh": "脂肪", "pinyin": "zhīfáng", "pos": "n.", "en": "fat", "text": 2}, {"n": 40, "zh": "动脉", "pinyin": "dòngmài", "pos": "n.", "en": "artery", "text": 2}, {"n": 41, "zh": "实质", "pinyin": "shízhì", "pos": "n.", "en": "essence, substance", "text": 2}, {"n": 42, "zh": "肆无忌惮", "pinyin": "sìwú-jìdàn", "en": "to act recklessly and care for nobody, to act outrageously", "text": 2}, {"n": 43, "zh": "损坏", "pinyin": "sǔnhuài", "pos": "v.", "en": "to damage, to spoil", "text": 2}, {"n": 44, "zh": "倾向", "pinyin": "qīngxiàng", "pos": "v.", "en": "to tend to, to be inclined to", "text": 2}, {"n": 45, "zh": "分寸", "pinyin": "fēncun", "pos": "n.", "en": "proper limits for speech or action", "text": 2}, {"n": 46, "zh": "恰到好处", "pinyin": "qiàdào-hǎochù", "en": "to be just perfect, to be to the point", "text": 2}, {"n": 47, "zh": "是非", "pinyin": "shìfēi", "pos": "n.", "en": "right and wrong", "text": 2}, {"n": 48, "zh": "探讨", "pinyin": "tàntǎo", "pos": "v.", "en": "to discuss", "text": 2}, {"n": 49, "zh": "收益", "pinyin": "shōuyì", "pos": "n.", "en": "profit, gains", "text": 2}, {"n": 50, "zh": "起哄", "pinyin": "qǐ hòng", "pos": "v.", "en": "to kick up a fuss", "text": 2}, {"n": 51, "zh": "斟酌", "pinyin": "zhēnzhuó", "pos": "v.", "en": "to consider, to think over", "text": 2}, {"n": 52, "zh": "恰当", "pinyin": "qiàdàng", "pos": "adj.", "en": "appropriate, proper", "text": 2}]}], "grammar": [{"n": 1, "title_zh": "预先", "title_en": "（一）综合注释", "explanation_zh": "“预先”，副词，意思是在事情发生或动作进行之前就采取了某种行动。", "examples": [{"n": 1, "zh": "那里一年四季都是旅游旺季，到那里去旅行，一定要预先订好旅馆。"}, {"n": 2, "zh": "大家预先都没有想到，本届绘画展览竟然这么受欢迎。"}, {"n": 3, "zh": "志愿者在预先未被告知测试目的的情况下，仅凭直觉就能准确地分辨出假笑声。", "note_zh": "课文句"}], "practice_instruction_zh": "练一练：用“预先”完成句子", "practice": [{"n": 1, "zh": "这事她________，我最近都忙糊涂了，忘了告诉你了。", "answer": "预先通知过我", "answer_ref": {"book": "textbook_answers", "pages": [16]}}, {"n": 2, "zh": "他________的是，居然有那么多朋友，在他最困难的时候向他伸出了援手。", "answer": "预先没有想到", "answer_ref": {"book": "textbook_answers", "pages": [16]}}, {"n": 3, "zh": "古代递送紧急公文也骑马。一天中马该跑多少路，都有规定。从这一站到那一站多远，也规定好了。送公文的到了，吃饱喝足，稍稍休息一下，换一匹________，继续赶路。", "answer": "预先准备好的马", "answer_ref": {"book": "textbook_answers", "pages": [16]}}]}, {"n": 2, "title_zh": "……也好，……也罢", "title_en": "（一）综合注释", "explanation_zh": "“……也好，……也罢”用以列举，表示在任何情况下都是这样。也可以说“……也好，……也好”“……也罢，……也罢”。下文常与“都、也”配合使用。", "structure_rows": ["……也好，……也罢", "……也好，……也好", "……也罢，……也罢"], "examples": [{"n": 1, "zh": "中国人深信开怀大笑也好，哈哈傻笑也罢，哪怕是私下里偷偷地笑，都会是生活中最通用，而且管用的治病良方。", "note_zh": "课文句"}, {"n": 2, "zh": "退休以后别人都养养花，喂喂鸟，可是花也好，鸟也好，都引不起他的兴趣。"}, {"n": 3, "zh": "开汽车也罢，骑自行车也罢，行进中打电话都会影响注意力与反应能力。"}], "practice_instruction_zh": "练一练：用“……也好／也罢，……也好／也罢”或者“……也好，……也罢”改写句子", "practice": [{"n": 1, "zh": "是上学还是工作，只要你自己愿意就行。\n________。", "answer": "上学也好还是工作也罢，只要你自己愿意就行。", "answer_ref": {"book": "textbook_answers", "pages": [16]}}, {"n": 2, "zh": "考试已经完了，考得好不好，再想也没用了。\n________。", "answer": "考试已经完了，考得好也好，不好也罢，再想也没用了。", "answer_ref": {"book": "textbook_answers", "pages": [16]}}, {"n": 3, "zh": "不管明天是什么天气，刮风或者下雨，都不能影响我们六点准时出发。\n________。", "answer": "不管明天是什么天气，刮风也好下雨也罢，都不能影响我们六点准时出发。", "answer_ref": {"book": "textbook_answers", "pages": [16]}}]}, {"n": 3, "title_zh": "诸——各", "title_en": "（二）词语辨析", "explanation_zh": "（二）词语辨析 诸——各\n共同点：在人称代词“诸位、各位”中意思和用法相同。如：诸位/各位有何意见，请尽量发表。\n不同点：\n诸——1. 书面语，表示“众、许多”的意思。后边的名词或量词一般都是指人的。一般为固定结构。如：诸位/诸君/诸侯/诸子百家\n各——1. 表示某一范围内的所有个体，不只指人，还可以指别的事物。如：各位/各方/各界/各国\n诸——2. 没有右边这个用法。\n各——2. 表示不止一人做某事或不止一物有某种属性。如：①双方各执一词。②院子前后各有一门。\n诸——3. 不能用在动词前面。\n各——3. 可以做副词，放在动词前面，表示“分别”“每一个”。如：①几种水果他各买了一斤。②他们各想了一个办法。", "structure_rows": [" | 诸 | 各", "共同点 | 在人称代词“诸位、各位”中意思和用法相同。（两栏合并）", "共同点 | 如：诸位/各位有何意见，请尽量发表。（两栏合并）", "不同点 | 1. 书面语，表示“众、许多”的意思。后边的名词或量词一般都是指人的。一般为固定结构。 | 1. 表示某一范围内的所有个体，不只指人，还可以指别的事物。", "不同点 | 如：诸位/诸君/诸侯/诸子百家 | 如：各位/各方/各界/各国", "不同点 | 2. 没有右边这个用法。 | 2. 表示不止一人做某事或不止一物有某种属性。", "不同点 | （同上） | 如：①双方各执一词。②院子前后各有一门。", "不同点 | 3. 不能用在动词前面。 | 3. 可以做副词，放在动词前面，表示“分别”“每一个”。", "不同点 | （同上） | 如：①几种水果他各买了一斤。②他们各想了一个办法。"], "examples": [{"n": 1, "zh": "诸位/各位有何意见，请尽量发表。", "note_zh": "共同点"}, {"n": 2, "zh": "诸位/诸君/诸侯/诸子百家", "note_zh": "诸 不同点1"}, {"n": 3, "zh": "各位/各方/各界/各国", "note_zh": "各 不同点1"}, {"n": 4, "zh": "双方各执一词。", "note_zh": "各 不同点2 ①"}, {"n": 5, "zh": "院子前后各有一门。", "note_zh": "各 不同点2 ②"}, {"n": 6, "zh": "几种水果他各买了一斤。", "note_zh": "各 不同点3 ①"}, {"n": 7, "zh": "他们各想了一个办法。", "note_zh": "各 不同点3 ②"}], "practice_instruction_zh": "做一做：判断正误", "practice": [{"n": 1, "zh": "亚洲各国首脑都参加了此次会议。（　　）", "answer": "√", "answer_ref": {"book": "textbook_answers", "pages": [16]}}, {"n": 2, "zh": "经过诸方的共同努力，事情终于圆满解决了。（　　）", "answer": "×", "answer_ref": {"book": "textbook_answers", "pages": [16]}}, {"n": 3, "zh": "三种办法各有优点和缺点，实在难以抉择。（　　）", "answer": "√", "answer_ref": {"book": "textbook_answers", "pages": [16]}}, {"n": 4, "zh": "他喜欢读古代诸子百家的著作。（　　）", "answer": "√", "answer_ref": {"book": "textbook_answers", "pages": [16]}}]}, {"n": 4, "title_zh": "修辞（6）设问", "title_en": "（三）篇章修辞", "explanation_zh": "（三）篇章修辞 修辞（6）设问\n无疑而问，自问自答即设问修辞手法。设问的作用有两个：一是引起读者的注意，启发读者思考；二是便于组织文章，例（2）就使语义的转折过渡自然而简练。", "examples": [{"n": 1, "zh": "难道我们听到庸俗、不上档次的笑话假笑两声、敷衍一下也不可以吗？可是，好像确实不行。", "note_zh": "课文句"}, {"n": 2, "zh": "笑，真的是人生旅途中的最佳良药吗？答案似乎不是那么肯定。", "note_zh": "课文句"}, {"n": 3, "zh": "离开了手机，难道会死吗？何不尝试一下一周关机一天？说干就干，索性这礼拜就开始。"}], "practice_instruction_zh": "练一练：将下列句子改写为设问句", "practice": [{"n": 1, "zh": "有钱不一定幸福，有朋友，有健康，有自己的事业才会幸福。\n________。", "answer": "有钱一定幸福吗？不一定，有朋友，有健康，有自己的事业才会幸福。", "answer_ref": {"book": "textbook_answers", "pages": [16]}}, {"n": 2, "zh": "气候真的变暖了，没错，我们的地球每一天都在变化。\n________。", "answer": "气候真的变暖了吗？没错，我们的地球每一天都在变化。", "answer_ref": {"book": "textbook_answers", "pages": [16]}}, {"n": 3, "zh": "奋斗的人生是最美好的，因为奋斗之中快乐无穷。\n________。", "answer": "奋斗的人生是最美好的吗？是的，因为奋斗之中快乐无穷。", "answer_ref": {"book": "textbook_answers", "pages": [17]}}]}], "exercises": [{"n": 1, "type_zh": "模仿例子写词语", "instruction_zh": "模仿例子，写出更多的词语", "instruction_en": "Exercises", "items": [{"n": "例", "zh": "实质：本质　性质　品质　素质", "hint_zh": "（质）"}, {"n": 1, "zh": "档次：________", "hint_zh": "（档）", "answer": "存档、档案、高档、低档", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 2, "zh": "回避：________", "hint_zh": "（避）", "answer": "躲避、避雨、避免、避重就轻", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 3, "zh": "周密：________", "hint_zh": "（周）", "answer": "周围、周全、周岁、周末", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 4, "zh": "提炼：________", "hint_zh": "（提）", "answer": "提前、前提、提取、提心吊胆", "answer_ref": {"book": "textbook_answers", "pages": [17]}}]}, {"n": 2, "type_zh": "改写句子", "instruction_zh": "用所给词语或结构改写句子", "items": [{"n": 1, "zh": "付出艰苦努力的人什么都没得到，哪有这样的道理啊？\n________。", "hint_zh": "（岂有此理）", "answer": "付出艰苦努力的人什么都没得到，岂有此理！", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 2, "zh": "我已经提前做好了计划，所以实施起来很顺利。\n________。", "hint_zh": "（预先）", "answer": "我已经预先做好了计划，所以实施起来很顺利。", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 3, "zh": "无论富贵还是贫穷，我对他的爱不会改变。\n________。", "hint_zh": "（……也好，……也罢）", "answer": "富贵也好贫穷也罢，我对他的爱不会改变。", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 4, "zh": "“米”是国际上普遍使用的基本长度单位。\n________。", "hint_zh": "（通用）", "answer": "“米”是世界上通用的基本长度单位。", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 5, "zh": "问题的本质在于某些人缺乏责任心。\n________。", "hint_zh": "（实质）", "answer": "问题的实质在于某些人缺乏责任心。", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 6, "zh": "明天的会议很重要，发言稿你好好考虑考虑。\n________。", "hint_zh": "（斟酌）", "answer": "明天的会议很重要，发言稿你好好斟酌斟酌。", "answer_ref": {"book": "textbook_answers", "pages": [17]}}]}, {"n": 3, "type_zh": "选词填空", "instruction_zh": "选择合适的词语填空", "word_bank": [["损坏", "循环", "脂肪", "收缩", "动脉"], ["恰当", "周密", "意向", "收益", "一丝不苟"]], "items": [{"n": 1, "zh": "心脏每时每刻都在跳动，有规律地________和舒张，这可以使血液在体内不断________，因此心脏的重要性不言而喻。而肥胖会导致________硬化，________心脏机能。所以减轻体重，减少________含量是保护心脏重要的一步。", "hint_zh": "（损坏、循环、脂肪、收缩、动脉）", "answer": "收缩、循环、动脉、损坏、脂肪", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 2, "zh": "新产品面世以前，一般要先调查消费者的购买________，然后经过________的设计，________的生产过程，再找一个________的时机投放到市场，才能获得可观的________。", "hint_zh": "（恰当、周密、意向、收益、一丝不苟）", "answer": "意向、周密、一丝不苟、恰当、收益", "answer_ref": {"book": "textbook_answers", "pages": [17]}}]}, {"n": 4, "type_zh": "问答连线", "instruction_zh": "请给下面的问句选择对应的答句并连线（问句 | 答句）", "items": [{"n": 1, "zh": "竺可桢走进北海公园，单是为了观赏景物吗？", "options": {"A": "它是人类所创造的财富的总和，特指精神财富，如文学、艺术、教育、科学，文明涵盖了人与人、人与社会、人与自然之间的关系。", "B": "唯有青青松树枝。", "C": "不是，他是来观察物候，做科学研究的。", "D": "不是。有的植物不但能够运动，而且还会跳舞呢。"}, "answer": "C", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 2, "zh": "如何定义“文明”？", "options": {"A": "它是人类所创造的财富的总和，特指精神财富，如文学、艺术、教育、科学，文明涵盖了人与人、人与社会、人与自然之间的关系。", "B": "唯有青青松树枝。", "C": "不是，他是来观察物候，做科学研究的。", "D": "不是。有的植物不但能够运动，而且还会跳舞呢。"}, "answer": "A", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 3, "zh": "你也许以为植物都是不能运动的吧？", "options": {"A": "它是人类所创造的财富的总和，特指精神财富，如文学、艺术、教育、科学，文明涵盖了人与人、人与社会、人与自然之间的关系。", "B": "唯有青青松树枝。", "C": "不是，他是来观察物候，做科学研究的。", "D": "不是。有的植物不但能够运动，而且还会跳舞呢。"}, "answer": "D", "answer_ref": {"book": "textbook_answers", "pages": [17]}}, {"n": 4, "zh": "雪中何以赠君别？", "options": {"A": "它是人类所创造的财富的总和，特指精神财富，如文学、艺术、教育、科学，文明涵盖了人与人、人与社会、人与自然之间的关系。", "B": "唯有青青松树枝。", "C": "不是，他是来观察物候，做科学研究的。", "D": "不是。有的植物不但能够运动，而且还会跳舞呢。"}, "answer": "B", "answer_ref": {"book": "textbook_answers", "pages": [17]}}]}, {"n": 5, "type_zh": "简述课文", "instruction_zh": "根据提示，简述课文主要内容（课文（一）、课文（二）各一表格：问题 | 提示）", "items": [{"n": 1, "zh": "课文（一）：为什么说不要用假笑敷衍别人？", "hint_zh": "①如果不想……，可以……，可以……，可以……，可以……，但不要……　②因为只要……，不管……，不管……，别人都能……"}, {"n": 2, "zh": "课文（一）：人们通过什么途径识别假笑的？", "hint_zh": "①……激活……特定区域　②……自动分析……缘故　③诚挚的笑声会……　④志愿者的反映"}, {"n": 3, "zh": "课文（一）：研究结果是什么？", "hint_zh": "①……对……非常敏感　②开启……区域，获知……，动用……部分，提炼出……信息"}, {"n": 4, "zh": "课文（二）：为什么说笑是治病良方？", "hint_zh": "调节情绪，促进……循环和……收缩，吸氧量，燃烧卡路里，消耗脂肪，减轻体重，缓解动脉硬化，消除紧张感"}, {"n": 5, "zh": "课文（二）：笑有什么坏处？", "hint_zh": "因心跳加速而昏迷，岔气，心脏不舒服"}, {"n": 6, "zh": "课文（二）：怎么笑才健康？", "hint_zh": "把握分寸"}]}, {"n": "扩展1", "type_zh": "扩展 词汇：熟悉下列近义词", "instruction_zh": "扩展 词汇\n（1）熟悉下列近义词", "instruction_en": "Expansion", "items": [{"n": 1, "zh": "腐朽——腐败"}, {"n": 2, "zh": "烘——烤"}, {"n": 3, "zh": "焦点——中心"}, {"n": 4, "zh": "内幕——内情"}, {"n": 5, "zh": "埋葬——安葬"}, {"n": 6, "zh": "衔接——连接"}, {"n": 7, "zh": "践踏——摧残"}, {"n": 8, "zh": "陷阱——圈套"}, {"n": 9, "zh": "示意——暗示"}, {"n": 10, "zh": "相等——相当"}, {"n": 11, "zh": "妥善——稳妥"}, {"n": 12, "zh": "贼——小偷"}, {"n": 13, "zh": "旋转——转动"}, {"n": 14, "zh": "住宅——住所"}, {"n": 15, "zh": "呕吐——吐"}, {"n": 16, "zh": "正当——合法"}]}, {"n": "扩展2", "type_zh": "扩展 词汇：政治方面的词语连线", "instruction_zh": "（2）将下列政治方面的词语与其对应的意思连线", "word_bank": [["统治", "时事", "条约", "纲领"]], "items": [{"n": 1, "zh": "统治", "options": {"1": "最近一段时间的国内外大事。", "2": "国家和国家签订的有关政治、军事、经济或文化等方面的权利和义务的文书。", "3": "政府、政党、社团根据自己在一定时期内的任务而规定的奋斗目标和行动步骤。", "4": "凭借政权来控制、管理国家或地区。"}, "answer": "4", "answer_ref": {"book": "textbook_answers", "pages": [18]}}, {"n": 2, "zh": "时事", "options": {"1": "最近一段时间的国内外大事。", "2": "国家和国家签订的有关政治、军事、经济或文化等方面的权利和义务的文书。", "3": "政府、政党、社团根据自己在一定时期内的任务而规定的奋斗目标和行动步骤。", "4": "凭借政权来控制、管理国家或地区。"}, "answer": "1", "answer_ref": {"book": "textbook_answers", "pages": [18]}}, {"n": 3, "zh": "条约", "options": {"1": "最近一段时间的国内外大事。", "2": "国家和国家签订的有关政治、军事、经济或文化等方面的权利和义务的文书。", "3": "政府、政党、社团根据自己在一定时期内的任务而规定的奋斗目标和行动步骤。", "4": "凭借政权来控制、管理国家或地区。"}, "answer": "2", "answer_ref": {"book": "textbook_answers", "pages": [18]}}, {"n": 4, "zh": "纲领", "options": {"1": "最近一段时间的国内外大事。", "2": "国家和国家签订的有关政治、军事、经济或文化等方面的权利和义务的文书。", "3": "政府、政党、社团根据自己在一定时期内的任务而规定的奋斗目标和行动步骤。", "4": "凭借政权来控制、管理国家或地区。"}, "answer": "3", "answer_ref": {"book": "textbook_answers", "pages": [18]}}]}], "application": [{"title_zh": "写一写", "instruction_zh": "这篇课文用两篇小短文给我们讲述了跟笑有关的科学知识。人们对假笑很敏感，假笑是怎么被识别出来的？对健康来说，笑有什么益处，有什么坏处，怎么笑才健康？请参考练习5，把两篇课文各缩写成200字左右的短文。", "instruction_en": "Application"}], "culture": {"title_zh": "课文脚注", "body_zh": "① 卡路里：热量的计量单位，符号cal。简称卡。［法calorie］"}}, "workbook": {"ref": {"book": "workbook", "pages": [79, 80, 81, 82, 83, 84, 85, 86]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：请选出与所听内容一致的一项。", "items": [{"n": 1, "zh": "", "options": {"A": "《康熙字典》是康熙编的", "B": "《康熙字典》的编纂者共有2人", "C": "《康熙字典》的名字是康熙起的", "D": "编写《康熙字典》共用了6年时间"}, "transcript_zh": "《康熙字典》是清代康熙年间出版的图书，作者是张玉书、陈廷敬等，它是在明朝《字汇》《正字通》两书的基础上加以增订的。该书的编撰工作始于康熙四十九年，成书于康熙五十五年，历时六年，因此书名叫《康熙字典》。", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [34]}}, {"n": 2, "zh": "", "options": {"A": "爱起哄的心态不健康", "B": "有好奇心是人的本性", "C": "在街上唱歌是一种快乐", "D": "喜欢凑热闹的人不在少数"}, "transcript_zh": "有些人很爱凑热闹，不管街头发生什么事情，他们都要驻足引颈，看个究竟。有的还免不了要放开喉咙，起哄喝倒彩，从中寻找乐趣，寻求刺激，这其实反映出一种病态心理。", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [34]}}, {"n": 3, "zh": "", "options": {"A": "婴儿喜欢拥有自己的玩具", "B": "大人总会帮婴儿实现目标", "C": "大人应该想办法了解婴儿的理想", "D": "1岁的婴儿会表现出自己的意向"}, "transcript_zh": "婴儿在1周岁左右，开始学会独立行走，能更自由地接近和探索周围事物。当他看到桌子上放着一个他喜爱的玩具而无法拿到手时，会推大人的手去拿，表现出初步的有意向的行动。", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [34]}}, {"n": 4, "zh": "", "options": {"A": "读者的时间也是成本", "B": "报纸的成本越来越高", "C": "扩版后报纸信息变少", "D": "现在的人不愿意读报"}, "transcript_zh": "读者获取信息也是有成本与收益的。他们花钱买报，花时间看报就是成本，从报纸中得到对自己有用的信息就是收益。报纸扩版后，读者的成本增加了，尤其是要花更多宝贵的时间去读，忙碌的现代人承受不起这么高的成本。", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [34]}}, {"n": 5, "zh": "", "options": {"A": "这个剧本只适合阅读", "B": "这个剧本演出效果很好", "C": "这个剧本写得极其成功", "D": "生活中的口语是最文雅的"}, "transcript_zh": "这个剧本的可读性很强，尤其是剧本的语言，让人看后久久难忘。它的语言虽然都是生活中的口语，但经过了作者的提炼熔铸后，显得既鲜活又不失文雅，而且富有情趣。可以想象，这样朗朗上口的语言，一定很适合舞台演出。", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [35]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：请选出正确答案。", "items": [{"n": 6, "zh": "", "options": {"A": "厨师省脑子", "B": "厨师挣钱多", "C": "厨师不会失业", "D": "厨师不会挨饿"}, "transcript_zh": "女：能不能告诉我们，您最初怎么选中了厨师这个行业？\n男：我最初选择学厨师，想法很简单，人走到哪里都得吃饭，干这一行肯定饿不着。\n女：后来怎么就做到了五星级酒店的京菜主厨呢？\n男：进了饭店从做小工、刷盘子开始，我越干越觉得，厨师这一行实在是个让人痴迷又魅力无穷的行业。\n女：我们都知道掂大勺、刀功，都是厨师的看家本领，您学艺过程中，最头疼的是什么呢？\n男：记得刚学会做菜那会儿，我是吃到哪儿挑到哪儿，每吃一道菜，都要评头论足，“油放少了”“盐放多了”。后来，我想明白了，同样的调料，不同的人会炒出不同的味儿，就是中餐的精髓。我学做饭那时候，最伤脑筋的就是菜谱上“少许”这俩字，老是分寸把握不好。把这两个字琢磨透了，就可以出师了。\n女：自从您学厨师之后，过年过节，您家的聚餐就成了您露一手的机会了吧？\n男：说到这儿，我就会想起奶油菜花，这道菜给我的教训太深了。\n女：能讲给我们听听吗？\n男：2003年春节，我在学校练了一年的基本功，急于给大伙儿露一手，自告奋勇要给大家来个奶油菜花。这道菜我没做过，听老师在课堂上提过，觉得没什么难的。结果我进了厨房，一看那一堆菜花和黄油就傻眼了，最后愣是做出一锅大乱炖。菜端上桌，我觉得太丢人了，简直无地自容。亲戚朋友倒是非常捧场，把那道菜吃了个精光。\n女：大伙儿肯定能原谅您，那时候您还是个刚入学一年的学生嘛。\n男：8年以后，我把家里的亲戚朋友召集到一块儿，来了场“雪耻之战”。我当时放下豪言，让大家随便点，想吃什么点什么，他们能想得出的，我都能做。几个小时倒腾出来的十几道菜，当然也得到了大伙儿的一致称赞。\n女：您心里特别美吧？\n男：那就不用说了。\n问：男的为什么选择做厨师？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [35, 36]}}, {"n": 7, "zh": "", "options": {"A": "因为做小工、刷盘子太累", "B": "因为他从小喜欢吃北京菜", "C": "因为他迷恋上了厨师这个行业", "D": "因为他的师傅是个很有魅力的人"}, "transcript_zh": "女：能不能告诉我们，您最初怎么选中了厨师这个行业？\n男：我最初选择学厨师，想法很简单，人走到哪里都得吃饭，干这一行肯定饿不着。\n女：后来怎么就做到了五星级酒店的京菜主厨呢？\n男：进了饭店从做小工、刷盘子开始，我越干越觉得，厨师这一行实在是个让人痴迷又魅力无穷的行业。\n女：我们都知道掂大勺、刀功，都是厨师的看家本领，您学艺过程中，最头疼的是什么呢？\n男：记得刚学会做菜那会儿，我是吃到哪儿挑到哪儿，每吃一道菜，都要评头论足，“油放少了”“盐放多了”。后来，我想明白了，同样的调料，不同的人会炒出不同的味儿，就是中餐的精髓。我学做饭那时候，最伤脑筋的就是菜谱上“少许”这俩字，老是分寸把握不好。把这两个字琢磨透了，就可以出师了。\n女：自从您学厨师之后，过年过节，您家的聚餐就成了您露一手的机会了吧？\n男：说到这儿，我就会想起奶油菜花，这道菜给我的教训太深了。\n女：能讲给我们听听吗？\n男：2003年春节，我在学校练了一年的基本功，急于给大伙儿露一手，自告奋勇要给大家来个奶油菜花。这道菜我没做过，听老师在课堂上提过，觉得没什么难的。结果我进了厨房，一看那一堆菜花和黄油就傻眼了，最后愣是做出一锅大乱炖。菜端上桌，我觉得太丢人了，简直无地自容。亲戚朋友倒是非常捧场，把那道菜吃了个精光。\n女：大伙儿肯定能原谅您，那时候您还是个刚入学一年的学生嘛。\n男：8年以后，我把家里的亲戚朋友召集到一块儿，来了场“雪耻之战”。我当时放下豪言，让大家随便点，想吃什么点什么，他们能想得出的，我都能做。几个小时倒腾出来的十几道菜，当然也得到了大伙儿的一致称赞。\n女：您心里特别美吧？\n男：那就不用说了。\n问：为什么男的能做到五星级酒店的京菜主厨？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [35, 36]}}, {"n": 8, "zh": "", "options": {"A": "要多放油", "B": "做菜讲究标准化", "C": "各种调料要按顺序放", "D": "各种调料的量要恰到好处"}, "transcript_zh": "女：能不能告诉我们，您最初怎么选中了厨师这个行业？\n男：我最初选择学厨师，想法很简单，人走到哪里都得吃饭，干这一行肯定饿不着。\n女：后来怎么就做到了五星级酒店的京菜主厨呢？\n男：进了饭店从做小工、刷盘子开始，我越干越觉得，厨师这一行实在是个让人痴迷又魅力无穷的行业。\n女：我们都知道掂大勺、刀功，都是厨师的看家本领，您学艺过程中，最头疼的是什么呢？\n男：记得刚学会做菜那会儿，我是吃到哪儿挑到哪儿，每吃一道菜，都要评头论足，“油放少了”“盐放多了”。后来，我想明白了，同样的调料，不同的人会炒出不同的味儿，就是中餐的精髓。我学做饭那时候，最伤脑筋的就是菜谱上“少许”这俩字，老是分寸把握不好。把这两个字琢磨透了，就可以出师了。\n女：自从您学厨师之后，过年过节，您家的聚餐就成了您露一手的机会了吧？\n男：说到这儿，我就会想起奶油菜花，这道菜给我的教训太深了。\n女：能讲给我们听听吗？\n男：2003年春节，我在学校练了一年的基本功，急于给大伙儿露一手，自告奋勇要给大家来个奶油菜花。这道菜我没做过，听老师在课堂上提过，觉得没什么难的。结果我进了厨房，一看那一堆菜花和黄油就傻眼了，最后愣是做出一锅大乱炖。菜端上桌，我觉得太丢人了，简直无地自容。亲戚朋友倒是非常捧场，把那道菜吃了个精光。\n女：大伙儿肯定能原谅您，那时候您还是个刚入学一年的学生嘛。\n男：8年以后，我把家里的亲戚朋友召集到一块儿，来了场“雪耻之战”。我当时放下豪言，让大家随便点，想吃什么点什么，他们能想得出的，我都能做。几个小时倒腾出来的十几道菜，当然也得到了大伙儿的一致称赞。\n女：您心里特别美吧？\n男：那就不用说了。\n问：关于中餐，下列哪项正确？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [35, 36]}}, {"n": 9, "zh": "", "options": {"A": "是男的学会的第一道菜", "B": "最后男的根本没做出来", "C": "是大家强烈要求男的做的菜", "D": "是大家公认最好吃的一道菜"}, "transcript_zh": "女：能不能告诉我们，您最初怎么选中了厨师这个行业？\n男：我最初选择学厨师，想法很简单，人走到哪里都得吃饭，干这一行肯定饿不着。\n女：后来怎么就做到了五星级酒店的京菜主厨呢？\n男：进了饭店从做小工、刷盘子开始，我越干越觉得，厨师这一行实在是个让人痴迷又魅力无穷的行业。\n女：我们都知道掂大勺、刀功，都是厨师的看家本领，您学艺过程中，最头疼的是什么呢？\n男：记得刚学会做菜那会儿，我是吃到哪儿挑到哪儿，每吃一道菜，都要评头论足，“油放少了”“盐放多了”。后来，我想明白了，同样的调料，不同的人会炒出不同的味儿，就是中餐的精髓。我学做饭那时候，最伤脑筋的就是菜谱上“少许”这俩字，老是分寸把握不好。把这两个字琢磨透了，就可以出师了。\n女：自从您学厨师之后，过年过节，您家的聚餐就成了您露一手的机会了吧？\n男：说到这儿，我就会想起奶油菜花，这道菜给我的教训太深了。\n女：能讲给我们听听吗？\n男：2003年春节，我在学校练了一年的基本功，急于给大伙儿露一手，自告奋勇要给大家来个奶油菜花。这道菜我没做过，听老师在课堂上提过，觉得没什么难的。结果我进了厨房，一看那一堆菜花和黄油就傻眼了，最后愣是做出一锅大乱炖。菜端上桌，我觉得太丢人了，简直无地自容。亲戚朋友倒是非常捧场，把那道菜吃了个精光。\n女：大伙儿肯定能原谅您，那时候您还是个刚入学一年的学生嘛。\n男：8年以后，我把家里的亲戚朋友召集到一块儿，来了场“雪耻之战”。我当时放下豪言，让大家随便点，想吃什么点什么，他们能想得出的，我都能做。几个小时倒腾出来的十几道菜，当然也得到了大伙儿的一致称赞。\n女：您心里特别美吧？\n男：那就不用说了。\n问：关于奶油菜花，下列哪项正确？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [35, 36]}}, {"n": 10, "zh": "", "options": {"A": "请大家吃了顿最贵的饭", "B": "一顿饭吃了好几个小时", "C": "做的都是大家没吃过的菜", "D": "为8年前的事找回了面子"}, "transcript_zh": "女：能不能告诉我们，您最初怎么选中了厨师这个行业？\n男：我最初选择学厨师，想法很简单，人走到哪里都得吃饭，干这一行肯定饿不着。\n女：后来怎么就做到了五星级酒店的京菜主厨呢？\n男：进了饭店从做小工、刷盘子开始，我越干越觉得，厨师这一行实在是个让人痴迷又魅力无穷的行业。\n女：我们都知道掂大勺、刀功，都是厨师的看家本领，您学艺过程中，最头疼的是什么呢？\n男：记得刚学会做菜那会儿，我是吃到哪儿挑到哪儿，每吃一道菜，都要评头论足，“油放少了”“盐放多了”。后来，我想明白了，同样的调料，不同的人会炒出不同的味儿，就是中餐的精髓。我学做饭那时候，最伤脑筋的就是菜谱上“少许”这俩字，老是分寸把握不好。把这两个字琢磨透了，就可以出师了。\n女：自从您学厨师之后，过年过节，您家的聚餐就成了您露一手的机会了吧？\n男：说到这儿，我就会想起奶油菜花，这道菜给我的教训太深了。\n女：能讲给我们听听吗？\n男：2003年春节，我在学校练了一年的基本功，急于给大伙儿露一手，自告奋勇要给大家来个奶油菜花。这道菜我没做过，听老师在课堂上提过，觉得没什么难的。结果我进了厨房，一看那一堆菜花和黄油就傻眼了，最后愣是做出一锅大乱炖。菜端上桌，我觉得太丢人了，简直无地自容。亲戚朋友倒是非常捧场，把那道菜吃了个精光。\n女：大伙儿肯定能原谅您，那时候您还是个刚入学一年的学生嘛。\n男：8年以后，我把家里的亲戚朋友召集到一块儿，来了场“雪耻之战”。我当时放下豪言，让大家随便点，想吃什么点什么，他们能想得出的，我都能做。几个小时倒腾出来的十几道菜，当然也得到了大伙儿的一致称赞。\n女：您心里特别美吧？\n男：那就不用说了。\n问：8年以后，男的做了件什么事？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [35, 36]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–17题：请选出正确答案。", "items": [{"n": 11, "zh": "", "options": {"A": "“0”表示最轻度的疼痛", "B": "“10”表示最严重的疼痛", "C": "研究者做了70多次手术", "D": "研究对象涉及7000多人"}, "transcript_zh": "音乐是一种有效的止痛剂。有研究报告称，手术前、手术后甚至手术过程中播放音乐，都有助于缓解疼痛。\n本项研究共涉及近7000名患者的70多次临床试验的数据，试验证明，音乐确实是一剂有效的止痛药。实验者把术后疼痛分为0－10级，0代表丝毫不疼，10代表疼到极点，听音乐能够使疼痛等级下降2级。\n研究人员发现，音乐的镇痛作用与音乐类别无关，具体曲目由医生还是由患者选择也无所谓。研究涉及多种手术，但不含大脑或中枢神经系统手术。令人意外的是，患者即便接受全身麻醉，听音乐也有助于缓解术后疼痛，但效果不如接受手术时意识清醒的患者。\n虽然目前尚未将播放音乐作为帮助患者术后康复的常规项目，但这项研究毫无疑问在帮助人们进一步了解音乐的积极影响方面做了有益的探索。\n问：关于试验，下列哪项正确？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [36, 37]}}, {"n": 12, "zh": "", "options": {"A": "音乐减痛更适用于术后康复", "B": "音乐减痛不适用于脑部手术", "C": "音乐减痛对全身麻醉者无效", "D": "任何类型的音乐都可减轻疼痛"}, "transcript_zh": "音乐是一种有效的止痛剂。有研究报告称，手术前、手术后甚至手术过程中播放音乐，都有助于缓解疼痛。\n本项研究共涉及近7000名患者的70多次临床试验的数据，试验证明，音乐确实是一剂有效的止痛药。实验者把术后疼痛分为0－10级，0代表丝毫不疼，10代表疼到极点，听音乐能够使疼痛等级下降2级。\n研究人员发现，音乐的镇痛作用与音乐类别无关，具体曲目由医生还是由患者选择也无所谓。研究涉及多种手术，但不含大脑或中枢神经系统手术。令人意外的是，患者即便接受全身麻醉，听音乐也有助于缓解术后疼痛，但效果不如接受手术时意识清醒的患者。\n虽然目前尚未将播放音乐作为帮助患者术后康复的常规项目，但这项研究毫无疑问在帮助人们进一步了解音乐的积极影响方面做了有益的探索。\n问：关于试验结果，下列哪项正确？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [36, 37]}}, {"n": 13, "zh": "", "options": {"A": "改善医院的氛围", "B": "增加临床的应用", "C": "减少麻醉药的使用", "D": "认识音乐的积极作用"}, "transcript_zh": "音乐是一种有效的止痛剂。有研究报告称，手术前、手术后甚至手术过程中播放音乐，都有助于缓解疼痛。\n本项研究共涉及近7000名患者的70多次临床试验的数据，试验证明，音乐确实是一剂有效的止痛药。实验者把术后疼痛分为0－10级，0代表丝毫不疼，10代表疼到极点，听音乐能够使疼痛等级下降2级。\n研究人员发现，音乐的镇痛作用与音乐类别无关，具体曲目由医生还是由患者选择也无所谓。研究涉及多种手术，但不含大脑或中枢神经系统手术。令人意外的是，患者即便接受全身麻醉，听音乐也有助于缓解术后疼痛，但效果不如接受手术时意识清醒的患者。\n虽然目前尚未将播放音乐作为帮助患者术后康复的常规项目，但这项研究毫无疑问在帮助人们进一步了解音乐的积极影响方面做了有益的探索。\n问：这项研究的意义是什么？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [36, 37]}}, {"n": 14, "zh": "", "options": {"A": "全球一半人不能正确用药", "B": "九成患者安全用药知识匮乏", "C": "45万中国人缺乏正确的用药知识", "D": "大部分被调查者有用药不当的问题"}, "transcript_zh": "据世界卫生组织统计，全球一半患者不会正确用药。在中国，用药安全同样是个不可回避的问题，一项涉及45万份的网络调查显示，九成人存在用药误区。\n比如止痛药，不少人觉得，不管哪里疼痛，吃点儿止痛药，病就好了，这是再简单不过的事了。殊不知，乱用止痛药也会有严重后果，如损伤内脏、延误病情、产生心理依赖，甚至可能致死。再比如创可贴，人人都觉得自己会用，完全不存在专业的问题，可是有多少人知道，它的基本作用只是止血，并不能完全做到抗菌消毒。创可贴吸水性和透气性较差，使用不当可能造成伤口感染。出血较多的伤口、小而深的伤口、动物咬伤、污染较重的伤口、烧伤或者烫伤的创面，都不宜使用创可贴，它只适用于皮肤表面、出血不多而又不需要缝合的小伤口。\n问：关于用药误区，下列哪项正确？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [37]}}, {"n": 15, "zh": "", "options": {"A": "止痛药很难标本兼治", "B": "止痛药的作用不用探讨", "C": "止痛药管用只是虚假现象", "D": "止痛药用法简单无副作用"}, "transcript_zh": "据世界卫生组织统计，全球一半患者不会正确用药。在中国，用药安全同样是个不可回避的问题，一项涉及45万份的网络调查显示，九成人存在用药误区。\n比如止痛药，不少人觉得，不管哪里疼痛，吃点儿止痛药，病就好了，这是再简单不过的事了。殊不知，乱用止痛药也会有严重后果，如损伤内脏、延误病情、产生心理依赖，甚至可能致死。再比如创可贴，人人都觉得自己会用，完全不存在专业的问题，可是有多少人知道，它的基本作用只是止血，并不能完全做到抗菌消毒。创可贴吸水性和透气性较差，使用不当可能造成伤口感染。出血较多的伤口、小而深的伤口、动物咬伤、污染较重的伤口、烧伤或者烫伤的创面，都不宜使用创可贴，它只适用于皮肤表面、出血不多而又不需要缝合的小伤口。\n问：关于止痛药，下列哪项正确？", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [37]}}, {"n": 16, "zh": "", "options": {"A": "抗菌消毒作用很强", "B": "用后伤口不能沾水", "C": "应在医生指导下使用", "D": "使用不当会造成感染"}, "transcript_zh": "据世界卫生组织统计，全球一半患者不会正确用药。在中国，用药安全同样是个不可回避的问题，一项涉及45万份的网络调查显示，九成人存在用药误区。\n比如止痛药，不少人觉得，不管哪里疼痛，吃点儿止痛药，病就好了，这是再简单不过的事了。殊不知，乱用止痛药也会有严重后果，如损伤内脏、延误病情、产生心理依赖，甚至可能致死。再比如创可贴，人人都觉得自己会用，完全不存在专业的问题，可是有多少人知道，它的基本作用只是止血，并不能完全做到抗菌消毒。创可贴吸水性和透气性较差，使用不当可能造成伤口感染。出血较多的伤口、小而深的伤口、动物咬伤、污染较重的伤口、烧伤或者烫伤的创面，都不宜使用创可贴，它只适用于皮肤表面、出血不多而又不需要缝合的小伤口。\n问：关于创可贴，下列哪项正确？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [37]}}, {"n": 17, "zh": "", "options": {"A": "烧伤患者", "B": "烫伤患者", "C": "出血少的伤口", "D": "小而深的伤口"}, "transcript_zh": "据世界卫生组织统计，全球一半患者不会正确用药。在中国，用药安全同样是个不可回避的问题，一项涉及45万份的网络调查显示，九成人存在用药误区。\n比如止痛药，不少人觉得，不管哪里疼痛，吃点儿止痛药，病就好了，这是再简单不过的事了。殊不知，乱用止痛药也会有严重后果，如损伤内脏、延误病情、产生心理依赖，甚至可能致死。再比如创可贴，人人都觉得自己会用，完全不存在专业的问题，可是有多少人知道，它的基本作用只是止血，并不能完全做到抗菌消毒。创可贴吸水性和透气性较差，使用不当可能造成伤口感染。出血较多的伤口、小而深的伤口、动物咬伤、污染较重的伤口、烧伤或者烫伤的创面，都不宜使用创可贴，它只适用于皮肤表面、出血不多而又不需要缝合的小伤口。\n问：创可贴适用哪种情况？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [37]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第18–20题：请选出有语病的一项。", "items": [{"n": 18, "zh": "", "options": {"A": "那所学校的校舍，不是正规的学校。", "B": "他厌恶公文，也不喜欢动笔，当然也没有备忘录。", "C": "他对武术的见解成为了年轻人的座右铭，成为了励志的经典话语。", "D": "它时时提醒我们，不要为歪门邪道所惑，走到无法回头的岔路上去。"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 19, "zh": "", "options": {"A": "你们说一套做一套，言行不一，表里相违，真是岂有此理。", "B": "父亲很生气，说我们跟他说话没有礼貌，一点儿都把他不放在眼里。", "C": "大灾之年，洪水泛滥，它的肆无忌惮给人们带来了无穷的灾害和忧患。", "D": "脸谱以红色代表忠勇，黑色代表粗直，白色代表奸邪，使人物性格一目了然。"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 20, "zh": "", "options": {"A": "最好多做工作，他每天清晨5点多钟就起床，深夜才就寝。他对工作一丝不苟，非常讨厌懒散拖拉的作风。", "B": "现在有些音乐电视越来越吸引不了观众。有的音乐作品还是不错的，可一配上电视就显得画蛇添足、不伦不类了。", "C": "搜索引擎能够帮助我们更快更容易地找到信息，你只需输入一个或几个关键词，搜索引擎就会找到所有符合要求的网页。", "D": "几乎每台文艺晚会都少不了相声节目，演员们幽默的语言、诙谐的表情，逗得观众捧腹大笑。相声已成为流传最广、最为群众喜闻乐见的曲艺形式。"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第21–23题：选词填空。", "items": [{"n": 21, "zh": "在生活世界中，人不是一个________完成的概念，而是一个可选择的概念。人存在________生活，人选择生活就是选择存在方式。选择存在方式就是________自身。", "options": {"A": "预先　即　创作", "B": "父母　和　完善", "C": "事先　将　改变", "D": "社会　亦　激励"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 22, "zh": "幸福是什么？幸福就是看着粮食心里________，不再有饿肚子的恐惧。我知道在农村的很多地方，农民家里都________着很多粮食，看到满仓的粮食，农民的心里就踏实多了。这是很________的想法，但________不是被我们抛弃的真理。", "options": {"A": "平静　储蓄　庸俗　毕竟", "B": "踏实　储存　朴实　未必", "C": "平稳　积聚　机灵　历来", "D": "沉着　常备　难堪　明明"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 23, "zh": "用本族语也好，用外族语也好，一个人在思维的时候总得运用一种语言。学习外语要养成用外语________的习惯。如果没有这种习惯，用外语说话时就得先用本族语把意思想好，________再译成外语说出来。________，说出来的外语就不会流畅、________。", "options": {"A": "思想　接着　如此　正宗", "B": "翻译　后来　当然　专业", "C": "表达　以后　那样　周密", "D": "思维　然后　这样　纯正"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第24–28题：选句填空。\n一户人家要盖房，各种材料堆放在空地上。一根杨木、一根松木并排放在一个角落里，粗大、光滑，仔细看，杨木仿佛更加粗壮一些。\n夜深人静，杨木对松木说起话来。“真高兴，（24）________！看我这粗大的体型一定是主梁！你呢，虽然瘦小一些，也可以做根柱子！”松木说：“付出总有回报，（25）________！”\n第二天，工匠来选木料，师傅敲敲松木说：“这根做主梁！”又看看那根粗大的杨木说：“这根做个拴马桩子吧！”\n夜深人静，杨木又开始说话了：“（26）________，就你那体格，要去做主梁？而我，去做拴马桩子？这世道，还有说理的地方吗！”\n松木说：“孩子！你是比我粗大，（27）________，你却只生长了十几年。我生活的地方风大、缺水，环境恶劣，我们每年只能生长那么一点点，但木质紧密、结实。你生活在水源充足、营养丰富的河湾里，十几年就长得比我粗大了。但是孩子，你的身体是虚的啊！承担不起主梁的责任。”\n听了松木的话，（28）________，下决心要做好一根拴马桩子！", "items": [{"n": 24, "zh": "夜深人静，杨木对松木说起话来。“真高兴，（24）________！看我这粗大的体型一定是主梁！", "options": {"A": "努力和汗水都不会白费", "B": "我们终于成材了", "C": "杨木惭愧得无话可说", "D": "那个匠人真是老糊涂了", "E": "可我已经有上百年的树龄了"}, "picture_desc_en": "black-and-white photo of large peeled logs and square timber beams lying on the ground in a construction/timber yard, a few workers among them", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 25, "zh": "松木说：“付出总有回报，（25）________！”", "options": {"A": "努力和汗水都不会白费", "B": "我们终于成材了", "C": "杨木惭愧得无话可说", "D": "那个匠人真是老糊涂了", "E": "可我已经有上百年的树龄了"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 26, "zh": "夜深人静，杨木又开始说话了：“（26）________，就你那体格，要去做主梁？", "options": {"A": "努力和汗水都不会白费", "B": "我们终于成材了", "C": "杨木惭愧得无话可说", "D": "那个匠人真是老糊涂了", "E": "可我已经有上百年的树龄了"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 27, "zh": "松木说：“孩子！你是比我粗大，（27）________，你却只生长了十几年。", "options": {"A": "努力和汗水都不会白费", "B": "我们终于成材了", "C": "杨木惭愧得无话可说", "D": "那个匠人真是老糊涂了", "E": "可我已经有上百年的树龄了"}, "answer": "E", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 28, "zh": "听了松木的话，（28）________，下决心要做好一根拴马桩子！", "options": {"A": "努力和汗水都不会白费", "B": "我们终于成材了", "C": "杨木惭愧得无话可说", "D": "那个匠人真是老糊涂了", "E": "可我已经有上百年的树龄了"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第四部分（29–32）", "type_zh": "阅读 第四部分", "instruction_zh": "第29–36题：请选出正确答案。\n29–32.\n在床上吃比萨饼和冰激凌不行，边看电视边吃东西也不行，专家提醒人们：尽管很多人喜欢上述就餐习惯，但它对人体健康一点儿好处也没有。就餐的地点和方式与食物一样重要，因为有些环境会诱惑人多吃，有些就餐方式不利于消化。\n有人对办公室、学校、餐馆、路边摊等地方做过比较，结果是餐馆、黑暗的环境以及狼吞虎咽为最差就餐地点和习惯。其理由是餐馆的美味佳肴意味着更多的卡路里，因为餐馆中许多菜品的烹饪手段是过油之后再炒，而且在餐馆进餐往往比在家里吃得更多。\n至于黑暗的环境，主要是在昏暗的光线下，人们更容易无所顾忌地吃，吃得更加没有节制。\n狼吞虎咽就更不可取了，细嚼慢咽有助于消化，可以防止噎着、打嗝和心脏病发作。食物的块头越大越难消化，把食物咀嚼成近似液体状才是标准的进餐方式，因此诸位不管多把时间当回事，也千万不要节省吃饭的那点儿时间。\n专家特别提示，良好的就餐环境可以调动神经、内分泌和新陈代谢等多个系统，会让人感觉到满足从而停止吃东西。", "items": [{"n": 29, "zh": "下列哪个是最差就餐地点？", "options": {"A": "学校", "B": "餐馆", "C": "办公室", "D": "路边摊"}, "picture_desc_en": "black-and-white photo of a man sitting on a bed in a dim room, pointing a remote control forward (at a TV), a bowl of popcorn on a low table beside him", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 30, "zh": "狼吞虎咽的结果可能是：", "options": {"A": "饭量与日俱增", "B": "食物消化得更快", "C": "体味不出食物之美", "D": "严重时可引发心脏病"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 31, "zh": "画线词语“把时间当回事”的意思最可能是：", "options": {"A": "在意时间", "B": "浪费时间", "C": "算计时间", "D": "消磨时间"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 32, "zh": "关于就餐，专家特别提示：", "options": {"A": "食品质量是最重要的", "B": "应高度重视就餐环境", "C": "吃饭时应该专心致志", "D": "吃饭不要吃撑再停止"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第四部分（33–36）", "type_zh": "阅读 第四部分", "instruction_zh": "33–36.\n初见刘岩，舞者的气质自然流淌，纵使多年前的那次意外让她不能再用灵巧的足尖走近你，你却仍然第一眼就会认定这是一位顶尖的舞者。笑容妩媚却豁达，声音温柔而坚定，哪怕是坐在轮椅上，你也要赞叹她长歌善舞的风采。\n刘岩表示，《手之舞之》是一本学术著作，英文版的推出更是意义非凡，可以让全世界更加了解中国舞蹈文化。在世界范围内，中国的手舞研究学术性强，传承多样，在丰厚的古典文化滋润中，手舞作为微身体语言舞蹈，可以通过整体与局部来实现情感的沟通与表达。\n刘岩既是一名舞者，也是一名教育者，还是一名理论研究者，而她最在意的是教师身份，坚持一线教学，培养青年人才，是她的快乐所在。\n2010年，她以自己的名字命名成立了“刘岩文艺专项基金”，一直投身社会公益，关注贫困、孤残儿童的艺术教育。她告诉我们：“专项基金成立以后，每周末都会资助老师走到儿童福利机构去给那些孤儿或聋哑孩子上课，虽然困难很多，但当你去帮助了那些需要帮助的人时，快乐和温暖会充满每个人的内心，最重要的是孩子们从中收获了欢乐。”", "items": [{"n": 33, "zh": "根据上文，刘岩：", "options": {"A": "善于倾听", "B": "憎恶虚伪", "C": "豁达乐观", "D": "为人严肃"}, "picture_desc_en": "black-and-white photo of a smiling woman dancer in a dark long-sleeved top raising both arms gracefully above her head in front of a banner with English text (…International Sports Film We… / …World FICTS Challenge 2012)", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 34, "zh": "《手之舞之》英文版的意义在于：", "options": {"A": "是第一本英文舞蹈学术专著", "B": "着眼于中国古典文化的传播", "C": "创造了中国微身体语言舞蹈", "D": "帮助世界了解中国舞蹈文化"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 35, "zh": "根据上文，可以知道：", "options": {"A": "刘岩在福利机构工作", "B": "刘岩很重视培养年轻人", "C": "刘岩每天生活在快乐之中", "D": "刘岩的基金更倾向于资助老师"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 36, "zh": "最适合做上文标题的是：", "options": {"A": "舞者刘岩", "B": "著名作家刘岩", "C": "孤残儿童的好老师", "D": "她在探测生命的意义"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}], "answers_ref": {"book": "workbook_answers", "pages": [34, 35, 36, 37, 94, 95, 96, 97, 98, 99, 100]}}, "unclear": ["HSK6-д багшийн ном байхгүй тул teacher талбар орхисон. Дасгалын номын хариулт/бичвэр BLCUP 录音文本及答案 (HSK6 下Recording Text.pdf х.34–38), сурах бичгийн хариулт 课本参考答案 (HSK6 下Answer Textbook.pdf х.16–18)-аас. Дасгалын номын 阅读 (18–36) хариулт эдгээр эх сурвалжийн алинд ч хэвлэгдээгүй тул оруулаагүй, unclear-д тэмдэглэв.", "Аудио файлын нэр мэдэгдэхгүй тул audio талбар орхисон. Сурах бичгийн CD тэмдэг: 课文 = 29-1, 生词 = 29-2; дасгалын номын 听力 第一部分 = 29-1, 第二部分 = 29-2, 第三部分 = 29-3.", "Хичээлийн гарчгийн пиньинь (title_pinyin) номд хэвлэгдээгүй — «“Xiào” de bèiwànglù» гэж 备忘录-ийн 生词 пиньинь (bèiwànglù) + стандарт дуудлагаар бичсэн (гарчиг бүхлээрээ номоос биш). title_en номын гарчгийн доорх «A memorandum of laughing».", "课文 — нэг «课文 “笑”的备忘录（1154字）» гарчиг, нэг аудио (29-1), нэг 生词 жагсаалт (29-2, 1–52) дор хоёр дэд гарчигтай хэсэг: «（一）大脑能“听”出笑声的真假» ба «（二）笑未必是最佳良药». 练习5 «课文（一）/课文（二）», 运用 «两篇小短文…把两篇课文各缩写» гэж тусад нь авч үздэг тул texts-ийг n=1, n=2 гэж хоёр хуваав (title_zh-д дэд гарчиг, «（一）/（二）» дугааргүй). 生词-ийг анх гарсан хэсгээр нь хуваав: 1–29 → text 1, 30–52 → text 2 (дугаарлалт номынхоор тасралтгүй). Пиньинь бичвэр хэвлэгдээгүй → lines.pinyin байхгүй.", "课文 тэмдэгтийн тоо: номд «1154字». lines-ийн цэг таслалтай нийт тэмдэгт = 1133 (цифр тус бүрийг 1 гэж), зөвхөн ханз = 1012; дэд гарчиг хоёр (20 тэмдэгт) + зүүлтийн тэмдэг «①» (1) нэмбэл 1154 = 1154 — номын тоотой яг таарч байна (бичвэрийг 250dpi зургаар мөр мөрөөр тулгасан).", "Догол мөр эхлэх мөрийн дугаар (1-ээс): text1 [1, 7, 11], text2 [1, 2, 4, 6]. Text2-ын эхний догол «中国人喜欢听相声，因为它逗笑。» — ганц өгүүлбэртэй тусдаа догол.", "课文-д 1 зүүлтийн (脚注) тэмдэг: «燃烧掉2000卡路里①» (课文（二）3-р догол). lines-д «①»-ийг оруулаагүй (бичвэр цэвэр, L10/L13 жишгээр). Зүүлтийн бичвэр (PDF х.98 доод хэсэг) textbook.culture {title_zh:«课文脚注»}-д бүтнээр; «［法calorie］» номд байгаагаар. 文化/俗语 хэсэг байхгүй.", "课文-ийн доор эх сурвалж: «分别改编自《参考消息》同名文章» — схемд талбаргүй тул энд тэмдэглэв (lines-д оруулаагүй). 课文（一）-ийн доор зураг: инээмсэглэж буй эмэгтэйн нүүрний (хамар, уруул, шүд) ойрын зураг.", "生词 52 үг (1–52) + 11 装聋装哑-ийн доор дугааргүй дэд үг «聋哑 lóngyǎ adj. deaf and dumb» — L23 жишгээр new_words-д n=11-ээр тусад нь оруулав (validator «дугаар тасархай» гэж анхааруулж болно). * тэмдэгтэй: зөвхөн 26 直觉. Үгийн ай (pos) хэвлэгдээгүй: 2 岂有此理, 11 装聋装哑, 12 画蛇添足, 21 一丝不苟, 24 一目了然, 42 肆无忌惮, 46 恰到好处. Пиньинь номд байгаагаар: 2 «qǐyǒucǐlǐ» (зураасгүй), 11 «zhuānglóng zhuāngyǎ» (зайтай), 50 «qǐ hòng» (зайтай); 12 «huàshé-tiānzú», 21 «yìsī-bùgǒu», 24 «yímù-liǎorán», 42 «sìwú-jìdàn», 46 «qiàdào-hǎochù» (зураастай); 13 机灵 «jīling», 30 相声 «xiàngsheng», 45 分寸 «fēncun» (хөнгөн хөг). 12-ын англи тайлбар «to paint a snake with feet—superfluous» (зураастай) номд байгаагаар.", "练习5 课文（一） 2-р мөрийн сануулга «④志愿者的反映» гэж хэвлэгдсэн — 课文-д «大脑的反应» (反应); номд байгаагаар, засаагүй. 练习5 — хоёр хүснэгт (课文（一）3 мөр, 课文（二）3 мөр; асуулт | сануулга); items.zh-д «课文（一）：…» угтвартай, hint_zh-д ①②③④ номын дугаартай (课文（二）-ын сануулгад дугаар байхгүй).", "热身1 — шар дэвсгэр дээрх мод-диаграм (дээд талд инээмсэглэсэн шар smiley; 2 салаа: «你根据什么分辨真笑、假笑？» → 表情／声音／其他; «笑是否有益于健康？» → 益处／害处), warmup[0].items-д «асуулт | дэд хайрцагнууд» гэж. 热身2 — 4 мөрт хүснэгт (表／违／活／隐 | үгс).", "注释 (一) 综合注释 2 зүйл (预先、……也好，……也罢) → grammar 1–2; (二) 词语辨析 诸——各 (дугааргүй хайрцаг) хүснэгтийг grammar 3 (explanation_zh + structure_rows; «不同点» 2, 3-р мөрөнд 诸 баганын нүд тайлбар ба жишээний мөрийг хамарсан нэгтгэсэн нүд тул жишээний мөрөнд «（同上）» гэж тэмдэглэв); (三) 篇章修辞 修辞（6）设问 (дугааргүй хайрцаг) → grammar 4. Номын улаан өнгөөр хэвлэгдсэн жишээ = 课文-ийн өгүүлбэр → note_zh «课文句» (预先 (3), 也好也罢 (1), 设问 (1)(2)). Хүснэгтийн жишээнд 诸/各 хөх өнгөөр тодотгогдсон.", "注释2 ……也好，……也罢 — хувилбар хэлбэрүүд тайлбар дотор хэвлэгдсэн; structure_rows-д мөр мөрөөр давтсан. 练一练-ийн заавар номд «用“……也好 / 也罢，……也好 / 也罢”或者“……也好，……也罢”改写句子» (налуу зураас «/» зайтай) — «／» болгосон. 练一练 1–3 болон 设问 练一练 1–3, 练习2 1–6 — өгүүлбэр бүрийн доор хоосон мөр (+«。») → zh-д «\\n________。». 诸——各 做一做 — өгүүлбэр бүрийн төгсгөлд хоосон хаалт «（　　）».", "设问 тайлбарт «例（2）就使语义的转折过渡自然而简练» — «例（2）» номын өөрийн жишээ дугаар. Жишээ (1) нь 课文-ийн эхний хоёр өгүүлбэр, гэхдээ «真是岂有此理，» хэсэггүйгээр эхэлдэг — номд байгаагаар.", "练习1 模仿例子: доогуур цэгтэй ханз — 例 实质 (质), 档次 (档), 回避 (避), 周密 (周), 提炼 (提); hint_zh-д. Жишээ мөр «实质：本质　性质　品质　素质» номд хэвлэгдсэн (n=«例»).", "练习3 选词填空: 2 догол бичвэр, тус бүр 5 хоосон зай + өөрийн 5 үгийн сан (word_bank 2 бүлэг, hint_zh-д давтсан). 练习4 «请给下面的问句选择对应的答句并连线» — зүүн багана 问句 ①–④, баруун багана 答句 A–D; options-д A–D-г item бүрт давтсан. Энэ дасгалын өгүүлбэрүүд (竺可桢、文明、植物、雪中何以赠君别) энэ хичээлийн 课文-тэй холбоогүй мэт (设问 сэдэвт) — номд байгаагаар.", "扩展 — «词汇 （1）熟悉下列近义词» 16 хос (номд 2 багана × 8 мөр, PDF х.104–105; мөрөөр уншсан дараалал: зүүн хос → баруун хос) ба «（2）将下列政治方面的词语与其对应的意思连线» (4 үг: 统治、时事、条约、纲领; 4 тайлбар баруун баганад номд дугааргүй — options-д номын дарааллаар 1–4 түлхүүр өгсөн, энэ нь номын дугаар биш). Энэ хичээлд 做一做 байхгүй. Номд 运用 (写一写) нь 扩展-ийн ӨМНӨ (PDF х.104) хэвлэгдсэн.", "运用 — зөвхөн «写一写» (хоёр 课文-ийг тус бүр 200 орчим ханзаар 缩写).", "Дасгалын ном (PDF х.79–86) — 听力 1–17 + 阅读 18–36, нийт 36 асуулт. Энэ хичээлд 三、书写 хэсэг байхгүй (дараагийн хуудас х.87 = 第30课).", "Дасгалын ном 20A «最好多做工作，他每天清晨5点多钟就起床…» — 400dpi-аар томруулж шалгасан, номд байгаагаар. 21-д хоёр дахь хоосон зай мөр дамжин тасарсан («人存在__ / ______生活») — нэг «________» болгов. 21–23 сонголт бүр 3–4 үгийн багц — options-д «　» (бүтэн өргөнтэй зай)-гаар холбосон. Цифр ба ханзны хоорондох зай («2 人», «6 年», «5 点», «70 多次», «45 万», «8 年») хасав.", "Дасгалын ном 阅读 24–28: бичвэр section.instruction_zh-д, сонголт A–E бүх item-д давтсан; бичвэрийн хажууд зураг (модон дүнз/дам нуруу хэвтэж буй талбай, ажилчид). Номд «柱子!”», «吗!”» гэх мэт зарим «!» хагас өргөнтэй мэт — бүтэн өргөнтэй «！» болгосон. Номд «（25）________！ ”» ойр зайтай хэвлэгдсэн.", "Дасгалын ном 阅读 29–32 бичвэрт «把时间当回事» доогуур зураастай хэвлэгдсэн (31-р асуултын «画线词语»); хажууд харанхуй өрөөнд орон дээр суугаад телевизийн удирдлага барьсан эрэгтэй, ширээн дээр попкорн. 33–36 — хажууд гараа толгой дээгүүр өргөсөн бүжигчин эмэгтэйн зураг (ард нь «…International Sports Film We… / …World FICTS Challenge 2012» бичигтэй). 29–36 нэг заавар («第29–36题») — хоёр бичвэрийг тус тусын section-д (29–32, 33–36).", "Дасгалын номын 二、阅读 (18–36) — BLCUP 录音文本及答案 (HSK6 下Recording Text.pdf х.34–38)-д зөвхөн 听力 1–17-ийн хариулт хэвлэгдсэн, 阅读-ийн хариулт (18–36) энэ товхимолд ч, сурах бичгийн 课本参考答案 (HSK6 下Answer Textbook.pdf)-д ч байхгүй тул answer/answer_ref нэмээгүй.", "扩展2 (统治/时事/条约/纲领 холбох дасгал): 课本参考答案 (х.18) дээр 4 нэр томьёо, 4 тайлбарыг холбосон зураас (X хэлбэрээр гуйвуулсан) хэвлэгдсэн; тайлбарын хэвлэгдсэн дараалал нь толгой үгийн дараалалтай давхцахгүй (эргэлдсэн). Толь бичгийн утгаар (болон зурааснуудыг зурагт тулгаж) тодорхойлов: 统治→4 (凭借政权来控制、管理国家或地区), 时事→1 (最近一段时间的国内外大事), 条约→2 (国家和国家签订…义务的文书), 纲领→3 (政府、政党、社团…行动步骤) — эдгээр нь source.json-ийн items[*].options-ийн түлхүүр дугаартай тохирно.", "Дасгалын номын 阅读 18–36-ийн хариултыг BLCUP 录音文本及答案 (HSK6下 Recording Text.pdf) төгсгөлийн нэгдсэн 参考答案 хүснэгт (х.94–100)-ээс нэмсэн; 听力 1–17-ийн inline хариулттай тулгасан."], "verified_pages": [95, 96, 97, 98, 99, 100, 101, 102, 103, 104, 105, 79, 80, 81, 82, 83, 84, 85, 86], "schema_version": 1}'::jsonb, 1, 'image_verified')
