insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk6-l33', 'hsk6', 'HSK6B', 33, '怀念慢生活', 'Huáiniàn màn shēnghuó', 'Cherishing the memory of slow life', '{"level": "hsk6", "lesson": 33, "book": "HSK6B", "title_zh": "怀念慢生活", "title_pinyin": "Huáiniàn màn shēnghuó", "title_en": "Cherishing the memory of slow life", "textbook": {"ref": {"book": "textbook", "pages": [137, 138, 139, 140, 141, 142, 143, 144, 145]}, "warmup": [{"instruction_zh": "现在你的生活节奏怎么样？你是不是被紧张的生活所困扰？请对照下表看看有没有跟自己一样的情况，你认为应该怎么解决这种状况？", "instruction_en": "Warm-up", "items": ["你每天的生活紧张吗？ | 是/否", "你常常觉得累吗？ | ________", "你的情绪怎么样？容易生气和着急吗？ | ________", "你最近压力大吗？ | ________", "如果你每天很紧张、很累、压力很大、情绪变坏，你该怎么办？（两栏合并）"], "pictures_desc_en": ["a young woman with long curly hair screaming in frustration, holding a small spiral notepad and a pen; to her right the yes/no table of questions"]}, {"instruction_zh": "想一想下列词语之间有什么联系。", "items": ["速 | 速度、时速、匀速、车速、超速、风速、高速、光速、航速、音速、转速、加速、减速、变速", "终 | 终点、终场、终极、终结、终止、年终、期终、始终、最终、有始有终", "威 | 威风、威力、威名、威望、威武、威信、威严、权威、示威、八面威风", "源 | 电源、财源、根源、光源、货源、来源、能源、热源、资源、起源、本源、渊源、源流"]}], "texts": [{"n": 1, "title_zh": "怀念慢生活", "title_en": "Cherishing the memory of slow life", "kind": "narrative", "lines": [{"zh": "为期三天的假期，我和儿时的好友结伴去西安旅行。"}, {"zh": "去时乘高铁①，车程6小时。"}, {"zh": "列车缓缓离开了车站，很快就以征服一切的气势甩开窗外的景致，以300公里的时速跨过了桥梁，穿越了平原。"}, {"zh": "车窗外，模糊的景象夹杂着西北②的风沙呼啸而过。"}, {"zh": "坐在宽敞座椅中的人们，享受着齐全的软硬件设施，看电影的看电影，打电话的打电话，更多的则是把自己封闭在小小的手机屏幕中，不是用语言，而是用符号传递着各自的情感。"}, {"zh": "寄情于虚拟世界的网迷们对喧哗的现实流露出的是不屑一顾的冷淡。"}, {"zh": "伴随着“终点站到了”的广播，我和朋友像千千万万旅途中的人们一样，没等车停稳，就兴冲冲地守候在车门口，迫不及待地投入到西安滚滚的人流中。"}, {"zh": "三天的旅行很快就结束了，我们回程坐特快，将近13个小时的硬座③。"}, {"zh": "列车没有了高铁的威风，不紧不慢地开出了车站，不温不火地匀速前行，仿佛知道一路上将会演绎出许许多多的故事。"}, {"zh": "不久我就发现硬座车厢信号很差无法上网；灯光昏暗无法看书；没有电源，耗尽了电量的手机无法充电；人多嘈杂混乱得睡不着觉，闭塞的车厢里，我们像是回到了50年前。"}, {"zh": "朋友忽然说：“其实有时候吧，我还挺喜欢这种感觉的，只有这时候，人和人之间才有种久违的亲近感，也许是因为我们手头都没有事情，愿意彼此分享和倾听。”"}, {"zh": "之后发生的一切，都像是在证明朋友的话是对的。"}, {"zh": "昏暗的灯光下，我和朋友开始聊天儿。"}, {"zh": "她讲起小学的时候，班里颇具正义感的女生李芳芳如何见义勇为，在洪水中英勇救人；我感叹初中时，班里那个贵族气十足的男生，他叫……唉，一时竟忘了他叫什么名字。"}, {"zh": "他16岁到了农村，从播种开始学习，后来长成了个精壮的汉子，改革开放后第一批承包了土地，就此发家致富，他简直就是一代人中的奇迹。"}, {"zh": "我们想起小学的地理老师，讲课的时候总会带出些方言，班里调皮的男生千方百计跟她捣乱，弄得老师狼狈不堪，那会儿的我们真是幼稚得可笑。"}, {"zh": "还有，中学我们班那个料事如神的诸葛亮……"}, {"zh": "火车上，我们边回忆边开心地笑着，好像很久很久都没有这么纯粹地开心过了。"}, {"zh": "说笑累了，朋友看着窗外，我则观察着周围的人们。"}, {"zh": "坐我对面的像是一对双胞胎姐弟，他们正在聊家常。"}, {"zh": "姐姐轻声细语，回顾着陈年往事：改革开放后的第一年，弟弟考上了大学，瞬间，这消息成了方圆百里的爆炸性新闻。"}, {"zh": "那一年过春节弟弟在学校没回家，家里节过得别提多冷清了，对联都懒得贴。"}, {"zh": "虽然弟弟写信来拜年，可全家都觉得没了天伦之乐。"}, {"zh": "那一年除夕、元宵节，不，是整个正月都过得没了生气，爸妈大年初一连寺庙都懒得去，天天感叹孩子翅膀硬了就要飞了，眼神中流露着失落。"}, {"zh": "隔着过道坐着一对新婚的夫妇，新郎新娘一边给大家分发喜糖，一边说他们是旅行结婚的，顿时，整节车厢都热闹起来了，有人提议新郎新娘唱支歌，大家立刻鼓掌响应，那新郎一看就是个老实人，脸憋得通红，说他是社区物业干维修的，就会干活儿，不会唱歌，不过他媳妇不光贤惠，歌也唱得好，就让媳妇代表了，果然新娘张嘴就惊动了整节车厢，掌声、赞美声响成一片，现场简直就像联欢会一样，而我们对面角落里坐着的漫画家，早就用画笔记录下了眼前的一切。"}, {"zh": "……"}, {"zh": "我和朋友不由得感叹，现代交通的确高效，人们随意打发着路上的时间，仓促间投入目的地的怀抱，早就忘了其实沿途的风景也是旅途的一部分，人和人之间无拘无束的交流也是人生最宝贵的财富。"}, {"zh": "若不如此，我们又怎么会读到古人在那一束月光，一叶小舟，或者在那青山绿水间所寄托的情感呢！"}], "new_words": [{"n": 1, "zh": "为期", "pinyin": "wéiqī", "pos": "v.", "en": "for a period of, for a term of", "text": 1}, {"n": 2, "zh": "征服", "pinyin": "zhēngfú", "pos": "v.", "en": "to conquer", "text": 1}, {"n": 3, "zh": "桥梁", "pinyin": "qiáoliáng", "pos": "n.", "en": "bridge", "text": 1}, {"n": 4, "zh": "平原", "pinyin": "píngyuán", "pos": "n.", "en": "plain", "text": 1}, {"n": 5, "zh": "夹杂", "pinyin": "jiāzá", "pos": "v.", "en": "to be mixed up with", "text": 1}, {"n": 6, "zh": "呼啸", "pinyin": "hūxiào", "pos": "v.", "en": "to roar, to howl", "text": 1}, {"n": 7, "zh": "宽敞", "pinyin": "kuānchang", "pos": "adj.", "en": "spacious", "text": 1}, {"n": 8, "zh": "齐全", "pinyin": "qíquán", "pos": "adj.", "en": "complete", "text": 1}, {"n": 9, "zh": "封闭", "pinyin": "fēngbì", "pos": "v.", "en": "to close, to seal", "text": 1}, {"n": 10, "zh": "符号", "pinyin": "fúhào", "pos": "n.", "en": "symbol, sign", "text": 1}, {"n": 11, "zh": "喧哗", "pinyin": "xuānhuá", "pos": "adj.", "en": "tumultuous, noisy", "text": 1}, {"n": 12, "zh": "不屑一顾", "pinyin": "búxiè yígù", "en": "to not spare a glance for", "text": 1}, {"n": 13, "zh": "威风", "pinyin": "wēifēng", "pos": "n.", "en": "panache, awe-inspiring bearing", "text": 1}, {"n": 14, "zh": "演绎", "pinyin": "yǎnyì", "pos": "v.", "en": "to interpret, to act out", "text": 1}, {"n": 15, "zh": "电源", "pinyin": "diànyuán", "pos": "n.", "en": "power supply", "text": 1}, {"n": 16, "zh": "闭塞", "pinyin": "bìsè", "pos": "adj.", "en": "occluded, blocked", "text": 1}, {"n": 17, "zh": "久违", "pinyin": "jiǔwéi", "pos": "v.", "en": "long-lost, long-awaited", "star": true, "text": 1}, {"n": 18, "zh": "正义", "pinyin": "zhèngyì", "pos": "adj.", "en": "just, righteous", "text": 1}, {"n": 19, "zh": "见义勇为", "pinyin": "jiànyì-yǒngwéi", "en": "to do boldly what is righteous", "text": 1}, {"n": 20, "zh": "洪水", "pinyin": "hóngshuǐ", "pos": "n.", "en": "flood", "text": 1}, {"n": 21, "zh": "英勇", "pinyin": "yīngyǒng", "pos": "adj.", "en": "heroic, brave", "text": 1}, {"n": 22, "zh": "贵族", "pinyin": "guìzú", "pos": "n.", "en": "noble, aristocrat", "text": 1}, {"n": 23, "zh": "播种", "pinyin": "bō zhǒng", "pos": "v.", "en": "to sow", "text": 1}, {"n": 24, "zh": "承包", "pinyin": "chéngbāo", "pos": "v.", "en": "to contract (with)", "text": 1}, {"n": 25, "zh": "方言", "pinyin": "fāngyán", "pos": "n.", "en": "dialect", "text": 1}, {"n": 26, "zh": "捣乱", "pinyin": "dǎo luàn", "pos": "v.", "en": "to make trouble", "text": 1}, {"n": 27, "zh": "狼狈", "pinyin": "lángbèi", "pos": "adj.", "en": "in a mess, in a difficult position", "text": 1}, {"n": 28, "zh": "幼稚", "pinyin": "yòuzhì", "pos": "adj.", "en": "childish, naïve", "text": 1}, {"n": 29, "zh": "双胞胎", "pinyin": "shuāngbāotāi", "pos": "n.", "en": "twins", "text": 1}, {"n": 30, "zh": "家常", "pinyin": "jiācháng", "pos": "n.", "en": "the daily life of a family", "text": 1}, {"n": 31, "zh": "回顾", "pinyin": "huígù", "pos": "v.", "en": "to review, to look back on", "text": 1}, {"n": 32, "zh": "往事", "pinyin": "wǎngshì", "pos": "n.", "en": "the past", "text": 1}, {"n": 33, "zh": "方圆", "pinyin": "fāngyuán", "pos": "n.", "en": "surrounding area", "text": 1}, {"n": 34, "zh": "爆炸", "pinyin": "bàozhà", "pos": "v.", "en": "to explode, to go off, to blow up", "text": 1}, {"n": 35, "zh": "对联", "pinyin": "duìlián", "pos": "n.", "en": "couplet", "text": 1}, {"n": 36, "zh": "拜年", "pinyin": "bài nián", "pos": "v.", "en": "to pay a New Year call", "text": 1}, {"n": 37, "zh": "天伦之乐", "pinyin": "tiānlúnzhīlè", "en": "the happiness of a family union", "text": 1}, {"n": 38, "zh": "元宵节", "pinyin": "Yuánxiāo Jié", "pos": "n.", "en": "the Lantern Festival", "text": 1}, {"n": 39, "zh": "正月", "pinyin": "zhēngyuè", "pos": "n.", "en": "the first month of the lunar year", "text": 1}, {"n": 40, "zh": "寺庙", "pinyin": "sìmiào", "pos": "n.", "en": "temple", "text": 1}, {"n": 41, "zh": "眼神", "pinyin": "yǎnshén", "pos": "n.", "en": "expression in one’s eyes", "text": 1}, {"n": 42, "zh": "新郎", "pinyin": "xīnláng", "pos": "n.", "en": "bridegroom", "text": 1}, {"n": 43, "zh": "新娘", "pinyin": "xīnniáng", "pos": "n.", "en": "bride", "text": 1}, {"n": 44, "zh": "响应", "pinyin": "xiǎngyìng", "pos": "v.", "en": "to respond", "text": 1}, {"n": 45, "zh": "社区", "pinyin": "shèqū", "pos": "n.", "en": "community, residential community", "text": 1}, {"n": 46, "zh": "物业", "pinyin": "wùyè", "pos": "n.", "en": "property, real estate", "text": 1}, {"n": 47, "zh": "媳妇", "pinyin": "xífu", "pos": "n.", "en": "wife", "text": 1}, {"n": 48, "zh": "贤惠", "pinyin": "xiánhuì", "pos": "adj.", "en": "(of a woman) virtuous", "text": 1}, {"n": 49, "zh": "惊动", "pinyin": "jīngdòng", "pos": "v.", "en": "to shock, to startle", "text": 1}, {"n": 50, "zh": "现场", "pinyin": "xiànchǎng", "pos": "n.", "en": "site, spot", "text": 1}, {"n": 51, "zh": "联欢", "pinyin": "liánhuān", "pos": "v.", "en": "to get together, to party", "text": 1}, {"n": 52, "zh": "漫画", "pinyin": "mànhuà", "pos": "n.", "en": "cartoon, comics", "text": 1}, {"n": 53, "zh": "仓促", "pinyin": "cāngcù", "pos": "adj.", "en": "hasty, hurried", "text": 1}, {"n": 54, "zh": "无拘无束", "pinyin": "wújū-wúshù", "en": "unrestrained, unfettered", "text": 1}, {"n": 55, "zh": "拘束", "pinyin": "jūshù", "pos": "v.", "en": "to restrain, to restrict", "text": 1}, {"n": 56, "zh": "束", "pinyin": "shù", "pos": "m.", "en": "beam", "text": 1}, {"n": 57, "zh": "舟", "pinyin": "zhōu", "pos": "n.", "en": "boat", "text": 1}]}], "grammar": [{"n": 1, "title_zh": "A的A，B的B", "title_en": "（一）综合注释", "explanation_zh": "“A的A，B的B”格式，表示对某一事物几种情况的列举，用于口语。", "examples": [{"n": 1, "zh": "进了果园，大家看到一树的桃，红的红，绿的绿，漂亮极了。"}, {"n": 2, "zh": "坐在宽敞座椅中的人们，享受着齐全的软硬件设施，看电影的看电影，打电话的打电话……", "note_zh": "课文句"}, {"n": 3, "zh": "信号灯变绿了，前面的汽车还是不走，后面一长串汽车的司机按喇叭的按喇叭，探头的探头。"}], "practice_instruction_zh": "练一练：请把下列6个小句组合成3个连贯的语段", "practice": [{"n": "（1）（2）（3）", "zh": "（1）________　（2）________　（3）________", "options": {"A": "那一年，爸爸病了，爷爷奶奶年岁已高，我们姐弟年龄还小", "B": "玩儿了一天，大家饿的饿，渴的渴", "C": "迫不及待地想吃顿可口的饭菜", "D": "晚会上，大家唱的唱，跳的跳", "E": "一家子老的老，小的小，病的病，妈妈愁得不得了", "F": "高兴得不得了"}, "answer": "（1）AE　（2）BC　（3）DF", "answer_ref": {"book": "textbook_answers", "pages": [24]}}]}, {"n": 2, "title_zh": "一时", "title_en": "（一）综合注释", "explanation_zh": "“一时”做副词时，主要意思有两个。\n■ 表示行为临时、偶然或突然地发生。\n■ 重复使用，表示不同行为交替发生。跟“时而”相同。", "examples": [{"n": 1, "zh": "我感叹初中时，班里那个贵族气十足的男生，他叫……唉，一时竟忘了他叫什么名字。", "note_zh": "表示行为临时、偶然或突然地发生；课文句"}, {"n": 2, "zh": "接到丈夫病危的电话，她一时心急，连门都没有锁，就冲出家门，直奔医院而去。", "note_zh": "表示行为临时、偶然或突然地发生"}, {"n": 1, "zh": "他吃了药，好些了，身上一时冷，一时热的情况没有了。", "note_zh": "重复使用，表示不同行为交替发生"}, {"n": 2, "zh": "高原上天气变化大，一时太阳当空，一时阴雨绵绵是常有的事。", "note_zh": "重复使用，表示不同行为交替发生"}], "practice_instruction_zh": "练一练：给“一时”选择适当的位置", "practice": [{"n": 1, "zh": "见了面A觉得似曾相识，B可C又记不起来D在哪儿见过。", "answer": "C", "answer_ref": {"book": "textbook_answers", "pages": [24]}}, {"n": 2, "zh": "A他一不留神，B从台阶上重重地C摔了下来，D动弹不得。", "answer": "D", "answer_ref": {"book": "textbook_answers", "pages": [24]}}, {"n": 3, "zh": "买房子是A大事，B要考虑清楚，可C不能凭D冲动。", "answer": "D", "answer_ref": {"book": "textbook_answers", "pages": [24]}}]}, {"n": 3, "title_zh": "现场——当场", "title_en": "（二）词语辨析", "explanation_zh": "（二）词语辨析 现场——当场\n共同点：都有“在发生某事的时候和场所”的意思。如：他现场/当场把这种新的技术演示了一次。\n不同点：\n现场——1. 名词，直接进行生产、演出、比赛、试验等的场所，强调地方。后边可以带名词。如：现场参观/现场演出/现场直播/现场会议　2. 发生案件、事故或自然灾害的场所以及该场所当时的状况。如：地震过后，现场一片狼藉。\n当场——1. 副词，就在那个地方和那个时候，强调时机。后边只能跟动词。如：当场出丑/当场抓获/当场死亡　2. 没有左边这个用法。", "structure_rows": [" | 现场 | 当场", "共同点 | 都有“在发生某事的时候和场所”的意思。（两栏合并）", "共同点 | 如：他现场/当场把这种新的技术演示了一次。（两栏合并）", "不同点 | 1. 名词，直接进行生产、演出、比赛、试验等的场所，强调地方。后边可以带名词。 | 1. 副词，就在那个地方和那个时候，强调时机。后边只能跟动词。", "不同点 | 如：现场参观/现场演出/现场直播/现场会议 | 如：当场出丑/当场抓获/当场死亡", "不同点 | 2. 发生案件、事故或自然灾害的场所以及该场所当时的状况。 | 2. 没有左边这个用法。（右栏两行合并）", "不同点 | 如：地震过后，现场一片狼藉。 | （同上）"], "examples": [{"n": 1, "zh": "他现场/当场把这种新的技术演示了一次。", "note_zh": "共同点"}, {"n": 2, "zh": "现场参观/现场演出/现场直播/现场会议", "note_zh": "不同点 现场1"}, {"n": 3, "zh": "地震过后，现场一片狼藉。", "note_zh": "不同点 现场2"}, {"n": 4, "zh": "当场出丑/当场抓获/当场死亡", "note_zh": "不同点 当场1"}], "practice_instruction_zh": "做一做：选择“现场”或“当场”填空", "practice": [{"n": 1, "zh": "昨天公司被偷了，警察要求保护________，以便取证。", "answer": "现场", "answer_ref": {"book": "textbook_answers", "pages": [24]}}, {"n": 2, "zh": "昨天那里发生了严重的交通事故，司机________死亡了。", "answer": "当场", "answer_ref": {"book": "textbook_answers", "pages": [24]}}, {"n": 3, "zh": "终于看到了我喜爱的明星的________演唱会。", "answer": "现场", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 4, "zh": "大家都吓坏了，小王甚至________哭出了声。", "answer": "当场", "answer_ref": {"book": "textbook_answers", "pages": [25]}}]}, {"n": 4, "title_zh": "修辞（9）借代", "title_en": "（三）篇章修辞", "explanation_zh": "（三）篇章修辞 修辞（9）借代\n不直说某一事物的名称，而是借用另一种说法来表现，在修辞手法中叫借代。例（1）中就是把“我们班那个料事如神的同学”直接称作“诸葛亮”。", "examples": [{"n": 1, "zh": "还有，中学我们班那个料事如神的诸葛亮……", "note_zh": "（“诸葛亮”是三国时代著名人物，有智慧，且能在事前准确地预料到事情的结果，在中国人民心中已成了智慧的代称，例子中用来代替“料事如神的同学”）；课文句"}, {"n": 2, "zh": "这个小眼镜就是我的儿子。", "note_zh": "（用小眼镜借代“戴着小眼镜的人”）"}, {"n": 3, "zh": "汽车停下来，等待放了学的小黄帽们过马路。", "note_zh": "（用小黄帽借代“戴着小黄帽的小学生”）"}], "practice_instruction_zh": "练一练：下面句子中，每句带下划线的词中都有一个不属于借代，请指出", "practice": [{"n": 1, "zh": "大胡子边说话边乐呵呵地朝我走来。", "hint_zh": "（下划线：大胡子、乐呵呵）", "answer": "乐呵呵", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 2, "zh": "为了全家的面包，我也要好好工作呀。", "hint_zh": "（下划线：面包、工作）", "answer": "工作", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 3, "zh": "他的狡猾是出了名的，我们都很了解这只老狐狸。", "hint_zh": "（下划线：狡猾、老狐狸）", "answer": "狡猾", "answer_ref": {"book": "textbook_answers", "pages": [25]}}]}], "exercises": [{"n": 1, "type_zh": "模仿例子写词语", "instruction_zh": "模仿例子，写出更多的词语", "instruction_en": "Exercises", "items": [{"n": "例", "zh": "方言：语言　言论　传言　谎言", "hint_zh": "（言）"}, {"n": 1, "zh": "宽敞：________", "hint_zh": "（宽）", "answer": "宽松、宽裕、宽窄、宽限", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 2, "zh": "齐全：________", "hint_zh": "（全）", "answer": "周全、全身、全然、全心全意", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 3, "zh": "封闭：________", "hint_zh": "（闭）", "answer": "关闭、闭幕、闭塞、闭月羞花", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 4, "zh": "演绎：________", "hint_zh": "（演）", "answer": "演员、演出、演讲、表演", "answer_ref": {"book": "textbook_answers", "pages": [25]}}]}, {"n": 2, "type_zh": "完成句子", "instruction_zh": "用所给词语或结构完成句子", "items": [{"n": 1, "zh": "公司打算________。", "hint_zh": "（为期）", "answer": "开展为期一周的艺术周活动", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 2, "zh": "运动场上，大家________。", "hint_zh": "（A的A，B的B）", "answer": "跑的跑，跳的跳", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 3, "zh": "路途遥远，________。", "hint_zh": "（一时）", "answer": "我们一时没法估计到达的时间", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 4, "zh": "________，他感慨万分。", "hint_zh": "（回顾）", "answer": "回顾过去的四十年", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 5, "zh": "为了________，大家积极行动起来。", "hint_zh": "（响应）", "answer": "响应政府号召", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 6, "zh": "不好意思，________。", "hint_zh": "（仓促）", "answer": "时间有限，准备得太仓促了", "answer_ref": {"book": "textbook_answers", "pages": [25]}}]}, {"n": 3, "type_zh": "选词填空", "instruction_zh": "选择合适的词语填空", "word_bank": [["贤惠", "新郎", "新娘", "现场", "回顾"], ["正月", "对联", "天伦之乐", "家常", "拜年"]], "items": [{"n": 1, "zh": "昨天我参加了一对年轻人的婚礼，________帅气能干，________不但漂亮，而且________。两人________了恋爱时的点点滴滴。大家的掌声、笑声响成一片，婚礼________成了欢乐的海洋。", "hint_zh": "（贤惠、新郎、新娘、现场、回顾）", "answer": "新郎、新娘、贤惠、回顾、现场", "answer_ref": {"book": "textbook_answers", "pages": [25]}}, {"n": 2, "zh": "春节是中国最重要的传统节日，家家户户都贴________，包饺子，放鞭炮。在外地工作的儿女们，无论有多远，都要赶回家，陪父母聊聊________，帮父母做做家务，共享________。________初一，亲朋好友们互相________，共同祝愿新的一年一切顺利。", "hint_zh": "（正月、对联、天伦之乐、家常、拜年）", "answer": "对联、家常、天伦之乐、正月、拜年", "answer_ref": {"book": "textbook_answers", "pages": [25, 26]}}]}, {"n": 4, "type_zh": "指出借代的用法", "instruction_zh": "请指出下列语段中借代的用法（表格：语段 | ……借代……）", "items": [{"n": 1, "zh": "“老李，你有些不舒服吗？你生病了吗？”一个花白胡子问道。\n……借代……：________", "answer": "“花白胡子”借代“有花白胡子的人”。", "answer_ref": {"book": "textbook_answers", "pages": [26]}}, {"n": 2, "zh": "几千双眼睛都盯着你呢，你肩上的责任很重啊。\n……借代……：________", "answer": "“几千双眼睛”借代“几千个人”。", "answer_ref": {"book": "textbook_answers", "pages": [26]}}, {"n": 3, "zh": "要爱护这里的一草一木，不能拿群众的一针一线。\n……借代……：________", "answer": "“一草一木”“一针一线”借代“老百姓的所有事物”。", "answer_ref": {"book": "textbook_answers", "pages": [26]}}, {"n": 4, "zh": "远远的，一个可爱的小红帽一蹦一跳地走过来。\n……借代……：________", "answer": "“小红帽”借代“戴小红帽的人”。", "answer_ref": {"book": "textbook_answers", "pages": [26]}}]}, {"n": 5, "type_zh": "简述课文", "instruction_zh": "根据提示，简述课文主要内容（表格：项目 | 提示）", "items": [{"n": 1, "zh": "去时乘坐高铁的情形", "hint_zh": "车程，时速，车窗外，车里的人们（A的A，B的B，更多的……，寄情于……），终点站……"}, {"n": 2, "zh": "回程与去时有何不同？", "hint_zh": "车程，速度，网络信号，灯光，电源，环境"}, {"n": 3, "zh": "我跟朋友在车上聊了些什么？", "hint_zh": "①朋友：见义勇为的李芳芳　②我：贵族气十足的男生　③我们：小学地理老师，我们班的诸葛亮"}, {"n": 4, "zh": "我周围的人在做什么？", "hint_zh": "①双胞胎姐弟：弟弟考上大学，春节没有回家，家里……　②新婚小两口：分发喜糖，新郎……，新娘……，唱歌……"}, {"n": 5, "zh": "我们的感受", "hint_zh": "现代交通……，人们早已忘了……，……是人生最宝贵的财富"}]}, {"n": "扩展", "type_zh": "扩展 词汇：熟悉下列词语的语素义", "instruction_zh": "词汇：熟悉下列词语的语素义", "instruction_en": "Expansion", "items": [{"n": 1, "zh": "验收 | 验：察看，查考 | 收：接受"}, {"n": 2, "zh": "武装 | 武：关于军事的 | 装：配置"}, {"n": 3, "zh": "团结 | 团：会合在一起 | 结：组织，结合"}, {"n": 4, "zh": "整顿 | 整：整理 | 顿：处理，安置"}, {"n": 5, "zh": "界限 | 界：不同事物的分界 | 限：指定的范围"}, {"n": 6, "zh": "充当 | 充：担任 | 当：担任"}, {"n": 7, "zh": "签署 | 签：亲自写姓名或画记号 | 署：签名"}, {"n": 8, "zh": "包庇 | 包：隐藏，掩盖 | 庇：遮蔽，掩护"}, {"n": 9, "zh": "共鸣 | 共：在一起，一齐 | 鸣：发出声音，使发出声音"}, {"n": 10, "zh": "发动 | 发：开始行动，引起行动 | 动：改变原来的位置或状态"}, {"n": 11, "zh": "测量 | 测：用仪器确定空间、时间、温度、速度、功能的有关数据 | 量：用尺子等可作为标准的东西来确定事物的大小、多少或其他性质"}, {"n": 12, "zh": "指示 | 指：指点，引导 | 示：表明，把事物拿出来或指出来使人知道"}]}], "application": [{"title_zh": "写一写", "instruction_zh": "这篇课文通过一次旅行去程和回程的对比，告诉我们在现代人的生活中，快速的生活节奏让我们忘掉了很多美好的东西，其实我们需要在紧张的生活中慢下来，尽情享受一下慢的乐趣。请参考练习5，把课文缩写成400字左右的短文。", "instruction_en": "Application"}], "culture": {"title_zh": "课文脚注", "body_zh": "① 高铁：高速铁路。指能以200千米/小时以上的速度高速运行的客运铁路。中国目前的火车主要分下列几类：G-高速动车、D-动车组、C-城际列车、K-空调快速、T-空调特快、Z-直达特快和无字母开头的普客/普快，Y和N字头的列车比较少，一般都为省内旅游列车。\n② 西北：指中国西北地区，包括陕西省、甘肃省、青海省、宁夏回族自治区、新疆维吾尔自治区和内蒙古自治区西部。\n③ 硬座：中国火车座位票分为硬座和软座，卧铺票分为硬卧和软卧，高铁、动车分一等座和二等座以及商务座。"}}, "workbook": {"ref": {"book": "workbook", "pages": [113, 114, 115, 116, 117, 118, 119, 120]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：请选出与所听内容一致的一项。", "items": [{"n": 1, "zh": "", "options": {"A": "小学生的注意力不能持久", "B": "没有经验的老师上不好课", "C": "课有吸引力学生就会认真听", "D": "学生违反纪律是应该原谅的"}, "transcript_zh": "教师必须把教学活动组织得生动、有趣，除了教师讲授外，要多给学生参与的机会。小学生中出现的课堂纪律问题，往往不是学生故意捣乱，而是学生对教师的课不感兴趣，因而不能坚持听课。", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [50]}}, {"n": 2, "zh": "", "options": {"A": "考古工作者的数量一直不足", "B": "考古工作完毕，现场就破坏了", "C": "考古工作者都应该学习考古报告", "D": "考古报告能反映当时的考古发掘情况"}, "transcript_zh": "考古发掘中，能够直接参加考古工作的人终究是少数，且一旦发掘工作完毕，现场往往很难原样不动地保存下来，要想让更多的人了解某一地下发掘的现场、情景以及出土文物，只有依靠考古报告。", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [50]}}, {"n": 3, "zh": "", "options": {"A": "化学工业正在进行一场革命", "B": "人们怀疑无害化学品的真实性", "C": "传统化学工业的生存受到了挑战", "D": "降低化学污染的号召得到了响应"}, "transcript_zh": "传统的化学工业给环境带来的污染已十分严重，并威胁着人类的生存。化学工业能否生产出对环境无害的化学品？甚至开发出不产生废物的工艺？有识之士提出了绿色化学的号召，并立即得到了全世界的积极响应。", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [50]}}, {"n": 4, "zh": "", "options": {"A": "春节是一年的最后一天", "B": "“春节”古时称为“新正”", "C": "汉武帝规定春节为法定节日", "D": "从一开始春节就有很多习俗"}, "transcript_zh": "农历正月初一是古时的新年，又称“新正”，今天我们称之为“春节”。它作为古代官方法定岁首，乃汉武帝时编定的太初历所规定。千百年来，这个法定岁首逐步汇聚了许多其他节日的习俗，成为一个送旧迎新的节日。", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [50]}}, {"n": 5, "zh": "", "options": {"A": "小篆曾经风行六国", "B": "相传李斯创造了小篆", "C": "小篆可以写成方的或圆的", "D": "就书写简便而言，大篆更优"}, "transcript_zh": "小篆，是秦始皇统一六国之后，秦代通用的标准字体。相传是秦国丞相李斯所创。与大篆相比，小篆书写起来更加简便，字体长方，每个字大小一样，排列方正，横竖成行，给人一种整齐之美，这样也就形成了方圆兼备的小篆体。", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [50, 51]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：请选出正确答案。", "items": [{"n": 6, "zh": "", "options": {"A": "自己留学的经历", "B": "编辑朋友的建议", "C": "外国朋友的问题", "D": "女儿学校的要求"}, "transcript_zh": "男：离开美国后，你决定写这部非虚构题材的小说，有什么原因和契机吗？\n女：这本书是我自己的一段人生历程，其中也包含了大量人们需要的信息。之前我只写形象更为复杂、主题相对悲观的虚构作品。说到非虚构题材的写作，原因和契机其实很偶然。去年，我和一位出版社编辑聊起我在美国陪孩子读书时的一些见闻，提到这样一个场景：一对华人夫妇星期天去购物，那是个冬天，下着鹅毛大雪，他们开车经过市中心，看到有个女孩儿高举标语牌，孤零零地站在教堂门口，标语牌上写着：“抗议反对人工流产”“抗议歧视同性恋”，华人夫妇议论道，这么冷的天，一个女孩子站在雪地里，也不知道她父母知道不知道，车到近前才骇然发现，这女孩儿竟是他们还在读高中的独生女儿。\n编辑朋友激动地打断我，提议我写下来。她认为，我这几年陪读生活中遇到的点点滴滴都值得记录下来，现在这么多中国家庭把孩子送出去留学，家长非常需要了解我经历过的这些事，中国教育是有问题，但异国生涯无论对小留学生还是对家长都未必不是挑战。\n男：你是一个擅长写虚构小说和戏剧的作家，是什么让你决定从虚构的掩体中跃出，开始非虚构的写作？\n女：关于非虚构写作，虽然我是第一次尝试，不过我很早就关注了。那是2000年我在美国期间，逛书店的时候，我发现书店每周张贴出的畅销书前十名排行榜都分为两大类：虚构和非虚构，我吃惊地意识到，在美国，非虚构作品的数量和质量竟然可以和虚构作品不分伯仲。而那时，中国的文学刊物还没有“非虚构”栏目，虽然有报告文学，但报告文学只是非虚构里的一种形式。\n写这本书，我的初衷是希望和其他家长分享我所了解的美国高中校园，希望读者能够通过我和孩子的一些经历获得他们需要的信息，也希望通过我的视角让读者了解这个媒体上谈论最多的国家，因此比较有说服力的应该是非虚构这个写作形式。\n问：女的这本非虚构题材小说的写作契机是什么？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [51, 52]}}, {"n": 7, "zh": "", "options": {"A": "被华人夫妇的女儿征服了", "B": "认为小留学生也面临挑战", "C": "认为中国家长有时很幼稚", "D": "庆幸自己认识一位好作者"}, "transcript_zh": "男：离开美国后，你决定写这部非虚构题材的小说，有什么原因和契机吗？\n女：这本书是我自己的一段人生历程，其中也包含了大量人们需要的信息。之前我只写形象更为复杂、主题相对悲观的虚构作品。说到非虚构题材的写作，原因和契机其实很偶然。去年，我和一位出版社编辑聊起我在美国陪孩子读书时的一些见闻，提到这样一个场景：一对华人夫妇星期天去购物，那是个冬天，下着鹅毛大雪，他们开车经过市中心，看到有个女孩儿高举标语牌，孤零零地站在教堂门口，标语牌上写着：“抗议反对人工流产”“抗议歧视同性恋”，华人夫妇议论道，这么冷的天，一个女孩子站在雪地里，也不知道她父母知道不知道，车到近前才骇然发现，这女孩儿竟是他们还在读高中的独生女儿。\n编辑朋友激动地打断我，提议我写下来。她认为，我这几年陪读生活中遇到的点点滴滴都值得记录下来，现在这么多中国家庭把孩子送出去留学，家长非常需要了解我经历过的这些事，中国教育是有问题，但异国生涯无论对小留学生还是对家长都未必不是挑战。\n男：你是一个擅长写虚构小说和戏剧的作家，是什么让你决定从虚构的掩体中跃出，开始非虚构的写作？\n女：关于非虚构写作，虽然我是第一次尝试，不过我很早就关注了。那是2000年我在美国期间，逛书店的时候，我发现书店每周张贴出的畅销书前十名排行榜都分为两大类：虚构和非虚构，我吃惊地意识到，在美国，非虚构作品的数量和质量竟然可以和虚构作品不分伯仲。而那时，中国的文学刊物还没有“非虚构”栏目，虽然有报告文学，但报告文学只是非虚构里的一种形式。\n写这本书，我的初衷是希望和其他家长分享我所了解的美国高中校园，希望读者能够通过我和孩子的一些经历获得他们需要的信息，也希望通过我的视角让读者了解这个媒体上谈论最多的国家，因此比较有说服力的应该是非虚构这个写作形式。\n问：关于编辑朋友，下列哪项正确？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [51, 52]}}, {"n": 8, "zh": "", "options": {"A": "非虚构文学在中国是空白", "B": "2000年非虚构文学才出现", "C": "在美国非虚构作品很畅销", "D": "她接受了非虚构刊物的约稿"}, "transcript_zh": "男：离开美国后，你决定写这部非虚构题材的小说，有什么原因和契机吗？\n女：这本书是我自己的一段人生历程，其中也包含了大量人们需要的信息。之前我只写形象更为复杂、主题相对悲观的虚构作品。说到非虚构题材的写作，原因和契机其实很偶然。去年，我和一位出版社编辑聊起我在美国陪孩子读书时的一些见闻，提到这样一个场景：一对华人夫妇星期天去购物，那是个冬天，下着鹅毛大雪，他们开车经过市中心，看到有个女孩儿高举标语牌，孤零零地站在教堂门口，标语牌上写着：“抗议反对人工流产”“抗议歧视同性恋”，华人夫妇议论道，这么冷的天，一个女孩子站在雪地里，也不知道她父母知道不知道，车到近前才骇然发现，这女孩儿竟是他们还在读高中的独生女儿。\n编辑朋友激动地打断我，提议我写下来。她认为，我这几年陪读生活中遇到的点点滴滴都值得记录下来，现在这么多中国家庭把孩子送出去留学，家长非常需要了解我经历过的这些事，中国教育是有问题，但异国生涯无论对小留学生还是对家长都未必不是挑战。\n男：你是一个擅长写虚构小说和戏剧的作家，是什么让你决定从虚构的掩体中跃出，开始非虚构的写作？\n女：关于非虚构写作，虽然我是第一次尝试，不过我很早就关注了。那是2000年我在美国期间，逛书店的时候，我发现书店每周张贴出的畅销书前十名排行榜都分为两大类：虚构和非虚构，我吃惊地意识到，在美国，非虚构作品的数量和质量竟然可以和虚构作品不分伯仲。而那时，中国的文学刊物还没有“非虚构”栏目，虽然有报告文学，但报告文学只是非虚构里的一种形式。\n写这本书，我的初衷是希望和其他家长分享我所了解的美国高中校园，希望读者能够通过我和孩子的一些经历获得他们需要的信息，也希望通过我的视角让读者了解这个媒体上谈论最多的国家，因此比较有说服力的应该是非虚构这个写作形式。\n问：是什么原因促使女的愿意尝试非虚构写作？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [51, 52]}}, {"n": 9, "zh": "", "options": {"A": "读者喜欢什么她就写什么", "B": "进入本周畅销书排行前十", "C": "写的是美国高中校园生活", "D": "媒体评价其内容很有说服力"}, "transcript_zh": "男：离开美国后，你决定写这部非虚构题材的小说，有什么原因和契机吗？\n女：这本书是我自己的一段人生历程，其中也包含了大量人们需要的信息。之前我只写形象更为复杂、主题相对悲观的虚构作品。说到非虚构题材的写作，原因和契机其实很偶然。去年，我和一位出版社编辑聊起我在美国陪孩子读书时的一些见闻，提到这样一个场景：一对华人夫妇星期天去购物，那是个冬天，下着鹅毛大雪，他们开车经过市中心，看到有个女孩儿高举标语牌，孤零零地站在教堂门口，标语牌上写着：“抗议反对人工流产”“抗议歧视同性恋”，华人夫妇议论道，这么冷的天，一个女孩子站在雪地里，也不知道她父母知道不知道，车到近前才骇然发现，这女孩儿竟是他们还在读高中的独生女儿。\n编辑朋友激动地打断我，提议我写下来。她认为，我这几年陪读生活中遇到的点点滴滴都值得记录下来，现在这么多中国家庭把孩子送出去留学，家长非常需要了解我经历过的这些事，中国教育是有问题，但异国生涯无论对小留学生还是对家长都未必不是挑战。\n男：你是一个擅长写虚构小说和戏剧的作家，是什么让你决定从虚构的掩体中跃出，开始非虚构的写作？\n女：关于非虚构写作，虽然我是第一次尝试，不过我很早就关注了。那是2000年我在美国期间，逛书店的时候，我发现书店每周张贴出的畅销书前十名排行榜都分为两大类：虚构和非虚构，我吃惊地意识到，在美国，非虚构作品的数量和质量竟然可以和虚构作品不分伯仲。而那时，中国的文学刊物还没有“非虚构”栏目，虽然有报告文学，但报告文学只是非虚构里的一种形式。\n写这本书，我的初衷是希望和其他家长分享我所了解的美国高中校园，希望读者能够通过我和孩子的一些经历获得他们需要的信息，也希望通过我的视角让读者了解这个媒体上谈论最多的国家，因此比较有说服力的应该是非虚构这个写作形式。\n问：关于女的的非虚构小说，下列哪项正确？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [51, 52]}}, {"n": 10, "zh": "", "options": {"A": "她的书都写自己的亲身经历", "B": "她的非虚构小说信息量很大", "C": "她的作品内容丰富体裁齐全", "D": "她是一位正义感极强的作家"}, "transcript_zh": "男：离开美国后，你决定写这部非虚构题材的小说，有什么原因和契机吗？\n女：这本书是我自己的一段人生历程，其中也包含了大量人们需要的信息。之前我只写形象更为复杂、主题相对悲观的虚构作品。说到非虚构题材的写作，原因和契机其实很偶然。去年，我和一位出版社编辑聊起我在美国陪孩子读书时的一些见闻，提到这样一个场景：一对华人夫妇星期天去购物，那是个冬天，下着鹅毛大雪，他们开车经过市中心，看到有个女孩儿高举标语牌，孤零零地站在教堂门口，标语牌上写着：“抗议反对人工流产”“抗议歧视同性恋”，华人夫妇议论道，这么冷的天，一个女孩子站在雪地里，也不知道她父母知道不知道，车到近前才骇然发现，这女孩儿竟是他们还在读高中的独生女儿。\n编辑朋友激动地打断我，提议我写下来。她认为，我这几年陪读生活中遇到的点点滴滴都值得记录下来，现在这么多中国家庭把孩子送出去留学，家长非常需要了解我经历过的这些事，中国教育是有问题，但异国生涯无论对小留学生还是对家长都未必不是挑战。\n男：你是一个擅长写虚构小说和戏剧的作家，是什么让你决定从虚构的掩体中跃出，开始非虚构的写作？\n女：关于非虚构写作，虽然我是第一次尝试，不过我很早就关注了。那是2000年我在美国期间，逛书店的时候，我发现书店每周张贴出的畅销书前十名排行榜都分为两大类：虚构和非虚构，我吃惊地意识到，在美国，非虚构作品的数量和质量竟然可以和虚构作品不分伯仲。而那时，中国的文学刊物还没有“非虚构”栏目，虽然有报告文学，但报告文学只是非虚构里的一种形式。\n写这本书，我的初衷是希望和其他家长分享我所了解的美国高中校园，希望读者能够通过我和孩子的一些经历获得他们需要的信息，也希望通过我的视角让读者了解这个媒体上谈论最多的国家，因此比较有说服力的应该是非虚构这个写作形式。\n问：关于女的，下列哪项正确？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [51, 52]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–17题：请选出正确答案。", "items": [{"n": 11, "zh": "", "options": {"A": "努力工作", "B": "全家团聚", "C": "举行仪式", "D": "外出旅行"}, "transcript_zh": "“年”是中国人最重要、最综合的一个节日。年，对我们究竟意味着什么？华服？美食？休闲？放松？不尽然，应该说贴对联、穿新衣，只是一种仪式，是对辞旧迎新的尊重，对美好生活的憧憬；拜年、聚餐、拉家常，则是对亲情的眷恋。\n很多人感慨现在的“年味”越来越淡了。其实所谓“浓”或“淡”，恐怕只是成年人的感受，年复一年，循环往复，再加上现在生活水平提高了，平时吃、穿水平就不低，过年也变不出什么新花样，新鲜感自然就少了！但是孩子过年总是欢乐的，仿佛天天都被浓浓的年味包裹着，光是过年的气氛，就足以让他们欢快了，和儿时的我们一样。\n问：根据这段话，中国人过年要做什么？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [52, 53]}}, {"n": 12, "zh": "", "options": {"A": "为了漂亮", "B": "以示重视", "C": "因为有钱", "D": "因为高兴"}, "transcript_zh": "“年”是中国人最重要、最综合的一个节日。年，对我们究竟意味着什么？华服？美食？休闲？放松？不尽然，应该说贴对联、穿新衣，只是一种仪式，是对辞旧迎新的尊重，对美好生活的憧憬；拜年、聚餐、拉家常，则是对亲情的眷恋。\n很多人感慨现在的“年味”越来越淡了。其实所谓“浓”或“淡”，恐怕只是成年人的感受，年复一年，循环往复，再加上现在生活水平提高了，平时吃、穿水平就不低，过年也变不出什么新花样，新鲜感自然就少了！但是孩子过年总是欢乐的，仿佛天天都被浓浓的年味包裹着，光是过年的气氛，就足以让他们欢快了，和儿时的我们一样。\n问：过年为什么要穿新衣服？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [52, 53]}}, {"n": 13, "zh": "", "options": {"A": "以前的喧哗不见了", "B": "新鲜的东西都没有了", "C": "现在天天都穿新衣服", "D": "平时生活水平提高了"}, "transcript_zh": "“年”是中国人最重要、最综合的一个节日。年，对我们究竟意味着什么？华服？美食？休闲？放松？不尽然，应该说贴对联、穿新衣，只是一种仪式，是对辞旧迎新的尊重，对美好生活的憧憬；拜年、聚餐、拉家常，则是对亲情的眷恋。\n很多人感慨现在的“年味”越来越淡了。其实所谓“浓”或“淡”，恐怕只是成年人的感受，年复一年，循环往复，再加上现在生活水平提高了，平时吃、穿水平就不低，过年也变不出什么新花样，新鲜感自然就少了！但是孩子过年总是欢乐的，仿佛天天都被浓浓的年味包裹着，光是过年的气氛，就足以让他们欢快了，和儿时的我们一样。\n问：为什么很多人觉得现在年味不浓？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [52, 53]}}, {"n": 14, "zh": "", "options": {"A": "“慢生活”讲究事必躬亲", "B": "“慢生活”讲究行为优雅", "C": "“慢生活”讲究品味和质量", "D": "“慢生活”讲究体味做事的过程"}, "transcript_zh": "我理解“慢生活”就是一种生活态度，把工作、吃饭、休息、劳动都看成一种享受。老实说，生活中的每件小事都能给我们带来快乐，比如，拿起剪刀慢慢做点儿小手工；亲手织一件色泽淡雅、款式绝无仅有的毛衣穿在身上；在花瓶中插上一束沁人心脾的鲜花；每顿都用心做一碗健康美味的汤品。而做这些事的过程并非都是痛苦的劳动，其本身就充满了乐趣。\n于是，我开始改变自己。原本我不写日记，现在开始徜徉在文字之间，寻觅那一份“慢”的惬意；每天开车上班，我改变了按点出门的习惯，这样就不会为堵车而心急火燎，而是慢慢开，把驾驶当成一种乐趣；出去买菜或办事需要走路时，我的脚步慢了下来，看看身边的城市、身边的人，发现竟然会有不一样的心情！\n慢下来其实很简单，只要去除那些外力强加给你的价值观，只需听从自己内心的声音，找到自己喜欢的事情，按照自己的节奏，慢慢地享受那份美好，你的心中就会少些抱怨，感觉生活其实很精彩！\n问：说话人认为应该怎样理解“慢生活”？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [53, 54]}}, {"n": 15, "zh": "", "options": {"A": "开始读书写作", "B": "开始调整自己", "C": "学着买菜做饭", "D": "在街上东张西望"}, "transcript_zh": "我理解“慢生活”就是一种生活态度，把工作、吃饭、休息、劳动都看成一种享受。老实说，生活中的每件小事都能给我们带来快乐，比如，拿起剪刀慢慢做点儿小手工；亲手织一件色泽淡雅、款式绝无仅有的毛衣穿在身上；在花瓶中插上一束沁人心脾的鲜花；每顿都用心做一碗健康美味的汤品。而做这些事的过程并非都是痛苦的劳动，其本身就充满了乐趣。\n于是，我开始改变自己。原本我不写日记，现在开始徜徉在文字之间，寻觅那一份“慢”的惬意；每天开车上班，我改变了按点出门的习惯，这样就不会为堵车而心急火燎，而是慢慢开，把驾驶当成一种乐趣；出去买菜或办事需要走路时，我的脚步慢了下来，看看身边的城市、身边的人，发现竟然会有不一样的心情！\n慢下来其实很简单，只要去除那些外力强加给你的价值观，只需听从自己内心的声音，找到自己喜欢的事情，按照自己的节奏，慢慢地享受那份美好，你的心中就会少些抱怨，感觉生活其实很精彩！\n问：说话人有哪些改变？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [53, 54]}}, {"n": 16, "zh": "", "options": {"A": "不要去管别人想什么", "B": "不要惧怕外界的压力", "C": "按自己的想法享受美好", "D": "慢与不慢都能活得精彩"}, "transcript_zh": "我理解“慢生活”就是一种生活态度，把工作、吃饭、休息、劳动都看成一种享受。老实说，生活中的每件小事都能给我们带来快乐，比如，拿起剪刀慢慢做点儿小手工；亲手织一件色泽淡雅、款式绝无仅有的毛衣穿在身上；在花瓶中插上一束沁人心脾的鲜花；每顿都用心做一碗健康美味的汤品。而做这些事的过程并非都是痛苦的劳动，其本身就充满了乐趣。\n于是，我开始改变自己。原本我不写日记，现在开始徜徉在文字之间，寻觅那一份“慢”的惬意；每天开车上班，我改变了按点出门的习惯，这样就不会为堵车而心急火燎，而是慢慢开，把驾驶当成一种乐趣；出去买菜或办事需要走路时，我的脚步慢了下来，看看身边的城市、身边的人，发现竟然会有不一样的心情！\n慢下来其实很简单，只要去除那些外力强加给你的价值观，只需听从自己内心的声音，找到自己喜欢的事情，按照自己的节奏，慢慢地享受那份美好，你的心中就会少些抱怨，感觉生活其实很精彩！\n问：说话人对“慢生活”的切身感受是什么？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [53, 54]}}, {"n": 17, "zh": "", "options": {"A": "慢生活是大势所趋", "B": "慢点开车才能欣赏到风景", "C": "想提高工作效率要先慢下来", "D": "慢下来可以感受到不一样的生活"}, "transcript_zh": "我理解“慢生活”就是一种生活态度，把工作、吃饭、休息、劳动都看成一种享受。老实说，生活中的每件小事都能给我们带来快乐，比如，拿起剪刀慢慢做点儿小手工；亲手织一件色泽淡雅、款式绝无仅有的毛衣穿在身上；在花瓶中插上一束沁人心脾的鲜花；每顿都用心做一碗健康美味的汤品。而做这些事的过程并非都是痛苦的劳动，其本身就充满了乐趣。\n于是，我开始改变自己。原本我不写日记，现在开始徜徉在文字之间，寻觅那一份“慢”的惬意；每天开车上班，我改变了按点出门的习惯，这样就不会为堵车而心急火燎，而是慢慢开，把驾驶当成一种乐趣；出去买菜或办事需要走路时，我的脚步慢了下来，看看身边的城市、身边的人，发现竟然会有不一样的心情！\n慢下来其实很简单，只要去除那些外力强加给你的价值观，只需听从自己内心的声音，找到自己喜欢的事情，按照自己的节奏，慢慢地享受那份美好，你的心中就会少些抱怨，感觉生活其实很精彩！\n问：说话人告诉我们什么？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [53, 54]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第18–20题：请选出有语病的一项。", "items": [{"n": 18, "zh": "", "options": {"A": "由于这些电动机都以电池作为电源，所以未能广泛普及。", "B": "我承认，你年轻，身体比我棒极了，可你也不能这么不注意呀！", "C": "团结友爱、助人为乐、无私奉献，这些都是中华民族的传统美德。", "D": "人们散落在沙滩上，吃的吃，玩儿的玩儿，晒太阳的晒太阳，悠闲极了。"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 19, "zh": "", "options": {"A": "成都平原是我国西南地区最大的平原。", "B": "每逢佳节，这里常举行游园联欢，人们载歌载舞，喜气洋洋。", "C": "随着现代文明的发展和进步，人们对于生活节奏是更加没有规律了。", "D": "民间传说及古代作者常将元宵节的起源上溯至汉代，这不是没有道理的。"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 20, "zh": "", "options": {"A": "老人有一个儿子、两个女儿。每逢年节和老人的生日，几代人便欢聚一堂，尽享天伦之乐。", "B": "他规定所有员工统一着装。因为统一的服装可以使员工表现为非同一般的庄重和一丝不苟的修养，给客户留下好印象。", "C": "春天，他们种植松树；夏天，他们播种和照料野花；秋天，他们观察冬眠前各种动物的奇异骚动；冬天，他们给鸟喂食。", "D": "科学史是自然科学与人文科学之间的桥梁，它能够帮助人们获得自然科学的整体形象、人性的形象，从而全面地理解科学、理解科学与人文的关系。"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第21–23题：选词填空。", "items": [{"n": 21, "zh": "贾府不计成本办秦可卿葬礼和元妃省亲，只求________辉煌。结果事情是办得________了，但资源浪费了，贾府的________也就此开始了。", "options": {"A": "偶尔　顺利　没落", "B": "一度　漂亮　凋零", "C": "暂时　得意　堕落", "D": "一时　风光　衰落"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 22, "zh": "很多女人，特别是知性女人，常常认为女人的美是内在美和外在美的________。其实，在她们潜意识中更________的是内在美，往往________外在美，甚至对外在美有些________。", "options": {"A": "结合　在意　忽略　不屑一顾", "B": "总和　留心　疏忽　无拘无束", "C": "夹杂　挂念　漠视　无动于衷", "D": "统一　相信　马虎　不以为然"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 23, "zh": "第一天开上四个轮子上路，小李手忙脚乱，________至极，他能感觉到，路上的高手们嫌他车开得慢，________一般地超过他的车，有的还回过头来看上两眼，________中净是烦躁和埋怨，车子也是憋足了劲儿________而过。", "options": {"A": "威风　发狂　表情　擦肩", "B": "狼狈　示威　眼神　呼啸", "C": "惊恐　抗议　回顾　轰鸣", "D": "拘束　撒欢　仓促　一闪"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第24–28题：选句填空。\n一个人的成长，没有不经历坎坷的。只有历经挫折、苦涩与喜悦，才称得上是健康的成长。我一直在努力，希望自己做得更好，不辜负父母对我的期望，（24）________，唯有父母为子女的付出是无私且不求回报的。\n不记得有多少回，父母发现我走了歪路，好心来管教，（25）________，觉得父母多余，不喜欢他们管我，直到吃了苦头才后悔不已。那会儿的我，和很多孩子一样，（26）________，把父母的扶助当作天经地义，相反，对父母的教诲却是满肚子的不愿意，甚至充满敌意。\n其实父母把我们带到这个世界上，（27）________，让我们健康、快乐地成长，让我们掌握了知识，他们就尽到了责任。人生道路的选择是我们自己的事情，父母没有保证我们一辈子活得无忧无虑的义务。\n告诫各位朋友，懂事之后，不要随意伤害父母，多考虑一下他们的感受和意见，他们是为我们好，怕我们在成长之路上陷入误区，怕我们陷入不必要的痛苦。在我们成人之后，（28）________，做个有良心的人。", "items": [{"n": 24, "zh": "希望自己做得更好，不辜负父母对我的期望，（24）________，唯有父母为子女的付出是无私且不求回报的。", "options": {"A": "我却习惯性地反抗", "B": "因为普天之下", "C": "把我们拉扯大", "D": "要感念他们的养育之恩", "E": "把父母的付出当作理所当然"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 25, "zh": "不记得有多少回，父母发现我走了歪路，好心来管教，（25）________，觉得父母多余，不喜欢他们管我，直到吃了苦头才后悔不已。", "options": {"A": "我却习惯性地反抗", "B": "因为普天之下", "C": "把我们拉扯大", "D": "要感念他们的养育之恩", "E": "把父母的付出当作理所当然"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 26, "zh": "那会儿的我，和很多孩子一样，（26）________，把父母的扶助当作天经地义，相反，对父母的教诲却是满肚子的不愿意，甚至充满敌意。", "options": {"A": "我却习惯性地反抗", "B": "因为普天之下", "C": "把我们拉扯大", "D": "要感念他们的养育之恩", "E": "把父母的付出当作理所当然"}, "answer": "E", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 27, "zh": "其实父母把我们带到这个世界上，（27）________，让我们健康、快乐地成长，让我们掌握了知识，他们就尽到了责任。", "options": {"A": "我却习惯性地反抗", "B": "因为普天之下", "C": "把我们拉扯大", "D": "要感念他们的养育之恩", "E": "把父母的付出当作理所当然"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 28, "zh": "在我们成人之后，（28）________，做个有良心的人。", "options": {"A": "我却习惯性地反抗", "B": "因为普天之下", "C": "把我们拉扯大", "D": "要感念他们的养育之恩", "E": "把父母的付出当作理所当然"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第四部分（29–32）", "type_zh": "阅读 第四部分", "instruction_zh": "第29–36题：请选出正确答案。\n29–32.\n富兰克林的名言“时间就是生命，时间就是金钱”，作为大工业时代的座右铭，曾影响了整个世界，激励了无数人化身为社会机器的一个齿轮，越来越多的人沦为时间的奴隶。“慢的乐趣怎么失传了呢？”作家米兰·昆德拉在《慢》一书中发出这样的感慨。\n如今，一场新的提倡“慢”的革命正在悄然兴起。这场革命是由无数厌倦了忙碌日子的人们发起的，他们希望可以用更多的时间来欣赏生活的乐趣。\n对于“慢生活”，记者对10位不同行业的白领做了一次小型调查，无一例外，大家都渴望拥有慢生活的生活状态，但八成人认为“慢生活”只是美好的向往。“国情不允许”是白领们最为集中的观点。他们觉得中国用20年经历了欧美200年发生的事情，现在西欧的生活不快，因为他们的社会发展正处在较为稳定的阶段，而我国尚没有这样的经济基础和条件，还需要我们艰苦奋斗。另一方面，生活压力大也是白领们认为慢生活仅是向往的原因之一。\n媒体工作者薇薇是快工作、慢生活的有效实践者。虽然做媒体工作仿佛每天都在与时间赛跑，可她依然是贤惠的好媳妇、双胞胎的好母亲、公婆的好儿媳，她依然能超然地活得轻松而自在。上班时，她认真、高效地完成本职工作，下班后和孩子看漫画，和老人聊天，业余读读钟爱的古诗词，练练书法，周末全家人一起去爬山、会朋友、泛舟湖泊、纵情于山水之间。不管别人多忙碌，她依然可以保有内心的平静、淡定和从容。她做不了贵族，但她一定要做生活的主人。", "items": [{"n": 29, "zh": "失去慢的乐趣，源于：", "options": {"A": "社会的飞速发展", "B": "富兰克林的影响", "C": "人类深感时间宝贵", "D": "《慢》这本书的影响"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 30, "zh": "如今的状况是：", "options": {"A": "记者的调查惊动了社会", "B": "欣赏生活是一个世界潮流", "C": "多数白领希望生活重回慢节奏", "D": "多数人认为慢生活没什么好的"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 31, "zh": "八成人认为慢生活难以实现的理由是：", "options": {"A": "中国国情决定的", "B": "这些人还不够富有", "C": "中国经济发展不够稳定", "D": "中国赶上欧美需要200年"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 32, "zh": "关于薇薇，下列哪项正确：", "options": {"A": "她业余爱好跑步", "B": "她喜欢游山玩水", "C": "她还是个书法家", "D": "她向往贵族生活"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第四部分（33–36）", "type_zh": "阅读 第四部分", "instruction_zh": "33–36.\n三十年以后，乡村将是未来中国人的奢侈品。那时的乡村正如今天的城市让人们向往，那时的乡村将是鸟语花香的好地方。\n中国有句老话：三十年河东，三十年河西。1949年新中国成立，前半部历史是城市化，后半部历史将是乡村化。\n如今中国的乡村很多已经变成空心村，年轻人外出上学、务工，人人憧憬着城市生活，这就是今天的城市化。往后，再成为乡村土地主人的不再是曾经走出去的农民，而是从城市奔向农村的大学生和工人。“农民”这个名词将逐步被人们淡忘。城市化在不到20年时间内，会促成乡村更多的耕地转化，空心村将会转移，因为都市人住进了乡村，城市核心区将会成为“空心城”。那时，种田是一种最好的生活方式。三五万人的小城镇将是人们最向往的地方。那时的市长很牛，村长更牛。那时，村依然在，可能已改为庄园或农场，农业机械化程度达到90%。\n以自然为本，与自然相融将会成为未来人的集体追求。“食”在田园乡村会成为人们的首选，新鲜的空气、自然的田园、刚刚从树上摘下来的水果、刚刚从菜园采回来的蔬菜，这一切都会成为享受。若干年后，人们开始从内心关注土壤，开始把土壤、树木视为自己的孩子，看成有生命的物质。那时的“住”，追求的不仅是宽敞和室内的舒适度，还关注室内外的环境，环境将成为居住的重要条件。", "items": [{"n": 33, "zh": "今天中国乡村的状况是：", "options": {"A": "年轻人都很忙", "B": "人口流向城市", "C": "老房子都坏了", "D": "环境污染严重"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 34, "zh": "第2段画线词语“三十年河东，三十年河西”的意思最可能是：", "options": {"A": "指人事变化无常", "B": "指不必被往事所困", "C": "指人的习俗好恶变迁", "D": "指每三十年中定会发洪水"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 35, "zh": "根据上文，往后乡村会是什么样子？", "options": {"A": "那时的村长兼职养牛", "B": "都市人都会住进乡村社区", "C": "走出去的农民争相重回土地", "D": "村子可能已改为庄园或农场"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 36, "zh": "“以自然为本，与自然相融”指的是：", "options": {"A": "大自然应进入学生的书本", "B": "人们的居住环境不再闭塞", "C": "大家追求人与自然环境的融合", "D": "人们像爱护孩子一样爱护树木"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}], "answers_ref": {"book": "workbook_answers", "pages": [50, 51, 52, 53, 54, 94, 95, 96, 97, 98, 99, 100]}}, "unclear": ["HSK6-д багшийн ном байхгүй тул teacher талбар орхисон. Дасгалын номын 听力 1–17-ийн хариулт/бичвэр BLCUP 录音文本及答案 (HSK6 下 Recording Text.pdf х.50–54)-аас, сурах бичгийн 练一练/做一做/练习 хариулт 课本参考答案 (HSK6 下Answer Textbook.pdf х.24–26)-аас нэмсэн. Дасгалын номын 阅读 18–36-ийн хариулт эх сурвалжид (Recording Text-д зөвхөн 听力-ийн хариулт байдаг) хэвлэгдээгүй тул оруулаагүй.", "Аудио файлын нэр мэдэгдэхгүй тул audio талбар орхисон. Сурах бичгийн CD тэмдэг: 课文 = 33-1, 生词 = 33-2; дасгалын номын 听力 第一部分 = 33-1, 第二部分 = 33-2, 第三部分 = 33-3.", "Хичээлийн гарчгийн пиньинь (title_pinyin) номд хэвлэгдээгүй, 怀念/慢/生活 生词-д ороогүй — «Huáiniàn màn shēnghuó» гэж стандарт дуудлагаар бичсэн (номоос биш). title_en номын гарчгийн доорх «Cherishing the memory of slow life».", "课文 гарчигт «（1369字）» гэж хэвлэгдсэн — lines дахь цэг таслалтай нийт тэмдэгт (①②③ тэмдэггүйгээр) = 1371, зөвхөн ханз = 1227 (номын 1369-өөс 2-оор илүү; «……» гурван удаа (他叫……, 诸葛亮……, 6-р догол) — тус бүрийг 1 тэмдэгт гэж тоолбол 1368); бичвэрийг 220–300dpi зурагтай мөр мөрөөр тулгасан. 课文-ийн гарчиг = хичээлийн гарчиг. Пиньинь бичвэр хэвлэгдээгүй тул lines.pinyin байхгүй. 7 догол мөр (6-р догол мөр нь номд зөвхөн «……» — бичвэрийн орхигдсон хэсгийн тэмдэг, тусдаа мөр болгосон) — lines-ийг өгүүлбэрээр (。！？ дээр) хуваасан; 4-р догол мөрийн «还有，中学我们班那个料事如神的诸葛亮……» (。-гүй, «火车上»-ээр шинэ өгүүлбэр эхэлнэ) тусдаа мөр болгосон. Догол мөр эхлэх мөрийн дугаар (1-ээс): [1, 2, 8, 13, 19, 26, 27].", "课文-ийн доор эх сурвалж: «改编自《北京青年报》文章《从前慢》，作者：莲的心事» — схемд талбаргүй тул энд тэмдэглэв (lines-д оруулаагүй). 课文-д «高铁①», «西北②», «硬座③» — дээд индекс зүүлт тайлбарын тэмдэг; lines-д үлдээсэн. Зүүлт тайлбар ①②③ (PDF х.138-ын доод хэсэг) бүтнээр textbook.culture {title_zh:«课文脚注»}-д. 文化/俗语 хэсэг байхгүй. 课文-д зураг байхгүй.", "生词 57 байрлал (1–57), * тэмдэгтэй: зөвхөн 17 久违. Номд 54 无拘无束-ийн доор дугааргүй дэд үг «拘束 jūshù v. to restrain, to restrict» хэвлэгдсэн бөгөөд дараагийн үг «56. 束» — 55 дугаар номд хэвлэгдээгүй ч дэд үг яг 55-ын байрыг эзэлж байгаа тул n=55 гэж өгсөн (өмнөх хичээлүүдийн «эх үгийн дугаар» жишгээс ялгаатай — дугаарлалт тасрахгүйн тулд). Үгийн ай (pos) хэвлэгдээгүй: 12 不屑一顾, 19 见义勇为, 37 天伦之乐, 54 无拘无束. Пиньинь номд байгаагаар: 12 «búxiè yígù», 23 «bō zhǒng», 26 «dǎo luàn», 36 «bài nián», 38 «Yuánxiāo Jié» (зайтай); 19 «jiànyì-yǒngwéi», 54 «wújū-wúshù» (зураастай); 37 «tiānlúnzhīlè» (нийлүүлсэн); 7 宽敞 «kuānchang», 47 媳妇 «xífu» (хөнгөн хөг). 17 久违 «v. long-lost, long-awaited», 28 幼稚 «naïve» — номд байгаагаар. 29 双胞胎 бичвэрт «双胞胎姐弟», 34 爆炸 «爆炸性新闻», 22 贵族 «贵族气» дотор гарна. 专有名词 хэсэг байхгүй (西安、李芳芳、诸葛亮 ороогүй) → proper_nouns байхгүй.", "热身1 — зүүн талд ууртай хашгирч буй, гартаа тэмдэглэлийн дэвтэр, үзэг барьсан буржгар үстэй эмэгтэйн зураг; баруун талд хүснэгт (асуулт | 是/否): эхний мөр «你每天的生活紧张吗？ | 是/否» (толгой мөр), дараагийн 3 мөрийн баруун нүд хоосон, сүүлийн мөр «如果你每天很紧张、很累、压力很大、情绪变坏，你该怎么办？» хоёр баганыг нэгтгэсэн — warmup[0].items-д мөр мөрөөр (хоосон нүдийг ________). Номд асуултын тэмдэг нарийн «?» мэт хэвлэгдсэн — бүтэн өргөнтэй «？» болгосон. 热身2 — 4 мөрт хүснэгт (速/终/威/源 | үгс), warmup[1].items-д мөр мөрөөр.", "注释 (一) 综合注释 2 зүйл (A的A，B的B、一时) → grammar 1–2; (二) 词语辨析 现场——当场 (дугааргүй хайрцаг) хүснэгтийг grammar 3 болгон (explanation_zh + structure_rows); (三) 篇章修辞 修辞（9）借代 → grammar 4. Номын улаан өнгөөр хэвлэгдсэн жишээ = 课文-ийн өгүүлбэр → note_zh «课文句» (A的A，B的B (2), 一时 ■1 (1), 借代 (1)).", "A的A，B的B 练一练 «请把下列6个小句组合成3个连贯的语段» — A–F, доор нь «（1）（2）（3）» хоосон хариултын зай; L28-ын жишгээр нэг practice item-д options A–F-ээр. 一时 — хоёр утга ■-ээр, утга тус бүрийн жишээ (1)(2)-оор дахин эхэлж дугаарлагдсан (examples n: 1,2,1,2 — номд байгаагаар; note_zh-д утгыг тэмдэглэсэн). 一时 练一练 — өгүүлбэр бүрт A B C D байрлалын үсэг (хариулт хэвлэгдээгүй).", "现场——当场 хүснэгт: «不同点» 2-р мөрөнд баруун (当场) нүд «2. 没有左边这个用法。» нь зүүн талын тайлбар ба «如：地震过后，现场一片狼藉。» хоёр мөрийг нэгтгэсэн. Жишээн дэх «现场»/«当场» хөх өнгөөр тодотгогдсон — текстэд тусгаагүй. 做一做 ❶–❹ хоосон зайтай (хариулт хэвлэгдээгүй).", "借代 жишээ бүрийн доор хаалтан дахь тайлбар номд хэвлэгдсэн → note_zh-д бүтнээр. Тайлбарт «我们班那个料事如神的同学» гэж, бичвэрт «中学我们班那个料事如神的诸葛亮» гэж — номд байгаагаар. 练一练 (1)–(3): өгүүлбэр бүрд хоёр үг доогуур зураастай (大胡子/乐呵呵, 面包/工作, 狡猾/老狐狸) — hint_zh-д «（下划线：…）» гэж тэмдэглэсэн.", "练习1 模仿例子： доогуур цэгтэй ханз (зургаар шалгасан) — 例 方言 (言), 宽敞 (宽), 齐全 (全), 封闭 (闭), 演绎 (演); hint_zh-д. Жишээ мөр «方言：语言 言论 传言 谎言» номд хэвлэгдсэн (n=«例»). 练习2 — мөр бүрийн ард хаалтан доторх үг/бүтэц hint_zh-д.", "练习3 选词填空: 2 догол бичвэр, тус бүр 5 хоосон зай + өөрийн 5 үгийн сан (word_bank 2 бүлэг, hint_zh-д давтсан). 练习4 — номд хүснэгт (语段 | ……借代……), баруун багана хоосон → items.zh-д «\\n……借代……：________» гэж нэмсэн. 练习5 — хүснэгт (зүүн: сэдэв, баруун: сануулга ①②), гарчиг мөр байхгүй; items.zh = зүүн багана, hint_zh = баруун багана. 练习5-д «新婚小两口» гэж (бичвэрт «一对新婚的夫妇»), «我们班的诸葛亮» гэж — номд байгаагаар.", "扩展 «词汇：熟悉下列词语的语素义» — номд салаалсан диаграм (үг → хоёр ханз тус бүрийн утга), 12 үг 2 баганаар; items-д мөрөөр, зүүнээс баруун тийш уншсан дараалал (验收、武装、团结、整顿、界限、充当、签署、包庇、共鸣、发动、测量、指示). «充：担任» ба «当：担任» — хоёулаа «担任» гэж хэвлэгдсэн (номд байгаагаар). Энэ хэсэгт 做一做 байхгүй. 运用 — зөвхөн «写一写» (400 орчим ханзаар 缩写), доор нь хоосон мөрүүд.", "Дасгалын ном (PDF х.113–120) — 听力 1–17 + 阅读 18–36, нийт 36 асуулт. Энэ хичээлд 三、书写 хэсэг байхгүй (PDF х.121 = 第34课).", "Дасгалын ном: хагас өргөнтэй мэт нарийн цэг таслал (23 «手忙脚乱,», «慢,», «两眼,»; 24–28 «期望,（24）», «管教,（25）», «一样,（26）», «世界上,（27）», «之后,（28）»; 29–32 «呢?”») — бүтэн өргөнтэй «，»«？» болгосон. Тоо ба ханзын хооронд нарийн зай («2000 年», «10 位», «20 年», «200 年», «1949 年», «90%») — зайгүй бичсэн. 21-д хоосон зай мөр дамжин хуваагдсан («办得______ / __了») — нэг зай гэж бичсэн.", "Дасгалын ном 阅读 21–23: сонголт бүр 3–4 үгийн багц — options-д «　» (бүтэн өргөнтэй зай)-гаар холбосон.", "Дасгалын ном 阅读 24–28: бичвэр section.instruction_zh-д, сонголт A–E бүх item-д давтсан; бичвэрийн баруун талд хоолтой ширээний ард инээмсэглэсэн гэр бүлийн (эцэг, эх, охин, өвөө) хар цагаан зураг.", "Дасгалын ном 阅读 第四部分 29–36 нэг заавар («第29–36题») — хоёр бичвэрийг тус тусын section-д (29–32 慢生活, 33–36 乡村). 29–32 бичвэрийн зүүн талд цүнх барьсан бизнесмэн дээш чиглэсэн том сумны нуман зам дээгүүр гүйж буй зураг; «米兰·昆德拉» — «·» тусгаарлагч. 33–36 бичвэрт «三十年河东，三十年河西» доогуур зураастай (34-р асуултын «画线词语»); бичвэрийн баруун талд дугуй малгайтай, нуруундаа том сагс үүрсэн хүн шанхай хүрэн үхэр хөтлөн дэнж тариалангийн хажуугийн замаар явж буй, ард нь ой мод, уул бүхий хар цагаан зураг.", "Дасгалын номын 阅读 18–36-ийн хариултыг BLCUP 录音文本及答案 (HSK6下 Recording Text.pdf) төгсгөлийн нэгдсэн 参考答案 хүснэгт (х.94–100)-ээс нэмсэн; 听力 1–17-ийн inline хариулттай тулгасан."], "verified_pages": [137, 138, 139, 140, 141, 142, 143, 144, 145, 113, 114, 115, 116, 117, 118, 119, 120], "schema_version": 1}'::jsonb, 1, 'image_verified')
on conflict (id) do update set book=excluded.book, title_zh=excluded.title_zh, title_pinyin=excluded.title_pinyin, title_en=excluded.title_en, payload=excluded.payload, schema_version=excluded.schema_version, status=excluded.status;
insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk6-l34', 'hsk6', 'HSK6B', 34, '为文物而生的人', 'Wèi wénwù ér shēng de rén', 'A person who was born for cultural relics', '{"level": "hsk6", "lesson": 34, "book": "HSK6B", "title_zh": "为文物而生的人", "title_pinyin": "Wèi wénwù ér shēng de rén", "title_en": "A person who was born for cultural relics", "textbook": {"ref": {"book": "textbook", "pages": [146, 147, 148, 149, 150, 151, 152, 153, 154, 155, 156]}, "warmup": [{"instruction_zh": "请对照图片熟悉下列物品的名称，并说一说你在哪儿见过这些东西。", "instruction_en": "Warm-up", "items": ["斗彩（dòucǎi）", "糖葫芦（tánghúlu）", "陶瓷（táocí）", "古玩（gǔwán）"], "pictures_desc_en": ["a porcelain bowl with a blue-and-white rim band and multicolored floral/plant decoration on the outside — 斗彩", "many red candied haws on bamboo skewers (tanghulu) — 糖葫芦", "a round lidded porcelain box with a yellow ground and dark floral pattern — 陶瓷", "a round lidded box of carved red lacquer with relief figures in a landscape, on a stand — 古玩"]}, {"instruction_zh": "想一想下列词语之间有什么联系。", "items": ["衣 | 衣着、衣服、衣柜、衣架、衣领、衣物、大衣、衬衣、风衣、毛衣、上衣、睡衣、外衣", "家 | 收藏家、鉴定家、科学家、艺术家、画家、作家、文学家、政治家、音乐家、名家、专家、大家", "册 | 造册、注册、表册、分册、画册、名册、史册、手册、书册、账册、纪念册、册子", "丰 | 丰厚、丰产、丰富、丰满、丰茂、丰年、丰盛、丰收、丰硕、丰足、丰裕、丰衣足食、五谷丰登"]}], "texts": [{"n": 1, "title_zh": "为文物而生的人", "title_en": "A person who was born for cultural relics", "kind": "narrative", "lines": [{"zh": "几十年前，北京街头远不及今天繁华。"}, {"zh": "清晨，朝霞还没铺满天空，一位衣着朴素、性情温和的老人，坐着一路颠簸的公共汽车去上班。"}, {"zh": "到站了，他慢慢地从车上走下来，走过他熟悉的大街小巷，步行到故宫博物院。"}, {"zh": "他就是著名的古陶瓷收藏家、鉴定家孙瀛洲①。"}, {"zh": "对于孙瀛洲和他的家人来说，1956年是个值得记忆的年头，那一年孙瀛洲将自己精心收藏的3000余件文物无偿赠送给了故宫博物院，其中的斗彩②三秋杯更是格外引人注目。"}, {"zh": "孙瀛洲的女儿孙女士至今仍记得当年的情景。"}, {"zh": "那些日子，家里人来人往，络绎不绝，人们忙着对捐献的文物登记造册，之后，故宫的同志就该来打包装箱了。"}, {"zh": "那晚，父亲把全家叫到一起，从准备捐出的几百盒珍贵文物中找出一个精致的小盒子，取出两个小瓷杯给全家看。"}, {"zh": "他说这是咱家最值钱的东西，故宫里也没有，明天就捐给故宫了，今天让你们看看。"}, {"zh": "父亲说话时脸上充满了自豪。"}, {"zh": "大家专注地看着父亲手里那对造型秀巧，杯体轻灵、洁白的斗彩瓷杯：杯体色调柔和宁静，搭配的图案是两只在山石花草间飞舞的蝴蝶，淡雅清爽，赏心悦目。"}, {"zh": "相传这对杯子是当年皇帝专门下旨烧制的，不是烧给皇后，而是烧给一位爱妃①。"}, {"zh": "当时共烧成5对，选出这一对后，其余4对全部销毁，并将烧制杯子的手艺人处死，烧制工艺就此失传，而这对凝聚着先人智慧结晶的杯子也就成了存世孤品。"}, {"zh": "也许有人要问，这孙瀛洲到底什么来历？"}, {"zh": "家藏竟然如此丰厚？"}, {"zh": "孙瀛洲的籍贯是河北，他13岁到北京，在古玩店做学徒、伙计，之后做过采购、副经理。"}, {"zh": "1923年他自己创业，开办了古玩店。"}, {"zh": "由于经营有方，又收藏有大量珍贵文物，孙瀛洲在当时的古董经营者中很有威望。"}, {"zh": "孙女士感慨道，尽管当年家中私藏丰厚，但他们生活却非常简朴，甚至有些吝啬，举个例子吧，过年时孩子们吃的糖葫芦都是孙瀛洲自制的。"}, {"zh": "他对孩子尚且如此，对自己的那份节俭也就不难想象了。"}, {"zh": "可是，为了收购绝世珍品斗彩三秋杯，他却是不惜重金。"}, {"zh": "正是这种对陶瓷执着的热爱，使孙瀛洲收藏了数量可观的陶瓷精品。"}, {"zh": "孙羸洲的子女们说，父亲来到这个世界好像只有一个神圣的使命——保护文物。"}, {"zh": "他全身心投入到文物当中，生活在文物当中。"}, {"zh": "有人问他们怎样看待当年父亲捐赠的义举？"}, {"zh": "要是在今天，你们这些做家属的会支持父亲吗？"}, {"zh": "他们回答：“今天我们也会拥护父亲的选择，就像父亲捐出这些文物不是为了表彰，不是为了荣誉，不是为了奖励，也没想得到什么称号一样，这些东西本就属于国家，属于全人类。”"}, {"zh": "孙家后人很争气，他们不想沾父亲的光，父亲留给他们最大的财富就是高洁的品质。"}, {"zh": "1956年，孙瀛洲受聘于故宫博物院从事古陶瓷研究、鉴定工作。"}, {"zh": "他很乐意接受这份工作，工作中更是精益求精。"}, {"zh": "孙瀛洲的弟子讲过这样一件事：一次，孙瀛洲让人们把不同时期的瓷器放在一起，其中当然有真品，也有仿品。"}, {"zh": "他背过身，人们打乱摆放次序，他闭着眼睛，转过身来，只用手摸，就准确地一一说出了各件文物的朝代、名称。"}, {"zh": "在历来假货泛滥的文物界，鉴定家孙瀛洲就是一张最有威信的名片。"}, {"zh": "当代社会，被称为“专家”容易，称为“著名专家”也不难，但称得上“大家”的不多，孙瀛洲就是人人心服口服的国家级别的“大家”。"}, {"zh": "孙瀛洲在故宫博物院工作期间将一生所学毫无保留地传授给学生，培养出一批文物鉴定人才，有的已成为当今古陶瓷鉴定的泰斗。"}], "new_words": [{"n": 1, "zh": "霞", "pinyin": "xiá", "pos": "n.", "en": "morning or evening glow", "text": 1}, {"n": 2, "zh": "朴素", "pinyin": "pǔsù", "pos": "adj.", "en": "plain, simple", "text": 1}, {"n": 3, "zh": "温和", "pinyin": "wēnhé", "pos": "adj.", "en": "mild, gentle", "text": 1}, {"n": 4, "zh": "颠簸", "pinyin": "diānbǒ", "pos": "v.", "en": "to bump, to jolt", "text": 1}, {"n": 5, "zh": "巷", "pinyin": "xiàng", "pos": "n.", "en": "lane", "text": 1}, {"n": 6, "zh": "陶瓷", "pinyin": "táocí", "pos": "n.", "en": "pottery and porcelain", "text": 1}, {"n": 7, "zh": "收藏", "pinyin": "shōucáng", "pos": "v.", "en": "to collect", "text": 1}, {"n": 8, "zh": "鉴定", "pinyin": "jiàndìng", "pos": "v.", "en": "to authenticate", "text": 1}, {"n": 9, "zh": "无偿", "pinyin": "wúcháng", "pos": "adj.", "en": "free of charge, for free", "text": 1}, {"n": 10, "zh": "赠送", "pinyin": "zèngsòng", "pos": "v.", "en": "to give as a present", "text": 1}, {"n": 11, "zh": "络绎不绝", "pinyin": "luòyì bù jué", "en": "to come and go in a continuous stream", "text": 1}, {"n": 12, "zh": "文物", "pinyin": "wénwù", "pos": "n.", "en": "cultural relic, historical relic", "text": 1}, {"n": 13, "zh": "同志", "pinyin": "tóngzhì", "pos": "n.", "en": "comrade", "text": 1}, {"n": 14, "zh": "打包", "pinyin": "dǎ bāo", "pos": "v.", "en": "to pack", "text": 1}, {"n": 15, "zh": "搭配", "pinyin": "dāpèi", "pos": "v.", "en": "to match", "text": 1}, {"n": 16, "zh": "图案", "pinyin": "tú’àn", "pos": "n.", "en": "pattern", "text": 1}, {"n": 17, "zh": "皇帝", "pinyin": "huángdì", "pos": "n.", "en": "emperor", "text": 1}, {"n": 18, "zh": "皇后", "pinyin": "huánghòu", "pos": "n.", "en": "empress, wife of an emperor", "text": 1}, {"n": 19, "zh": "销毁", "pinyin": "xiāohuǐ", "pos": "v.", "en": "to destroy by melting or burning", "text": 1}, {"n": 20, "zh": "手艺", "pinyin": "shǒuyì", "pos": "n.", "en": "handicraft, craftsmanship", "text": 1}, {"n": 21, "zh": "凝聚", "pinyin": "níngjù", "pos": "v.", "en": "to agglomerate, to embody", "text": 1}, {"n": 22, "zh": "结晶", "pinyin": "jiéjīng", "pos": "n.", "en": "crystallization, fruit, product", "text": 1}, {"n": 23, "zh": "籍贯", "pinyin": "jíguàn", "pos": "n.", "en": "the place of one’s birth or origin", "text": 1}, {"n": 24, "zh": "采购", "pinyin": "cǎigòu", "pos": "n.", "en": "purchase", "text": 1}, {"n": 25, "zh": "创业", "pinyin": "chuàngyè", "pos": "v.", "en": "to start an undertaking or a business, to do pioneering work", "text": 1}, {"n": 26, "zh": "威望", "pinyin": "wēiwàng", "pos": "n.", "en": "prestige", "text": 1}, {"n": 27, "zh": "吝啬", "pinyin": "lìnsè", "pos": "adj.", "en": "stingy, miserly", "text": 1}, {"n": 28, "zh": "尚且", "pinyin": "shàngqiě", "pos": "conj.", "en": "even", "text": 1}, {"n": 29, "zh": "不惜", "pinyin": "bùxī", "pos": "v.", "en": "to not spare, to not scruple", "text": 1}, {"n": 30, "zh": "可观", "pinyin": "kěguān", "pos": "adj.", "en": "considerable", "text": 1}, {"n": 31, "zh": "神圣", "pinyin": "shénshèng", "pos": "adj.", "en": "sacred, holy", "text": 1}, {"n": 32, "zh": "使命", "pinyin": "shǐmìng", "pos": "n.", "en": "mission", "text": 1}, {"n": 33, "zh": "看待", "pinyin": "kàndài", "pos": "v.", "en": "to regard, to treat", "text": 1}, {"n": 34, "zh": "家属", "pinyin": "jiāshǔ", "pos": "n.", "en": "family members", "text": 1}, {"n": 35, "zh": "拥护", "pinyin": "yōnghù", "pos": "v.", "en": "to support, to uphold", "text": 1}, {"n": 36, "zh": "表彰", "pinyin": "biǎozhāng", "pos": "v.", "en": "to commend, to cite", "text": 1}, {"n": 37, "zh": "荣誉", "pinyin": "róngyù", "pos": "n.", "en": "honor", "text": 1}, {"n": 38, "zh": "奖励", "pinyin": "jiǎnglì", "pos": "v.", "en": "to reward, to award", "text": 1}, {"n": 39, "zh": "称号", "pinyin": "chēnghào", "pos": "n.", "en": "title", "text": 1}, {"n": 40, "zh": "争气", "pinyin": "zhēng qì", "pos": "v.", "en": "to try to make a good showing, to try to win credit for, to try to bring credit to", "text": 1}, {"n": 41, "zh": "沾光", "pinyin": "zhān guāng", "pos": "v.", "en": "to benefit from association with sb. or sth.", "text": 1}, {"n": 42, "zh": "品质", "pinyin": "pǐnzhì", "pos": "n.", "en": "character, quality", "text": 1}, {"n": 43, "zh": "乐意", "pinyin": "lèyì", "pos": "v.", "en": "to be willing to, to be ready to", "text": 1}, {"n": 44, "zh": "精益求精", "pinyin": "jīngyìqiújīng", "en": "to always endeavor to do still better, to constantly perfect one’s skill", "text": 1}, {"n": 45, "zh": "次序", "pinyin": "cìxù", "pos": "n.", "en": "order, sequence", "text": 1}, {"n": 46, "zh": "朝代", "pinyin": "cháodài", "pos": "n.", "en": "dynasty", "text": 1}, {"n": 47, "zh": "泛滥", "pinyin": "fànlàn", "pos": "v.", "en": "to be in flood, to overflow", "text": 1}, {"n": 48, "zh": "威信", "pinyin": "wēixìn", "pos": "n.", "en": "prestige", "text": 1}, {"n": 49, "zh": "当代", "pinyin": "dāngdài", "pos": "n.", "en": "present, contemporary era", "text": 1}, {"n": 50, "zh": "级别", "pinyin": "jíbié", "pos": "n.", "en": "rank, level", "text": 1}, {"n": 51, "zh": "泰斗", "pinyin": "tàidǒu", "pos": "n.", "en": "leading authority", "text": 1}]}], "grammar": [{"n": 1, "title_zh": "尚且", "explanation_zh": "“尚且”，连词。用在复句的前一小句，提出明显的事例做比况，后一小句对程度上有差别的同类事例做出当然的结论。例如：", "examples": [{"n": 1, "zh": "尽管当年家中私藏丰厚，但他们生活却非常简朴，甚至有些吝啬，举个例子吧，过年时孩子们吃的糖葫芦都是孙瀛洲自制的。他对孩子尚且如此，对自己的那份节俭也就不难想象了。", "note_zh": "课文句"}, {"n": 2, "zh": "经济增长强劲时，这个企业尚且如此，经济衰退时，企业肯定会出现生存问题。"}, {"n": 3, "zh": "“人”和“入”这么简单的两个字他尚且分不清楚，何况其他呢？"}], "practice_instruction_zh": "练一练：给“尚且”选择适当的位置", "practice": [{"n": 1, "zh": "A小学生B明白C这些D道理，何况大学生呢？", "answer": "B", "answer_ref": {"book": "textbook_answers", "pages": [26]}}, {"n": 2, "zh": "钱钟书先生A如此B，对于一般人来C说，读书D做笔记就更有必要了。", "answer": "A", "answer_ref": {"book": "textbook_answers", "pages": [26]}}, {"n": 3, "zh": "A这个字B你作为中国人C不认识，D我这个留学生就更不认识了。", "answer": "C", "answer_ref": {"book": "textbook_answers", "pages": [26]}}]}, {"n": 2, "title_zh": "当", "explanation_zh": "“当”，介词，意思是正在（那个时候、那个地方）。例如：", "examples": [{"n": 1, "zh": "孙瀛洲的女儿孙女士至今仍记得当年的情景。", "note_zh": "课文句"}, {"n": 2, "zh": "由于经营有方，又收藏有大量珍贵文物，孙瀛洲在当时的古董经营者中很有威望。", "note_zh": "课文句"}, {"n": 3, "zh": "当代社会，被称为“专家”容易，称为“著名专家”也不难，但称得上“大家”的不多。", "note_zh": "课文句"}], "practice_instruction_zh": "练一练：选择合适的词语填空（当今　当场　当地）", "practice": [{"n": 1, "zh": "洪水淹没了村庄，给________人民的生活造成了很大的损失。", "hint_zh": "（当今、当场、当地）", "answer": "当地", "answer_ref": {"book": "textbook_answers", "pages": [26]}}, {"n": 2, "zh": "所有这些，与________社会提倡的“可持续发展”“以人为本”的价值观显然是背道而驰的。", "hint_zh": "（当今、当场、当地）", "answer": "当今", "answer_ref": {"book": "textbook_answers", "pages": [26]}}, {"n": 3, "zh": "他刚把手伸到别人的书包里，钱包还没拿出来，就被警察________抓获。", "hint_zh": "（当今、当场、当地）", "answer": "当场", "answer_ref": {"book": "textbook_answers", "pages": [26]}}]}, {"n": 3, "title_zh": "温和——温柔", "title_en": "（二）词语辨析", "explanation_zh": "（二）词语辨析 温和——温柔\n共同点：形容词，都有（性情、态度、言语等）不严厉，使人感到亲切的意思。如：她性格温和/温柔。\n不同点：\n温和——1. 侧重表示态度和语言和气、有礼貌。如：经理温和的态度打消了我的顾虑。\n温柔——1. 含有脾气好、有不同意见的时候能顺从别人的意思，多用于女性。如：这个女孩子很温柔。\n温和——2. 可以指（气候）不冷不热。如：昆明气候温和，四季如春。\n温柔——2. 没有左边这个用法。", "structure_rows": [" | 温和 | 温柔", "共同点 | 形容词，都有（性情、态度、言语等）不严厉，使人感到亲切的意思。（两栏合并）", "共同点 | 如：她性格温和/温柔。（两栏合并）", "不同点 | 1. 侧重表示态度和语言和气、有礼貌。 | 1. 含有脾气好、有不同意见的时候能顺从别人的意思，多用于女性。", "不同点 | 如：经理温和的态度打消了我的顾虑。 | 如：这个女孩子很温柔。", "不同点 | 2. 可以指（气候）不冷不热。 | 2. 没有左边这个用法。（与下一行合并）", "不同点 | 如：昆明气候温和，四季如春。 | （同上）"], "examples": [{"n": 1, "zh": "她性格温和/温柔。", "note_zh": "共同点"}, {"n": 2, "zh": "经理温和的态度打消了我的顾虑。", "note_zh": "温和 不同点1"}, {"n": 3, "zh": "这个女孩子很温柔。", "note_zh": "温柔 不同点1"}, {"n": 4, "zh": "昆明气候温和，四季如春。", "note_zh": "温和 不同点2"}], "practice_instruction_zh": "做一做：判断正误", "practice": [{"n": 1, "zh": "一个态度温和的办事员接待了我，仔细询问了我的情况。（　　）", "answer": "√", "answer_ref": {"book": "textbook_answers", "pages": [26]}}, {"n": 2, "zh": "苏州地处太湖之滨，气候温柔，土地肥沃。（　　）", "answer": "×", "answer_ref": {"book": "textbook_answers", "pages": [26]}}, {"n": 3, "zh": "她温柔地开导我，使我受伤的心灵得到一丝抚慰。（　　）", "answer": "√", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 4, "zh": "他温和的目光给了我莫大的力量，我鼓起勇气登台演出。（　　）", "answer": "√", "answer_ref": {"book": "textbook_answers", "pages": [27]}}]}, {"n": 4, "title_zh": "篇章（5）过渡", "title_en": "（三）篇章修辞", "explanation_zh": "（三）篇章修辞 篇章（5）过渡\n“过渡”指文章由这层意思向另一层意思转换，或由这段内容向另一段内容发展时，用一些词、句子或语段使这两层意思或两段内容能够自然衔接起来。\n“过渡”的作用是使上下文的意思连贯起来，形成一个整体。大多数文章中都有过渡语言，或用过渡词，或用过渡句，或用过渡段。例如：", "examples": [{"n": 1, "zh": "孙女士感慨道，尽管当年家中私藏丰厚，但他们生活却非常简朴，甚至有些吝啬，举个例子吧，过年时孩子们吃的糖葫芦都是孙瀛洲自制的。他对孩子尚且如此，对自己的那份节俭也就不难想象了。可是，为了收购绝世珍品斗彩三秋杯，他却是不惜重金。正是这种对陶瓷执着的热爱，使孙瀛洲收藏了数量可观的陶瓷精品。", "note_zh": "课文句；（“可是”为过渡词）"}, {"n": 2, "zh": "不少人看到过象，都说象是很大的动物。其实还有比象大得多的动物，那就是鲸。目前已知最大的鲸约有十六万公斤重，最小的也有两千公斤。我国发现过一头近四万公斤重的鲸，约十七米长，一条舌头就有十几头猪那么重。它要是张开嘴，人站在它嘴里，举起手来都摸不到它的上腭，四个人围着桌子坐在它的嘴里看书，还显得很宽敞。\n……\n鲸的身子这么大，它们吃什么呢？须鲸主要吃虾和小鱼。它们在海洋里游的时候，张着大嘴，把许多小鱼小虾连同海水一齐吸进嘴里，然后闭上嘴，把海水从须板中间滤出来，把小鱼小虾吞进肚子里，一顿就可以吃两千多公斤。齿鲸主要吃大鱼和海兽。它们遇到大鱼和海兽，就凶猛地扑上去，用锋利的牙齿咬住，很快就吃掉了。有一种号称“海中之虎”的虎鲸，常常好几十头结成一群，围住一头三十吨重的长须鲸，几个小时就能把它吃光。\n……", "note_zh": "（“鲸的身子这么大，它们吃什么呢？”为过渡句）"}, {"n": 3, "zh": "……他说这是咱家最值钱的东西，故宫里也没有，明天就捐给故宫了，今天让你们看看。父亲说话时脸上充满了自豪。\n……\n也许有人要问，这孙瀛洲到底什么来历？家藏竟然如此丰厚？\n孙瀛洲的籍贯是河北，他13岁到北京，在古玩店做学徒……", "note_zh": "课文句；（“也许有人要问，这孙瀛洲到底什么来历？家藏竟然如此丰厚？”为过渡段）"}], "practice_instruction_zh": "练一练：为过渡句“这座桥不但坚固，而且美观。”选择合适的位置", "practice": [{"n": 1, "zh": "河北省赵县的洨河上，有一座世界闻名的石拱桥，叫安济桥，又叫赵州桥。A 它是隋朝的石匠李春设计和参加建造的，到现在已经有一千四百多年了。\n赵州桥非常雄伟。B 桥长五十多米，有九米多宽，中间行车马，两旁走人。这么长的桥，全部用石头砌成，下面没有桥墩，只有一个拱形的大桥洞，横跨在三十七米多宽的河面上。大桥洞顶上的左右两边，还各有两个拱形的小桥洞。平时，河水从大桥洞流过，发大水的时候，河水还可以从四个小桥洞流过。这种设计，在建桥史上是一个创举，既减轻了流水对桥身的冲击力，使桥不容易被大水冲毁，又减轻了桥身的重量，节省了石料。\nC 桥面两侧有石栏，栏板上雕刻着精美的图案：有的刻着两条相互缠绕的龙，嘴里吐出美丽的水花；有的刻着两条飞龙，前爪相互抵着，各自回首遥望；还有的刻着双龙戏珠。所有的龙似乎都在游动，真像活了一样。\nD 赵州桥表现了劳动人民的智慧和才干，是我国宝贵的历史遗产。", "options": {"A": "A", "B": "B", "C": "C", "D": "D"}}]}], "exercises": [{"n": 1, "type_zh": "模仿例子写词语", "instruction_zh": "模仿例子，写出更多的词语", "instruction_en": "Exercises", "items": [{"n": "例", "zh": "温和：温柔　温顺　温厚　温情", "hint_zh": "（温）"}, {"n": 1, "zh": "赠送：________", "hint_zh": "（赠）", "answer": "赠与　赠言　回赠　捐赠", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 2, "zh": "皇帝：________", "hint_zh": "（皇）", "answer": "皇后　皇宫　皇权　冠冕堂皇", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 3, "zh": "创业：________", "hint_zh": "（创）", "answer": "创造　开创　创立　创伤", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 4, "zh": "荣誉：________", "hint_zh": "（荣）", "answer": "荣光　光荣　荣耀　荣幸", "answer_ref": {"book": "textbook_answers", "pages": [27]}}]}, {"n": 2, "type_zh": "完成句子", "instruction_zh": "用所给词语完成句子", "items": [{"n": 1, "zh": "他常常________。", "hint_zh": "（无偿）", "answer": "无偿上门服务", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 2, "zh": "他们店的生意很好，________。", "hint_zh": "（络绎不绝）", "answer": "顾客络绎不绝", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 3, "zh": "大人________，更别说孩子了。", "hint_zh": "（尚且）", "answer": "尚且撑不住", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 4, "zh": "为了自己的事业，________。", "hint_zh": "（不惜）", "answer": "不惜牺牲家庭", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 5, "zh": "由于采用了新技术，________。", "hint_zh": "（可观）", "answer": "收益可观", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 6, "zh": "人们对环境的破坏________。", "hint_zh": "（泛滥）", "answer": "导致洪水泛滥", "answer_ref": {"book": "textbook_answers", "pages": [27]}}]}, {"n": 3, "type_zh": "选词填空", "instruction_zh": "选择合适的词语填空", "word_bank": [["颠簸", "无偿", "朴素", "可观", "吝啬"], ["荣誉", "威望", "手艺", "乐意", "沾光"]], "items": [{"n": 1, "zh": "我经常看到一位衣着________的老人，坐着________的公共汽车去上班。后来才知道，这位老人自己生活很简朴，甚至可以说________，但他________资助了许多贫困地区的孩子读书。几十年的捐款加起来，数额相当________。", "hint_zh": "（颠簸、无偿、朴素、可观、吝啬）", "answer": "我经常看到一位衣着朴素的老人，坐着颠簸的公共汽车去上班。后来才知道，这位老人自己生活很简朴，甚至可以说吝啬，但他资助了许多贫困地区的孩子读书。几十年的捐款加起来，数额相当可观。", "answer_ref": {"book": "textbook_answers", "pages": [27]}}, {"n": 2, "zh": "父亲是个________人，经过几十年的努力，他在行业内越来越有________，也得到了不少________。虽然父亲很________把这项传统技艺传授给我们，但我们这些子女并不想________父亲的________，我们更希望通过自己的奋斗获得成功。", "hint_zh": "（荣誉、威望、手艺、乐意、沾光）", "answer": "父亲是个手艺人，经过几十年的努力，他在行业内越来越有威望，也得到了不少荣誉。虽然父亲很乐意把这项传统技艺传授给我们，但我们这些子女并不想沾父亲的光，我们更希望通过自己的奋斗获得成功。", "answer_ref": {"book": "textbook_answers", "pages": [27]}}]}, {"n": 4, "type_zh": "找出过渡词、过渡句", "instruction_zh": "请找出下列语段中的过渡词、过渡句", "items": [{"n": 1, "zh": "我们班的同学学习都非常努力，拿小丽来说，她上课从来不迟到，每天不是在图书馆就是在宿舍学习。\n________\n________", "answer": "拿小丽来说", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 2, "zh": "如果我们在实践中选择和采取恰当的措施，目标一致地协调行动，我们的教育工作就会取得良好效果。反之，教育工作就会迷失方向，遭受挫折，甚至失败。\n________\n________", "answer": "反之", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 3, "zh": "农业的市场主要在城市，资金主要来自城市，技术和掌握高科技的人才也来自城市，总而言之，脱离了城市，农业和农村经济就无法得到发展。\n________\n________", "answer": "总而言之", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 4, "zh": "“三高”食品本身无罪，因为热量、脂肪、糖分也是人体必需的，但俗话说“过犹不及”，一个人每天摄入过量的油脂和糖分对身体危害是极大的。\n________\n________", "answer": "但俗话说", "answer_ref": {"book": "textbook_answers", "pages": [28]}}]}, {"n": 5, "type_zh": "简述课文", "instruction_zh": "根据提示，简述课文主要内容（表格：问题 | 提示）", "items": [{"n": 1, "zh": "描述一下孙瀛洲", "hint_zh": "衣着，性情，坐着……到……上班，是……家、……家"}, {"n": 2, "zh": "为什么说1956年是个值得记忆的年头？", "hint_zh": "把……无偿赠送给……，对……登记造册，打包装箱，父亲取出……给全家看"}, {"n": 3, "zh": "为什么斗彩三秋杯有这么高的价值？", "hint_zh": "造型……，色调……，图案……，相传……"}, {"n": 4, "zh": "说说孙瀛洲的经历", "hint_zh": "籍贯……，13岁……，在古玩店做……，1923年……，在……很有威望"}, {"n": 5, "zh": "孩子们怎么看待父亲和父亲的义举？", "hint_zh": "生活简朴，不惜重金……，支持父亲，不想沾父亲的光，父亲留下的最大财富……"}, {"n": 6, "zh": "孙瀛洲在工作中的贡献有哪些？", "hint_zh": "从事……工作，精益求精，弟子讲过的一件事，人人“心服口服”的“大家”，将……传授给……"}]}, {"n": "扩展", "type_zh": "扩展 词汇：熟悉表示人物身份的词语", "instruction_zh": "扩展 词汇：熟悉下列表示人物身份的词语（表格：词语 | 释义）", "instruction_en": "Expansion", "word_bank": [["董事长", "法人", "顾问", "保姆", "乞丐", "渔民", "委员", "书记", "元首", "俘虏", "将军", "司令", "公民"]], "items": [{"n": 1, "zh": "董事长 | 由董事会选举产生的公司法定代表人。", "hint_zh": "董事长"}, {"n": 2, "zh": "法人 | 法律上指根据法定程序设立，有一定的组织机构和独立的财产，参加民事活动的社会组织，如公司、社团等。", "hint_zh": "法人"}, {"n": 3, "zh": "顾问 | 有某方面的专门知识，供个人或机关团体咨询的人。", "hint_zh": "顾问"}, {"n": 4, "zh": "保姆 | 受雇为人照料儿童、老人、病人或为人从事家务劳动的妇女。", "hint_zh": "保姆"}, {"n": 5, "zh": "乞丐 | 靠向人要饭要钱生活的人。", "hint_zh": "乞丐"}, {"n": 6, "zh": "渔民 | 以捕鱼为业的人。", "hint_zh": "渔民"}, {"n": 7, "zh": "委员 | 政党、团体、机关、学校中的集体领导组织的成员。", "hint_zh": "委员"}, {"n": 8, "zh": "书记 | 党、团等各级组织中的主要负责人。", "hint_zh": "书记"}, {"n": 9, "zh": "元首 | 国家的最高领导人。", "hint_zh": "元首"}, {"n": 10, "zh": "俘虏 | 打仗时捉住的敌人。", "hint_zh": "俘虏"}, {"n": 11, "zh": "将军 | “将”一级的军官，也泛指高级军官。", "hint_zh": "将军"}, {"n": 12, "zh": "司令 | 某些国家军队中主管军事的人。", "hint_zh": "司令"}, {"n": 13, "zh": "公民 | 具有或取得某国国籍，并根据该国法律规定享有权利和承担相应义务的人。", "hint_zh": "公民"}]}], "application": [{"title_zh": "写一写", "instruction_zh": "这篇课文讲述了陶瓷收藏家、鉴定家孙瀛洲的故事，通过文章我们了解了孙瀛洲是怎样一位老人，他一生的经历，他惊人的义举以及对孩子们的影响，从而让我们看到了一个真正的“大家”有着怎样的一种风范。请参考练习5，把课文缩写成400字左右的短文。", "instruction_en": "Application"}], "culture": {"title_zh": "课文脚注", "body_zh": "① 孙瀛洲：（1893-1966），男，中国著名古陶瓷鉴定专家。\n② 斗彩：又称“逗彩”。中国传统制瓷工艺的珍品。斗彩瓷器流传下来的不多，实物非常罕见。\n① 爱妃：妃（fēi），皇帝娶的皇后之外的女子。爱妃：皇帝宠爱的妃子。"}}, "workbook": {"ref": {"book": "workbook", "pages": [121, 122, 123, 124, 125, 126, 127, 128]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：请选出与所听内容一致的一项。", "items": [{"n": 1, "zh": "", "options": {"A": "旅游是中国的支柱产业", "B": "中国有很多人造风景区", "C": "不漂亮的地方鲜有人去", "D": "说话人不看好微缩景观"}, "transcript_zh": "我们的旅游一向是靠老祖宗留下的宫殿庙宇和老天爷造化的奇山秀水吃饭，许多“原装”景点尚且门庭冷落，经过微缩之后的“小玩意”到底有多少吸引力，前景实难预料。", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [54]}}, {"n": 2, "zh": "", "options": {"A": "很多人在拍戏前受了重伤", "B": "他舍不得花钱搭建影视城", "C": "戏中的战争场面极其宏大", "D": "影片中的群众演员很出色"}, "transcript_zh": "戏开拍前，他不惜血本，花费了数千万人民币搭建了一座影视城。为了再现当年明军与清军鏖战的场面，他不惜重金累计动用了数万人来担任群众演员，场面之宏大令人叹为观止。", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [54]}}, {"n": 3, "zh": "", "options": {"A": "所谓销售就是有偿转让", "B": "转让无形资产是有条件的", "C": "单位不动产不可随意赠送", "D": "无偿赠予和销售无本质区别"}, "transcript_zh": "转让无形资产，是指转让无形资产的所有权或使用权的行为；销售不动产，是指有偿转让不动产的所有权，转让不动产的有限产权或永久使用权。单位将不动产无偿赠送给他人等视同销售不动产的行为。", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [54]}}, {"n": 4, "zh": "", "options": {"A": "不同气质的人可以互相影响", "B": "各种气质的人混搭方便互相学习", "C": "企业用人时应考虑不同气质的混搭", "D": "不同气质的人混搭的消极影响极大"}, "transcript_zh": "企业在选拔班组成员时,应注意各种气质类型人员的适当搭配。这样,在工作中各种气质可以得到适当的互补。把不同气质的人搭配在一起,就可以发挥各种气质的积极因素,弥补其中消极的成分。", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [54]}}, {"n": 5, "zh": "", "options": {"A": "他常在外面吃饭", "B": "他是个画画儿的", "C": "他历来花钱要算计", "D": "做公益不如画画儿"}, "transcript_zh": "与其对社会公益事业的慷慨资助相比，他对自己的要求显得过于苛刻了，他生活十分俭朴，从不乱花一分钱，每天作画裁下的纸条儿都舍不得丢掉；到外边吃饭要打包，甚至连家里每月的开销也要精打细算，力求节俭。", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [55]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：请选出正确答案。", "items": [{"n": 6, "zh": "", "options": {"A": "和说话人关系都很好", "B": "其文学素养有高有低", "C": "并不真心愿意搞写作", "D": "很多人改行搞收藏了"}, "transcript_zh": "女：您和中国的一线作家都有交情，海岩的第一件收藏品还是您帮他挑选的。您写过爱情小说，之后就去写文物了。\n男：我和这些作家关系都非常好，50岁以上、60岁以下的都认识，他们这些人本身都文学素养很高。他们年轻的时候，工作都是分配的，不能辞职。后来，慢慢地，很多人退出了文学圈。我曾经还是有些文学理想的，但后来觉得文学界不争气，就从那里面走出来了。后来，我写的关于艺术品的小说比他们的文学小说还畅销。\n女：您怎么评价文学界和文物界？\n男：我觉得文物比文学好的一点在于：它比较深，而文学比较浅。好比，你原来是个吸烟者，那是文学；而搞文物的就是雪茄。等你吸了雪茄，你会发现香烟比较淡。文学的评价标准也是个问题，写诗可以有好坏，反正都能写，谁好谁坏也没有一个终极标准。但文物是一个很窄的领域，而且文物是有终极判断的。我发现，文物界很多人说起话来前言不搭后语，文物界的人都特别死板，眼界特窄，而我眼界比较宽。\n女：您介入公共事务极为频繁，前不久还在博客上写关于贪官什么的文章，这样做是要保持影响力，还是纯粹出于表达的欲望？\n男：博客我一年要写137篇，最近四年都是这个速度。对我而言，收藏只是生活中的一个调剂，我因为在《百家讲坛》说收藏而“红”了。但我觉得，这反而是我最不看重的事儿。如果说我是“收藏家”的话，那可能是因为我著书立说了。\n女：商人、作家、学者、收藏家，在这几种身份之间，您如何评价自己？\n男：我是一个学者，不是一个商人。我曾经和我儿子说“我能够做一个学者，是这个时代的不幸，是我自己的大幸。”我们不能和王国维、陈寅恪相比，我实际上没读过什么书，我们算什么？我们这个时代缺少文化，所以稍微读了一点儿书的人就显得有文化。\n问：关于对话中所说的一线作家，下列哪项正确？", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [55, 56]}}, {"n": 7, "zh": "", "options": {"A": "搞文物的人喜欢雪茄", "B": "文物界的人眼界不宽", "C": "和文学的评价标准一致", "D": "文物涉及的领域比较广"}, "transcript_zh": "女：您和中国的一线作家都有交情，海岩的第一件收藏品还是您帮他挑选的。您写过爱情小说，之后就去写文物了。\n男：我和这些作家关系都非常好，50岁以上、60岁以下的都认识，他们这些人本身都文学素养很高。他们年轻的时候，工作都是分配的，不能辞职。后来，慢慢地，很多人退出了文学圈。我曾经还是有些文学理想的，但后来觉得文学界不争气，就从那里面走出来了。后来，我写的关于艺术品的小说比他们的文学小说还畅销。\n女：您怎么评价文学界和文物界？\n男：我觉得文物比文学好的一点在于：它比较深，而文学比较浅。好比，你原来是个吸烟者，那是文学；而搞文物的就是雪茄。等你吸了雪茄，你会发现香烟比较淡。文学的评价标准也是个问题，写诗可以有好坏，反正都能写，谁好谁坏也没有一个终极标准。但文物是一个很窄的领域，而且文物是有终极判断的。我发现，文物界很多人说起话来前言不搭后语，文物界的人都特别死板，眼界特窄，而我眼界比较宽。\n女：您介入公共事务极为频繁，前不久还在博客上写关于贪官什么的文章，这样做是要保持影响力，还是纯粹出于表达的欲望？\n男：博客我一年要写137篇，最近四年都是这个速度。对我而言，收藏只是生活中的一个调剂，我因为在《百家讲坛》说收藏而“红”了。但我觉得，这反而是我最不看重的事儿。如果说我是“收藏家”的话，那可能是因为我著书立说了。\n女：商人、作家、学者、收藏家，在这几种身份之间，您如何评价自己？\n男：我是一个学者，不是一个商人。我曾经和我儿子说“我能够做一个学者，是这个时代的不幸，是我自己的大幸。”我们不能和王国维、陈寅恪相比，我实际上没读过什么书，我们算什么？我们这个时代缺少文化，所以稍微读了一点儿书的人就显得有文化。\n问：男的怎样评价文物界？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [55, 56]}}, {"n": 8, "zh": "", "options": {"A": "他是个做事死板的人", "B": "他著有关于收藏的著作", "C": "他很喜欢《百家讲坛》", "D": "他一直在寻找表达机会"}, "transcript_zh": "女：您和中国的一线作家都有交情，海岩的第一件收藏品还是您帮他挑选的。您写过爱情小说，之后就去写文物了。\n男：我和这些作家关系都非常好，50岁以上、60岁以下的都认识，他们这些人本身都文学素养很高。他们年轻的时候，工作都是分配的，不能辞职。后来，慢慢地，很多人退出了文学圈。我曾经还是有些文学理想的，但后来觉得文学界不争气，就从那里面走出来了。后来，我写的关于艺术品的小说比他们的文学小说还畅销。\n女：您怎么评价文学界和文物界？\n男：我觉得文物比文学好的一点在于：它比较深，而文学比较浅。好比，你原来是个吸烟者，那是文学；而搞文物的就是雪茄。等你吸了雪茄，你会发现香烟比较淡。文学的评价标准也是个问题，写诗可以有好坏，反正都能写，谁好谁坏也没有一个终极标准。但文物是一个很窄的领域，而且文物是有终极判断的。我发现，文物界很多人说起话来前言不搭后语，文物界的人都特别死板，眼界特窄，而我眼界比较宽。\n女：您介入公共事务极为频繁，前不久还在博客上写关于贪官什么的文章，这样做是要保持影响力，还是纯粹出于表达的欲望？\n男：博客我一年要写137篇，最近四年都是这个速度。对我而言，收藏只是生活中的一个调剂，我因为在《百家讲坛》说收藏而“红”了。但我觉得，这反而是我最不看重的事儿。如果说我是“收藏家”的话，那可能是因为我著书立说了。\n女：商人、作家、学者、收藏家，在这几种身份之间，您如何评价自己？\n男：我是一个学者，不是一个商人。我曾经和我儿子说“我能够做一个学者，是这个时代的不幸，是我自己的大幸。”我们不能和王国维、陈寅恪相比，我实际上没读过什么书，我们算什么？我们这个时代缺少文化，所以稍微读了一点儿书的人就显得有文化。\n问：关于男的，下列哪项正确？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [55, 56]}}, {"n": 9, "zh": "", "options": {"A": "他认为自己是个幸运儿", "B": "他是个具有公益心的人", "C": "他喜欢学者，不喜欢商人", "D": "他认为这个时代学者众多"}, "transcript_zh": "女：您和中国的一线作家都有交情，海岩的第一件收藏品还是您帮他挑选的。您写过爱情小说，之后就去写文物了。\n男：我和这些作家关系都非常好，50岁以上、60岁以下的都认识，他们这些人本身都文学素养很高。他们年轻的时候，工作都是分配的，不能辞职。后来，慢慢地，很多人退出了文学圈。我曾经还是有些文学理想的，但后来觉得文学界不争气，就从那里面走出来了。后来，我写的关于艺术品的小说比他们的文学小说还畅销。\n女：您怎么评价文学界和文物界？\n男：我觉得文物比文学好的一点在于：它比较深，而文学比较浅。好比，你原来是个吸烟者，那是文学；而搞文物的就是雪茄。等你吸了雪茄，你会发现香烟比较淡。文学的评价标准也是个问题，写诗可以有好坏，反正都能写，谁好谁坏也没有一个终极标准。但文物是一个很窄的领域，而且文物是有终极判断的。我发现，文物界很多人说起话来前言不搭后语，文物界的人都特别死板，眼界特窄，而我眼界比较宽。\n女：您介入公共事务极为频繁，前不久还在博客上写关于贪官什么的文章，这样做是要保持影响力，还是纯粹出于表达的欲望？\n男：博客我一年要写137篇，最近四年都是这个速度。对我而言，收藏只是生活中的一个调剂，我因为在《百家讲坛》说收藏而“红”了。但我觉得，这反而是我最不看重的事儿。如果说我是“收藏家”的话，那可能是因为我著书立说了。\n女：商人、作家、学者、收藏家，在这几种身份之间，您如何评价自己？\n男：我是一个学者，不是一个商人。我曾经和我儿子说“我能够做一个学者，是这个时代的不幸，是我自己的大幸。”我们不能和王国维、陈寅恪相比，我实际上没读过什么书，我们算什么？我们这个时代缺少文化，所以稍微读了一点儿书的人就显得有文化。\n问：男的怎样看自己和自己所生活的时代？", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [55, 56]}}, {"n": 10, "zh": "", "options": {"A": "收藏能够让人眼界开阔", "B": "王国维、陈寅恪很有威望", "C": "男的的主要收入来源是写作", "D": "男的认可的身份是学者和商人"}, "transcript_zh": "女：您和中国的一线作家都有交情，海岩的第一件收藏品还是您帮他挑选的。您写过爱情小说，之后就去写文物了。\n男：我和这些作家关系都非常好，50岁以上、60岁以下的都认识，他们这些人本身都文学素养很高。他们年轻的时候，工作都是分配的，不能辞职。后来，慢慢地，很多人退出了文学圈。我曾经还是有些文学理想的，但后来觉得文学界不争气，就从那里面走出来了。后来，我写的关于艺术品的小说比他们的文学小说还畅销。\n女：您怎么评价文学界和文物界？\n男：我觉得文物比文学好的一点在于：它比较深，而文学比较浅。好比，你原来是个吸烟者，那是文学；而搞文物的就是雪茄。等你吸了雪茄，你会发现香烟比较淡。文学的评价标准也是个问题，写诗可以有好坏，反正都能写，谁好谁坏也没有一个终极标准。但文物是一个很窄的领域，而且文物是有终极判断的。我发现，文物界很多人说起话来前言不搭后语，文物界的人都特别死板，眼界特窄，而我眼界比较宽。\n女：您介入公共事务极为频繁，前不久还在博客上写关于贪官什么的文章，这样做是要保持影响力，还是纯粹出于表达的欲望？\n男：博客我一年要写137篇，最近四年都是这个速度。对我而言，收藏只是生活中的一个调剂，我因为在《百家讲坛》说收藏而“红”了。但我觉得，这反而是我最不看重的事儿。如果说我是“收藏家”的话，那可能是因为我著书立说了。\n女：商人、作家、学者、收藏家，在这几种身份之间，您如何评价自己？\n男：我是一个学者，不是一个商人。我曾经和我儿子说“我能够做一个学者，是这个时代的不幸，是我自己的大幸。”我们不能和王国维、陈寅恪相比，我实际上没读过什么书，我们算什么？我们这个时代缺少文化，所以稍微读了一点儿书的人就显得有文化。\n问：根据对话，下列哪项正确？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [55, 56]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–17题：请选出正确答案。", "items": [{"n": 11, "zh": "", "options": {"A": "他的家乡是湖南", "B": "他是个成功的商人", "C": "他是自学成才的木工", "D": "他从事美术教育工作"}, "transcript_zh": "齐白石1864年出生，籍贯湖南，是近现代中国绘画大师，世界文化名人。他早年曾做过木工，后以卖画为生，五十七岁后定居北京。齐白石书法、篆刻、诗文、绘画样样精通，并著有《白石诗草》及《白石老人自述》等。\n居住在北京的齐白石，内心装着的却是家乡的山水、家乡的草木。无奈他不可能将家乡草木带到北京，于是这种情思便化作艺术信息传达出来。他刻了许多寄托着怀乡之情的印章，写了许多怀乡诗，那些诗句无一不是齐白石“夜不安眠”时的肺腑之言。\n齐白石的作品《我最知鱼》，画的是小鱼追逐钓钩和鱼饵的情景，而那正是齐白石少年时常做的事情，他怎会不“知鱼”？齐白石画中的黑蜻蜓、红甲虫，家乡人叫作“黑婆子”“红娘子”，这正是农民的审美情趣；齐白石画鲇鱼题“年年有余”，画石榴象征多子，画桃子象征多寿，也都是民间艺术的喻意象征。这些作品，无一不是齐白石的恋乡情结和童真情趣的自然流露。\n问：关于齐白石，下列哪项正确？", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [56, 57]}}, {"n": 12, "zh": "", "options": {"A": "夜里总是睡不好觉", "B": "院里种了许多花草", "C": "心中充满思乡之情", "D": "学会了写诗、刻印章"}, "transcript_zh": "齐白石1864年出生，籍贯湖南，是近现代中国绘画大师，世界文化名人。他早年曾做过木工，后以卖画为生，五十七岁后定居北京。齐白石书法、篆刻、诗文、绘画样样精通，并著有《白石诗草》及《白石老人自述》等。\n居住在北京的齐白石，内心装着的却是家乡的山水、家乡的草木。无奈他不可能将家乡草木带到北京，于是这种情思便化作艺术信息传达出来。他刻了许多寄托着怀乡之情的印章，写了许多怀乡诗，那些诗句无一不是齐白石“夜不安眠”时的肺腑之言。\n齐白石的作品《我最知鱼》，画的是小鱼追逐钓钩和鱼饵的情景，而那正是齐白石少年时常做的事情，他怎会不“知鱼”？齐白石画中的黑蜻蜓、红甲虫，家乡人叫作“黑婆子”“红娘子”，这正是农民的审美情趣；齐白石画鲇鱼题“年年有余”，画石榴象征多子，画桃子象征多寿，也都是民间艺术的喻意象征。这些作品，无一不是齐白石的恋乡情结和童真情趣的自然流露。\n问：齐白石定居在北京后，有什么变化？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [56, 57]}}, {"n": 13, "zh": "", "options": {"A": "专门为孩子创作", "B": "充满了童真童趣", "C": "内容深受城市人的喜爱", "D": "借鉴了民间艺术的手法"}, "transcript_zh": "齐白石1864年出生，籍贯湖南，是近现代中国绘画大师，世界文化名人。他早年曾做过木工，后以卖画为生，五十七岁后定居北京。齐白石书法、篆刻、诗文、绘画样样精通，并著有《白石诗草》及《白石老人自述》等。\n居住在北京的齐白石，内心装着的却是家乡的山水、家乡的草木。无奈他不可能将家乡草木带到北京，于是这种情思便化作艺术信息传达出来。他刻了许多寄托着怀乡之情的印章，写了许多怀乡诗，那些诗句无一不是齐白石“夜不安眠”时的肺腑之言。\n齐白石的作品《我最知鱼》，画的是小鱼追逐钓钩和鱼饵的情景，而那正是齐白石少年时常做的事情，他怎会不“知鱼”？齐白石画中的黑蜻蜓、红甲虫，家乡人叫作“黑婆子”“红娘子”，这正是农民的审美情趣；齐白石画鲇鱼题“年年有余”，画石榴象征多子，画桃子象征多寿，也都是民间艺术的喻意象征。这些作品，无一不是齐白石的恋乡情结和童真情趣的自然流露。\n问：齐白石的作品有什么特点？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [56, 57]}}, {"n": 14, "zh": "", "options": {"A": "是祖父收购来的", "B": "看起来平平常常", "C": "买时价格很便宜", "D": "如今已经是孤品"}, "transcript_zh": "一走进汪先生的家，我就看到他收藏的“宝贝”，有明代的漆器，清代的银碗和各种古典家具，不过数量最多的还是玉器。\n汪先生家原本有些祖传物件，如今均已失传，只剩下一个玉笔筒。听着汪先生的介绍，我注意到他家书桌上那个插着几支笔的青玉笔筒，虽貌不惊人，却别有情趣。\n汪先生说，这个玉笔筒是他父亲年轻时买的，当时花了一块大洋。那时一块大洋可值不少钱，所以笔筒价格不算便宜。他的父亲是一名中医，他买这笔筒是为了自己用，并不为收藏。\n汪先生从小看着这个笔筒长大，慢慢对老物件有了兴趣。后来，他随父母迁移到新疆伊犁,有机会接触到和田美玉。那时候和田玉的价格不像现在这么疯狂。当地居民都能接触到和田玉，少数民族居民身上都佩戴有玉器。汪先生觉得它们很漂亮，他喜欢玉的内在美感，从此汪先生成了玉器收藏者。\n问：关于玉笔筒，下列哪项正确？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [57, 58]}}, {"n": 15, "zh": "", "options": {"A": "他是一名中医", "B": "玉器是他的最爱", "C": "小时候就居住在新疆", "D": "把祖传玉器都处理了"}, "transcript_zh": "一走进汪先生的家，我就看到他收藏的“宝贝”，有明代的漆器，清代的银碗和各种古典家具，不过数量最多的还是玉器。\n汪先生家原本有些祖传物件，如今均已失传，只剩下一个玉笔筒。听着汪先生的介绍，我注意到他家书桌上那个插着几支笔的青玉笔筒，虽貌不惊人，却别有情趣。\n汪先生说，这个玉笔筒是他父亲年轻时买的，当时花了一块大洋。那时一块大洋可值不少钱，所以笔筒价格不算便宜。他的父亲是一名中医，他买这笔筒是为了自己用，并不为收藏。\n汪先生从小看着这个笔筒长大，慢慢对老物件有了兴趣。后来，他随父母迁移到新疆伊犁,有机会接触到和田美玉。那时候和田玉的价格不像现在这么疯狂。当地居民都能接触到和田玉，少数民族居民身上都佩戴有玉器。汪先生觉得它们很漂亮，他喜欢玉的内在美感，从此汪先生成了玉器收藏者。\n问：关于汪先生的父亲，下列哪项正确？", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [57, 58]}}, {"n": 16, "zh": "", "options": {"A": "当地居民大多收藏玉器", "B": "和田玉的价格历来很贵", "C": "当地居民都能接触玉器", "D": "当地居民对玉都很在行"}, "transcript_zh": "一走进汪先生的家，我就看到他收藏的“宝贝”，有明代的漆器，清代的银碗和各种古典家具，不过数量最多的还是玉器。\n汪先生家原本有些祖传物件，如今均已失传，只剩下一个玉笔筒。听着汪先生的介绍，我注意到他家书桌上那个插着几支笔的青玉笔筒，虽貌不惊人，却别有情趣。\n汪先生说，这个玉笔筒是他父亲年轻时买的，当时花了一块大洋。那时一块大洋可值不少钱，所以笔筒价格不算便宜。他的父亲是一名中医，他买这笔筒是为了自己用，并不为收藏。\n汪先生从小看着这个笔筒长大，慢慢对老物件有了兴趣。后来，他随父母迁移到新疆伊犁,有机会接触到和田美玉。那时候和田玉的价格不像现在这么疯狂。当地居民都能接触到和田玉，少数民族居民身上都佩戴有玉器。汪先生觉得它们很漂亮，他喜欢玉的内在美感，从此汪先生成了玉器收藏者。\n问：关于和田玉，下列哪项正确？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [57, 58]}}, {"n": 17, "zh": "", "options": {"A": "祖上就有收藏的传统", "B": "感受到收藏能赚大钱", "C": "天天看笔筒就喜欢上玉了", "D": "他领略到了玉的内在之美"}, "transcript_zh": "一走进汪先生的家，我就看到他收藏的“宝贝”，有明代的漆器，清代的银碗和各种古典家具，不过数量最多的还是玉器。\n汪先生家原本有些祖传物件，如今均已失传，只剩下一个玉笔筒。听着汪先生的介绍，我注意到他家书桌上那个插着几支笔的青玉笔筒，虽貌不惊人，却别有情趣。\n汪先生说，这个玉笔筒是他父亲年轻时买的，当时花了一块大洋。那时一块大洋可值不少钱，所以笔筒价格不算便宜。他的父亲是一名中医，他买这笔筒是为了自己用，并不为收藏。\n汪先生从小看着这个笔筒长大，慢慢对老物件有了兴趣。后来，他随父母迁移到新疆伊犁,有机会接触到和田美玉。那时候和田玉的价格不像现在这么疯狂。当地居民都能接触到和田玉，少数民族居民身上都佩戴有玉器。汪先生觉得它们很漂亮，他喜欢玉的内在美感，从此汪先生成了玉器收藏者。\n问：汪先生对玉的爱好是怎样形成的？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [57, 58]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第18–20题：请选出有语病的一项。", "items": [{"n": 18, "zh": "", "options": {"A": "一个人的成长，是需要经过无数坎坷的道路。", "B": "刘邦死后，皇后吕雉成了汉朝事实上的女皇帝。", "C": "我老家的天气是温和的，严冬时，水面也只结一层薄冰。", "D": "经过新闻媒体的跟踪报道，这一事件立刻成为街谈巷议的热门话题。"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 19, "zh": "", "options": {"A": "他做了大官，家里的生活照样十分朴素，跟普通百姓一样。", "B": "一时间，去新兴镇参观取经看热闹瞧新鲜的人滔滔似水，络绎不绝。", "C": "中国农村正在变成空心村，外出上学、务工，年轻人都流向了城市。", "D": "我到财务室交了钱，拿了取书单，财务室的同志告诉我要到书库去取书。"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 20, "zh": "", "options": {"A": "段文杰如此深厚的临摹功力，来源于他献身敦煌艺术的诚心和对后人负责的决心以及艺术上精益求精的恒心。", "B": "尽管应试教育弊端多多，但它目前相对来说确实是最为公正的选拔办法，到目前为止，人们无法找出比应试教育更好的选拔人才的方式。", "C": "语言对于社会全体成员来说是统一的、共同的，不论王公贵族、学术泰斗，还是贩夫走卒、农妇渔夫，都得遵守社会的语言习惯，谁都不能例外。", "D": "火一样的太阳先是烧红了西部的整片天空，然后又放射出金色光芒，而蓝天和白云也没有忘记前来取暖，这样就逐渐形成了五彩缤纷、变化多端的晚霞。"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第21–23题：选词填空。", "items": [{"n": 21, "zh": "晏殊14岁时被作为神童________给皇帝。皇帝要考考他，让他和一千多名最有学问的人一同参加考试。结果晏殊发现考题是自己练习过的，就________告诉了皇帝，并请求________题目。皇帝因此十分感动。", "options": {"A": "推荐　如实　更改", "B": "介绍　公然　改变", "C": "推选　趁早　变化", "D": "保举　当众　改正"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 22, "zh": "________人们只把这种以口述历史为基本特征的研究，作为一般记者的采访来________，很少谈及它的学术价值和方法意义。近年，在中国现当代文学研究中，最有新意的就是________口述方法的________。", "options": {"A": "往年　接纳　选择　著述", "B": "平素　接受　选取　创作", "C": "平昔　看待　动用　大作", "D": "以往　对待　采用　作品"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 23, "zh": "说起垃圾分类回收，________一个家庭并没有从中获得________的收益，但其社会效益却是________的，一是使有限的地球资源重复使用，以________子孙后代的生存需要，二是减少垃圾量，减轻对环境的污染。", "options": {"A": "或者　多少　庞大　解决", "B": "或许　可观　巨大　满足", "C": "分明　分毫　宏伟　适应", "D": "绝对　半点　重大　配合"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第24–28题：选句填空。\n从前有个人叫淳于棼，他家院中有一棵大槐树，盛夏时节人们都喜欢在树下乘凉。\n淳于棼生日那天，亲友都来祝寿，（24）________，之后就在槐树下沉沉睡去。\n梦中，他到了大槐安国，正赶上京城会试。他报名进了考场，考得很争气，居然得了第一名。皇帝看他学问好，相貌也好，就把公主嫁给了他。\n婚后，夫妻生活十分美满。淳于棼被皇帝任命为太守，（25）________。因他管理有方，属下不敢胡作非为，百姓十分拥护他。皇帝欣赏他的政绩，表彰了他，并给了他很多奖励和荣誉。\n这一年，敌兵入侵，大槐安国的将军被敌兵打得溃不成军。皇帝急忙召集群臣商议对策。（26）________，束手无策。这时，有人向皇帝推荐淳于棼。皇帝立即下令，让淳于棼率全国精锐与敌军决战。\n（27）________，与敌兵刚一接触，就败下阵来。皇帝大怒，撤了淳于棼的职务。淳于棼气得大叫一声，从梦中惊醒，但见月亮挂在树梢上，自己还在大槐树下。\n此后汉语就有了成语“南柯一梦”，（28）________。", "items": [{"n": 24, "zh": "淳于棼生日那天，亲友都来祝寿，（24）________，之后就在槐树下沉沉睡去。", "options": {"A": "一干就是20年", "B": "用来形容梦境或不可能实现的空想", "C": "大臣们你看我，我看你", "D": "可怜淳于棼对兵法一无所知", "E": "他一时高兴多喝了几杯"}, "answer": "E", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 25, "zh": "淳于棼被皇帝任命为太守，（25）________。", "options": {"A": "一干就是20年", "B": "用来形容梦境或不可能实现的空想", "C": "大臣们你看我，我看你", "D": "可怜淳于棼对兵法一无所知", "E": "他一时高兴多喝了几杯"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 26, "zh": "皇帝急忙召集群臣商议对策。（26）________，束手无策。", "options": {"A": "一干就是20年", "B": "用来形容梦境或不可能实现的空想", "C": "大臣们你看我，我看你", "D": "可怜淳于棼对兵法一无所知", "E": "他一时高兴多喝了几杯"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 27, "zh": "（27）________，与敌兵刚一接触，就败下阵来。", "options": {"A": "一干就是20年", "B": "用来形容梦境或不可能实现的空想", "C": "大臣们你看我，我看你", "D": "可怜淳于棼对兵法一无所知", "E": "他一时高兴多喝了几杯"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 28, "zh": "此后汉语就有了成语“南柯一梦”，（28）________。", "options": {"A": "一干就是20年", "B": "用来形容梦境或不可能实现的空想", "C": "大臣们你看我，我看你", "D": "可怜淳于棼对兵法一无所知", "E": "他一时高兴多喝了几杯"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第四部分（29–32）", "type_zh": "阅读 第四部分", "instruction_zh": "第29–36题：请选出正确答案。\n29–32.\n古人发明文字之后，最早用来做书写材料的是甲骨，后来竹片、木片以及缣帛也被用来书写。但竹片的笨重可想而知，缣帛的昂贵不言而喻，于是便有了纸的发明。\n中国西汉（前206年～公元25年）时期已开始了纸的制作，东汉（25年～220年）时期，造纸技术得以完善，魏晋南北朝（220年～589年）时期，造纸原料多样化，藤皮、稻草、麦秆纤维，甚至烂鱼网、破布在匠人的手下都能变成质地优良的好纸。需求也促进了造纸技术的提高，隋唐时期，著名的宣纸诞生。为了延长纸的寿命，晋时又发明了染纸技术，即从植物黄蘖中熬取汁液，浸染纸张，染过的纸叫黄纸，又叫黄麻纸，有灭虫防蛀的功能。唐代人在染黄纸的基础上创造出了较为名贵的艺术加工纸——硬黄纸。五代制造的澄心堂纸，直到北宋，一直被公认为是最好的纸张。到了明清，又有了新的创意，作为文书用纸的笺纸被加工得精美绝伦。\n中国出土最早的纸张是1933年在新疆发掘出的西汉古纸，年代不晚于公元前49年。1957年在陕西出土的古纸经过分析鉴定，为西汉麻纸，年代不晚于公元前118年。1986年在甘肃出土的西汉初年（约前179年～前141年）的纸质地图残片，表明了当时的纸已可供写绘之用。", "items": [{"n": 29, "zh": "古人发明纸的原因是：", "options": {"A": "骨头数量有限", "B": "竹片工艺烦琐", "C": "丝织品要做衣服", "D": "之前的材料都有缺憾"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 30, "zh": "关于古代造纸技术，下列哪项正确？", "options": {"A": "东汉水平最高", "B": "讲究化腐朽为神奇", "C": "努力适应市场需求", "D": "专门在细节上下功夫"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 31, "zh": "在漫长的历史中：", "options": {"A": "虫子一直对纸形成威胁", "B": "宣纸在纸张中十分有名", "C": "明清造纸技术达到了顶峰", "D": "工匠们一直追求的就是精美"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 32, "zh": "根据纸张的出土情况可以知道：", "options": {"A": "西汉是纸张用量最大的时期", "B": "西汉时期是纸张泛滥的年代", "C": "西汉生产的纸张已可绘制地图", "D": "1933年出土的纸是最早生产的纸"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第四部分（33–36）", "type_zh": "阅读 第四部分", "instruction_zh": "33–36.\n齐家文化古玉收藏家岳先生曾是个搞技术工作的军人。几十年的军旅生涯使他的足迹遍及祖国西北大漠戈壁，江南水乡，他亦曾多次远洋航行，颠簸于大风大浪之中。艰苦的生活磨炼了他的意志，严谨精细的技术工作又养成了他追根求底的性格特质。这对于他后来鉴定齐家文化古玉，破解其中蕴含的历史信息，打下了牢固的基础。\n齐家文化的玉器距今已有四五千年的历史，其中蕴含着丰富的文化信息，而岳先生偏偏对齐家文化古玉情有独钟。他发现，齐家玉器上一些细微特征所呈现的信息是多方位的。如立式玉人，手举斧头，腰际围一圈树叶遮蔽下身，斧头的头与柄由交叉绑系的绳索固定。这使得我们通常认知的史前先人腰围树叶的衣饰，以及斧、铲等工具与手柄捆绑系接的方法进一步在齐家古玉中得到佐证。\n提起古玉收藏，岳先生常说自己幸运，沾了改革开放的光，那时普通人的经济状况没有条件收藏，民间收藏品市场真品有的是，无奈的是囊中羞涩。岳先生节俭得近乎吝啬，却在浩如烟海的旧器物中搜寻到了不少上了级别的藏品。", "items": [{"n": 33, "zh": "岳先生认为自己收藏古玉的有利条件是：", "options": {"A": "他爱学习，阅历丰富", "B": "他走南闯北，有见识", "C": "他精通考古挖掘技术", "D": "他幸运地赶上了改革开放"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 34, "zh": "齐家玉器中的立式玉人：", "options": {"A": "上衣是树叶", "B": "上面标有朝代", "C": "有被捆绑过的痕迹", "D": "证实了人们对史前先人的一些认知"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 35, "zh": "根据上文，岳先生：", "options": {"A": "喜欢旅游", "B": "当过空军", "C": "钟情于齐家玉器", "D": "常为没钱而发愁"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 36, "zh": "最后一段画线词语“真品有的是”的意思是：", "options": {"A": "是真品", "B": "没有真品", "C": "有些是真品", "D": "真品特别多"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}], "answers_ref": {"book": "workbook_answers", "pages": [54, 55, 56, 57, 58, 94, 95, 96, 97, 98, 99, 100]}}, "unclear": ["HSK6-д багшийн ном байхгүй тул teacher талбар орхисон. Сурах бичгийн注释/练一练 (尚且, 当), 词语辨析 做一做 (温和——温柔) болон 练习1–4-ийн хариултыг BLCUP 课本参考答案 (HSK6 下Answer Textbook.pdf х.26–28)-аас нэмсэн. Дасгалын номын 听力 1–17-ийн бичвэр (transcript_zh) болон хариулт (answer, answer_ref, workbook.answers_ref) BLCUP 录音文本及答案 (HSK6下 Recording Text.pdf х.54–58)-аас нэмсэн. Харин дараах хэсэгт хариулт ямар ч эх сурвалжид хэвлэгдээгүй тул оруулаагүй: (三)篇章修辞 过渡-ийн 练一练 (赵州桥 A/B/C/D сонголт) — 课本参考答案 (х.26–28)-д алгасагдсан (зурагтай тулгаж нягталсан); дасгалын номын 阅读 18–36 — Recording Text.pdf зөвхөн 听力-ийн хариулт агуулдаг тул хариулт байхгүй; сурах бичгийн 练习5 (简述课文), 扩展 (词汇), 运用 (写一写) — нээлттэй/тайлбар шинжтэй тул хариулт байхгүй.", "Аудио файлын нэр мэдэгдэхгүй тул audio талбар орхисон. Сурах бичгийн CD тэмдэг: 课文 = 34-1, 生词 = 34-2; дасгалын номын 听力 第一部分 = 34-1, 第二部分 = 34-2, 第三部分 = 34-3.", "Хичээлийн гарчгийн пиньинь (title_pinyin) номд хэвлэгдээгүй — «Wèi wénwù ér shēng de rén» гэж стандарт дуудлагаар бичсэн (номоос биш; 文物 wénwù нь 生词 12). title_en номын гарчгийн доорх «A person who was born for cultural relics».", "课文 гарчигт «（1299字）» гэж хэвлэгдсэн — lines дахь цэг таслалтай нийт тэмдэгт = 1314, зөвхөн ханз = 1158; 脚注 тэмдэг (①②①) 3-ыг хасвал 1311 — номын 1299-өөс 12-оор илүү (бичвэрийг зурагтай мөр мөрөөр дахин тулгасан, орхисон/илүү ханз олдоогүй; зөрүүг таамаглаж засаагүй). 课文-ийн гарчиг = хичээлийн гарчиг. Пиньинь бичвэр хэвлэгдээгүй тул lines.pinyin байхгүй. 11 догол мөр — lines-ийг өгүүлбэрээр хуваасан; догол мөр эхлэх мөрийн дугаар (1-ээс): [1, 5, 6, 11, 14, 16, 19, 23, 29, 33, 35].", "课文 8-р догол мөрийн эхэнд «孙羸洲的子女们说» гэж 羸 (léi, доод дунд хэсэг 羊) ханзаар хэвлэгдсэн (PDF х.148, 400dpi-аар томруулж шалгасан) — бусад бүх газарт 孙瀛洲 (氵). Номын хэвлэлийн алдаа бололтой; lines-д номд байгаагаар «孙羸洲» гэж үлдээсэн.", "课文-ийн доор эх сурвалж: «改编自《北京青年报》文章《孙瀛洲曾捐上千文物给故宫 后人称是明智之举》» — схемд талбаргүй тул энд тэмдэглэв (lines-д оруулаагүй). 课文-д 脚注 3 бий (х.147: ① 孙瀛洲, ② 斗彩; х.148: ① 爱妃 — хуудас бүрт дугаар ①-ээс эхэлдэг тул lines-д «孙瀛洲①», «斗彩②», «爱妃①» гэж номын тэмдгээр) → textbook.culture {title_zh:«课文脚注»}-д бүтнээр. 文化/俗语 хэсэг байхгүй.", "生词 51 үг (1–51), * тэмдэгтэй үг байхгүй, 专有名词 хэсэг байхгүй. 11 络绎不绝, 44 精益求精 — үгийн ай (pos) хэвлэгдээгүй. Пиньинь номд байгаагаар: 11 «luòyì bù jué» (зайтай), 44 «jīngyìqiújīng» (зураасгүй, зайгүй), 14 «dǎ bāo», 40 «zhēng qì», 41 «zhān guāng» (зайтай), 16 图案 «tú’àn». Англи тайлбар номд байгаагаар: 24 采购 «n. purchase» (үгийн ай n.); 25 创业-ийн тайлбар 3 мөрт хэвлэгдсэн («to start an undertaking or a business, to do pioneering work»).", "热身1 — 4 зураг (2×2): 斗彩（dòucǎi）— цагаан дотортой, гадна талдаа өнгөт цэцэг/ургамлын хээтэй аяга; 糖葫芦（tánghúlu）— улаан бөөрөлзгөнө (山楂)-ийн шүүсэн чихэр модон шорлогт олноор; 陶瓷（táocí）— шар дэвсгэр дээр цэцгийн хээтэй дугуй таглаатай шаазан хайрцаг; 古玩（gǔwán）— улаан лакаар сийлсэн хээтэй дугуй таглаатай хайрцаг. Зургийн доорх пиньинийг items-д номд байгаагаар. 热身2 — 4 мөрт хүснэгт (衣/家/册/丰 | үгс), warmup[1].items-д мөр мөрөөр.", "注释 (一) 综合注释 2 зүйл (1 尚且, 2 当) → grammar 1–2; (二) 词语辨析 温和——温柔 (дугааргүй хайрцаг, хүснэгт) → grammar 3 (explanation_zh + structure_rows); (三) 篇章修辞 篇章（5）过渡 (дугааргүй хайрцаг) → grammar 4. Номын улаан өнгөөр хэвлэгдсэн жишээ = 课文-ийн өгүүлбэр → note_zh «课文句» (尚且 (1), 当 (1)(2)(3), 过渡 (1)(3)). 尚且 (1) нь 课文-ийн өгүүлбэрийн «孙女士感慨道，»-гүй хэсэг.", "注释2 当 — тайлбар «“当”，介词，意思是正在（那个时候、那个地方）» гэж хэвлэгдсэн боловч жишээнүүдэд 当年/当时/当代 үгс, 练一练-ийн үгсийн сан 当今　当场　当地 (гурван хоосон зай) — номд байгаагаар. 练一练-ийн сан practice_instruction_zh болон hint_zh-д.", "温和——温柔 хүснэгт: 共同点 мөр хоёр баганад нэгтгэгдсэн; 不同点 2-т 温柔 баганын «2. 没有左边这个用法。» нүд 温和 баганын 2 мөр (тайлбар + жишээ)-тэй нэгтгэгдсэн. Жишээнд 温和/温柔 үгс хөх өнгөөр тодотгогдсон. 做一做 «判断正误» — өгүүлбэр бүрийн төгсгөлд хоосон хаалт «（　　）», хариулт байхгүй.", "篇章（5）过渡 жишээ (2) (鲸-ийн тухай) хар өнгөөр, хоёр догол мөр, догол бүрийн дараа «……» мөр; (3) нь «……»-ээр эхэлж, дунд нь «……» мөр. Хаалтан доторх «（“可是”为过渡词）» гэх мэт тайлбарыг note_zh-д. 练一练 (赵州桥) — 4 догол мөрт бичвэр, A/B/C/D байрлалын үсэг номд хэвлэгдсэн; practice[0].options-д A–D (зөвхөн байрлалын тэмдэг).", "练习1 模仿例子： доогуур цэгтэй ханз — 例 温和 (温), 赠送 (赠), 皇帝 (皇), 创业 (创), 荣誉 (荣); hint_zh-д. Жишээ мөр «温和：温柔 温顺 温厚 温情» номд хэвлэгдсэн (n=«例»).", "练习3 选词填空： 2 догол бичвэр, тус бүр өөрийн 5 үгийн сан (word_bank 2 бүлэг, hint_zh-д давтсан). ② бичвэрт 6 хоосон зай байгаа боловч үгийн сан 5 үгтэй (沾光 салангид үг — «不想____父亲的____» хоёр зайд хуваагдах бүтэцтэй) — номд байгаагаар, хариулт тавиагүй.", "练习4 — бичвэр бүрийн доор 2 хоосон мөр → zh-д «\\n________\\n________». 练习5 — номд хүснэгт (зүүн багана: асуулт, баруун: сануулга). 运用 — зөвхөн «写一写» (400 орчим ханзаар 缩写).", "扩展 — «词汇：熟悉下列表示人物身份的词语» 13 мөрт хүснэгт (词语 | 释义), зураггүй; items-д «词语 | 释义». Энэ хэсэгт 做一做 байхгүй.", "Дасгалын ном (PDF х.121–128) — 听力 1–17 + 阅读 18–36, нийт 36 асуулт. Энэ хичээлд 三、书写 хэсэг байхгүй (дараагийн хуудас х.129 = 第35课).", "Дасгалын ном 阅读 18B «吕雉» (500dpi-аар томруулж шалгасан — 矢+隹). 20A «临摹». 21–23: сонголт бүр 3–4 үгийн багц — options-д «　» (бүтэн өргөнтэй зай)-гаар холбосон. 21-д «晏殊 14 岁» тоо орчимд зай хэвлэгдсэн, 23-т «回收,» нарийн таслал — бүтэн өргөнтэй «，» болгосон, зайг хассан.", "Дасгалын ном 阅读 24–28 (淳于棼-ийн тухай, «南柯一梦»): бичвэр section.instruction_zh-д, сонголт A–E бүх item-д давтсан; бичвэрийн баруун талд харанхуй хийсвэр зураг (эргэлдэх утаа мэт дэвсгэр дээр зүрхэн дүрс, нотны шугам). «“南柯一梦”,（28）» хаалтны өмнөх таслал нарийсгасан — бүтэн өргөнтэй болгосон. (27) догол мөр бусдаасаа бага догол зайтай хэвлэгдсэн.", "Дасгалын ном 阅读 29–32 (цаасны түүх) — бичвэрийн зүүн талд боож овоолсон цагаан цаасны (宣纸) багцын зураг, шошгон дээр «宣», «纸» ханз харагдана. «黄蘖» (艹+辥+木; 450dpi-аар шалгасан), «缣帛», «笺纸», «澄心堂纸». Он тооллын «～» номд байгаагаар. 33–36 (齐家文化古玉, 岳先生) — баруун талд харанхуй дэвсгэр дээрх цайвар хаш чулуун жижиг амьтны (мэрэгч мэт) баримлын зураг; сүүлийн догол мөрийн «真品有的是» доогуур зураастай (36-р асуултын «画线词语»). 29–36 нэг заавар («第29–36题») — хоёр бичвэрийг тус тусын section-д.", "（三）篇章修辞 过渡-ийн 练一练 (赵州桥 过渡句-ийн зөв байрлал сонгох, A/B/C/D)-ийн хариулт BLCUP 课本参考答案 (HSK6 下Answer Textbook.pdf х.26–28)-д хэвлэгдээгүй — тэнд «（三）篇章修辞» гарчгийн дор шууд «练习1–4» (= сурах бичгийн 练习 хэсгийн 1–4-ийн хариулт) ирдэг, 过渡-ийн 练一练-д тусад нь хариулт байхгүй (х.27 зурагтай тулгаж нягталсан). Иймд grammar[3].practice-д answer нэмээгүй.", "练习3 选词填空 item1 (衣着朴素 хуучин хүний тухай догол): item.zh-д 5 хоосон зай байгаа («衣着________»«坐着________»«甚至可以说________»«但他________资助»«数额相当________»), word_bank 5 үгтэй (颠簸、无偿、朴素、可观、吝啬), гэвч 课本参考答案 (х.27)-д зөвхөн 4 хариулт хэвлэгдсэн («朴素»«颠簸»«吝啬»«可观» — «但他____资助» гэсэн 4-р хоосон зайд харгалзах «无偿» хариулт номд тавигдаагүй, тухайн мөр зурагт ч хоосон зайгүйгээр «但他资助了…» гэж хэвлэгдсэн). Иймд item1.answer-д номд хэвлэгдсэн 4 хариултаар бүтэн өгүүлбэр болгосон («…甚至可以说吝啬，但他资助了许多贫困地区的孩子读书。…»), «无偿» үгийг таамаглан оруулаагүй.", "练习4 (找出过渡词、过渡句) — item бүрийн zh-д 2 хоосон мөр («________\\n________», 过渡词 ба 过渡句 тус тусад нь бичих зориулалттай) байгаа боловч 课本参考答案 (х.27–28)-д item бүрт ЗӨВХӨН НЭГ хариулт хэвлэгдсэн («拿小丽来说»«反之»«总而言之»«但俗话说»). Тухайн хэллэг нь эх бичвэрт过渡词, 过渡句 хоёулангийнх нь үүрэг гүйцэтгэдэг тул номын дагуу ганц хариултыг item.answer-д оруулсан (хоёр хоосон мөрийг тус тусад нь ялгаж хариулаагүй).", "Дасгалын номын 阅读 18–36-ийн хариултыг BLCUP 录音文本及答案 (HSK6下 Recording Text.pdf) төгсгөлийн нэгдсэн 参考答案 хүснэгт (х.94–100)-ээс нэмсэн; 听力 1–17-ийн inline хариулттай тулгасан."], "verified_pages": [146, 147, 148, 149, 150, 151, 152, 153, 154, 155, 156, 121, 122, 123, 124, 125, 126, 127, 128], "schema_version": 1}'::jsonb, 1, 'image_verified')
