insert into public.hsk_source_lessons (id, level, book, lesson, title_zh, title_pinyin, title_en, payload, schema_version, status)
values ('hsk6-l35', 'hsk6', 'HSK6B', 35, '走近木版年画', 'Zǒujìn mùbǎn niánhuà', 'Approaching the woodblock New Year Pictures', '{"level": "hsk6", "lesson": 35, "book": "HSK6B", "title_zh": "走近木版年画", "title_pinyin": "Zǒujìn mùbǎn niánhuà", "title_en": "Approaching the woodblock New Year Pictures", "textbook": {"ref": {"book": "textbook", "pages": [157, 158, 159, 160, 161, 162, 163, 164, 165, 166, 167]}, "warmup": [{"instruction_zh": "对照图片熟悉下列物品的名称，并想一想这些东西跟什么有关系？", "instruction_en": "Warm-up", "items": ["门神画（ménshén huà）", "碑刻（bēikè）", "拓印（tàyìn）", "墨（mò）", "印章（yìnzhāng）", "雕版（diāobǎn）"], "pictures_desc_en": ["1 (门神画): a pair of red door-god prints, each showing an armoured warrior deity in bright colours", "2 (碑刻): a tall stone stele carved with four large red characters in traditional script (五嶽獨宗), trees behind", "3 (拓印): a black rubbing of a stone inscription in cursive calligraphy, white characters on black", "4 (墨): a black ink stick with gold characters lying on paper with brush calligraphy", "5 (印章): a stone seal with a carved animal top beside a round red ink paste box, red seal impressions on calligraphy paper", "6 (雕版): carved wooden printing blocks with relief pictures, stacked on a table"]}, {"instruction_zh": "想一想下列词语之间有什么联系。", "items": ["画 | 门神画、年画、版画、油画、国画、漫画、书画、图画、字画、动画、画家、画展、画报、画册", "展 | 拓展、开展、发展、进展、扩展、伸展、舒展、延展、展开、展翅、愁眉不展", "墨 | 墨水、墨点、墨盒、墨汁、淡墨、浓墨、磨墨、油墨、水墨画", "花 | 花朵、花草、花丛、花木、花卉、花鸟、花瓶、花盆、花坛、花农、花园、鲜花、种花"]}], "texts": [{"n": 1, "title_zh": "走近木版年画", "title_en": "Approaching the woodblock New Year Pictures", "kind": "narrative", "lines": [{"zh": "年画的起源"}, {"zh": "年画是中国画的一种，始于古代的门神画。"}, {"zh": "有文献记载：传说很久以前，有一对兄弟，专门监督百鬼，发现凶恶的鬼就捆绑起来，无须揭露恶行，直接去喂老虎。"}, {"zh": "于是有人在门上画上他们兄弟二人的像，用以防鬼，这就是最早的门神画。"}, {"zh": "随着唐宋两朝经济的发展，文化的昌盛以及民间绘画水平的提高，门神画的内容得以拓展，反映世俗生活题材的作品进入了这一领域。"}, {"zh": "之后，有清朝学者在论述这类画作时正式使用了“年画”一词，自此，以驱逐祸凶、祝福新年吉祥喜庆为内容的画儿就叫年画了。"}, {"zh": "木版年画"}, {"zh": "造纸技术的发明是人类文化发展史上一个重要的里程碑。"}, {"zh": "有了纸，书写就需要墨水儿，于是有人发明了墨；字画、书信上需要盖章，于是印章开始流行；碑刻、拓印技术被广泛运用，于是有人联想到：这些技术结合起来，不就能印出书来吗！"}, {"zh": "人们尝试把印章扩大成一张纸那么大，叫作“版”，然后把书的内容刻在版上，在版上涂抹上墨，把纸铺到上面，用刷子均匀地刷印，最后将纸揭起，印品就出来了，这就是最早的雕版印刷。"}, {"zh": "虽然雕版印刷中雕刻版面需要大量的人工和材料，但雕版完成后一经开印，就显示出空前的高效率和印刷量大的优越性。"}, {"zh": "单色印品终究不能满足人们的审美需求，之后就有了彩色套印技术。"}, {"zh": "人们把这种技术运用到年画制作上，木版彩色套印年画就此诞生。"}, {"zh": "宋明两代，木版年画从问世走向成熟，之后走进了百姓生活，以至过年贴年画成为了一种风尚，仿佛没有年画，没有烟花爆竹，没有春联就不叫过年，而寄托着百姓美好愿望的年画，也为春节增添了浓浓的年味。"}, {"zh": "当时的另一盛况是，家族式的年画印制场所遍及全国各地。"}, {"zh": "这期间，年画的内容也从威武的门神，扩展到期盼丰收、恭喜发财、连年有余的吉庆画，再到历史故事、戏曲人物、民间笑话、寓言和神话，内容无所不包。"}, {"zh": "年画成了文化交流、道德教育、信仰传承的载体与工具，是老百姓喜闻乐见的文化艺术形式。"}, {"zh": "年画传人张光宁"}, {"zh": "第一次见到张光宁的木版年画，是在春节庙会上。"}, {"zh": "在众多摊位中，他的两只木版彩色套印技术做成的布老虎神气极了。"}, {"zh": "那虎翘着尾巴，神态逼真，身上装饰着彩绘花纹和盛开的花朵，全身散发着喜气。"}, {"zh": "我问多少钱，他耸耸肩，对我说：“这是魏州虎。”"}, {"zh": "言外之意是在告诉我这个外行，这虎可是系出名门。"}, {"zh": "我心想：“魏州是哪儿？我不知道别人也未必知道，这算什么推销术？”"}, {"zh": "这是他给我留下的第一印象。"}, {"zh": "“这个卖年画的不像个商人”，这是他给我留下的第二印象。"}, {"zh": "当你和他讨价还价的时候，他立刻就变得不好意思起来，说话吞吞吐吐。"}, {"zh": "什么“这是纯手工的”“残次品不可避免”这些现成的“谢绝”还价的理由他一条也说不出来，相反却唠唠叨叨地总想和你讨论木版年画中深厚的文化底蕴。"}, {"zh": "相识久了才知道，他在年画的故乡出生、长大，从小就画年画，基本功扎实，后来又对年画的构图创作、人物塑造、雕版手法、颜料加工等进行了广泛的研究。"}, {"zh": "当他的作品逐步被市场认可后，他又不满足了，中国年画虽不分派别，但不同地区的年画各有所长，都值得学习借鉴。"}, {"zh": "于是，他再接再厉，数年间走遍了全国各大年画产地，与同行进行广泛的交流。"}, {"zh": "不仅如此，参加民俗文化巡展，走进大学和师生就相关主题进行研讨，交流艺术心得，他从不缺席。"}, {"zh": "张光宁一年到头真够忙的，可他总是干劲十足。"}, {"zh": "他曾真诚地说：“年画占据了我生命的全部，我喜欢它，热爱它，靠它生活，也在努力探索它、发展它。”"}, {"zh": "是啊，愈是经营年画久了，他对年画就愈是热爱。"}, {"zh": "他已确立了自己的目标——传播他喜爱的这一民俗文化。"}, {"zh": "他的信念就是拓展年画的内容，使其雅俗共赏，为更多民众所喜爱，虽然任重道远，也不会一帆风顺，但他一定会坚持下去。"}], "new_words": [{"n": 1, "zh": "起源", "pinyin": "qǐyuán", "pos": "n.", "en": "origin, beginning", "text": 1}, {"n": 2, "zh": "文献", "pinyin": "wénxiàn", "pos": "n.", "en": "document, literature", "text": 1}, {"n": 3, "zh": "凶恶", "pinyin": "xiōng’è", "pos": "adj.", "en": "fierce, vicious", "text": 1}, {"n": 4, "zh": "揭露", "pinyin": "jiēlù", "pos": "v.", "en": "to expose, to uncover", "text": 1}, {"n": 5, "zh": "昌盛", "pinyin": "chāngshèng", "pos": "adj.", "en": "prosperous, flourishing", "text": 1}, {"n": 6, "zh": "题材", "pinyin": "tícái", "pos": "n.", "en": "subject, theme", "text": 1}, {"n": 7, "zh": "驱逐", "pinyin": "qūzhú", "pos": "v.", "en": "to drive out, to expel", "text": 1}, {"n": 8, "zh": "吉祥", "pinyin": "jíxiáng", "pos": "adj.", "en": "lucky, propitious", "text": 1}, {"n": 9, "zh": "里程碑", "pinyin": "lǐchéngbēi", "pos": "n.", "en": "milestone", "text": 1}, {"n": 10, "zh": "墨水儿", "pinyin": "mòshuǐr", "pos": "n.", "en": "ink", "text": 1}, {"n": 11, "zh": "盖章", "pinyin": "gài zhāng", "en": "to seal, to stamp", "text": 1}, {"n": 12, "zh": "联想", "pinyin": "liánxiǎng", "pos": "v.", "en": "to associate, to connect in the mind", "text": 1}, {"n": 13, "zh": "涂抹", "pinyin": "túmǒ", "pos": "v.", "en": "to paint, to daub", "text": 1}, {"n": 14, "zh": "终究", "pinyin": "zhōngjiū", "pos": "adv.", "en": "eventually, in the end, after all", "text": 1}, {"n": 15, "zh": "烟花爆竹", "pinyin": "yānhuā bàozhú", "en": "fireworks, firecrackers", "text": 1}, {"n": 16, "zh": "寄托", "pinyin": "jìtuō", "pos": "v.", "en": "to place (hope, etc.) on", "text": 1}, {"n": 17, "zh": "增添", "pinyin": "zēngtiān", "pos": "v.", "en": "to add", "text": 1}, {"n": 18, "zh": "丰收", "pinyin": "fēngshōu", "pos": "v.", "en": "to have a bumper harvest", "text": 1}, {"n": 19, "zh": "发财", "pinyin": "fā cái", "pos": "v.", "en": "to make a fortune", "text": 1}, {"n": 20, "zh": "连年", "pinyin": "liánnián", "pos": "v.", "en": "in successive years, in consecutive years", "text": 1}, {"n": 21, "zh": "寓言", "pinyin": "yùyán", "pos": "n.", "en": "fable, allegory, parable", "text": 1}, {"n": 22, "zh": "信仰", "pinyin": "xìnyǎng", "pos": "n.", "en": "faith, belief", "text": 1}, {"n": 23, "zh": "喜闻乐见", "pinyin": "xǐwén-lèjiàn", "en": "to love to see and hear, to be delighted to hear and see", "text": 1}, {"n": 24, "zh": "神气", "pinyin": "shénqì", "pos": "adj.", "en": "impressive, vigorous", "text": 1}, {"n": 25, "zh": "翘", "pinyin": "qiào", "pos": "v.", "en": "to raise (one’s head, tail, etc.)", "text": 1}, {"n": 26, "zh": "神态", "pinyin": "shéntài", "pos": "n.", "en": "expression, manner, mien", "text": 1}, {"n": 27, "zh": "盛开", "pinyin": "shèngkāi", "pos": "v.", "en": "to be in full bloom", "text": 1}, {"n": 28, "zh": "散发", "pinyin": "sànfā", "pos": "v.", "en": "to send forth, to give off", "text": 1}, {"n": 29, "zh": "耸", "pinyin": "sǒng", "pos": "v.", "en": "to shrug", "text": 1}, {"n": 30, "zh": "州", "pinyin": "zhōu", "pos": "n.", "en": "prefecture", "text": 1}, {"n": 31, "zh": "外行", "pinyin": "wàiháng", "pos": "n.", "en": "layman, outsider", "text": 1}, {"n": 32, "zh": "推销", "pinyin": "tuīxiāo", "pos": "v.", "en": "to promote sales", "text": 1}, {"n": 33, "zh": "吞吞吐吐", "pinyin": "tūntūntǔtǔ", "en": "to mutter and mumble, to falter out a few words", "text": 1}, {"n": 34, "zh": "残次品", "pinyin": "cáncì pǐn", "en": "damaged or defective product", "text": 1}, {"n": 34, "zh": "次品", "pinyin": "cìpǐn", "pos": "n.", "en": "defective product", "text": 1}, {"n": 35, "zh": "现成", "pinyin": "xiànchéng", "pos": "adj.", "en": "ready-made", "text": 1}, {"n": 36, "zh": "谢绝", "pinyin": "xièjué", "pos": "v.", "en": "to refuse, to decline", "text": 1}, {"n": 37, "zh": "故乡", "pinyin": "gùxiāng", "pos": "n.", "en": "hometown", "text": 1}, {"n": 38, "zh": "扎实", "pinyin": "zhāshi", "pos": "adj.", "en": "solid, sound", "text": 1}, {"n": 39, "zh": "塑造", "pinyin": "sùzào", "pos": "v.", "en": "to portray", "text": 1}, {"n": 40, "zh": "手法", "pinyin": "shǒufǎ", "pos": "n.", "en": "skill, technique", "text": 1}, {"n": 41, "zh": "派别", "pinyin": "pàibié", "pos": "n.", "en": "faction, school", "text": 1}, {"n": 42, "zh": "借鉴", "pinyin": "jièjiàn", "pos": "v.", "en": "to use for reference, to draw lessons from", "text": 1}, {"n": 43, "zh": "再接再厉", "pinyin": "zàijiē-zàilì", "en": "to make persistent efforts", "text": 1}, {"n": 44, "zh": "心得", "pinyin": "xīndé", "pos": "n.", "en": "what one has learned from work, study, etc.", "text": 1}, {"n": 45, "zh": "缺席", "pinyin": "quē xí", "pos": "v.", "en": "to be absent (from a meeting, etc.)", "text": 1}, {"n": 46, "zh": "干劲", "pinyin": "gànjìn", "pos": "n.", "en": "passion, energy", "text": 1}, {"n": 47, "zh": "占据", "pinyin": "zhànjù", "pos": "v.", "en": "to occupy, to take over", "text": 1}, {"n": 48, "zh": "确立", "pinyin": "quèlì", "pos": "v.", "en": "to establish", "text": 1}, {"n": 49, "zh": "信念", "pinyin": "xìnniàn", "pos": "n.", "en": "faith, belief", "text": 1}, {"n": 50, "zh": "任重道远", "pinyin": "rènzhòng-dàoyuǎn", "en": "it is an arduous task and the road is long; to take a heavy burden and embark on a long road", "text": 1}, {"n": 51, "zh": "一帆风顺", "pinyin": "yìfān-fēngshùn", "en": "everything is going smoothly; to go off smoothly, to have a favorable wind all the way", "text": 1}]}], "grammar": [{"n": 1, "title_zh": "终究", "explanation_zh": "“终究”，副词。\n■ 表示强调事物的本质特点不会改变，事实不可否认。有加强语气的作用，多用于评价意义的陈述句。\n■ 常用在助动词之前，表示预料或期望的结果必然会出现；无论怎样，一定会这样。", "examples": [{"n": 1, "zh": "单色印品终究不能满足人们的审美需求，之后就有了彩色套印技术。", "note_zh": "用法1 例（1）；课文句"}, {"n": 2, "zh": "猫终究是动物，动物急了咬人也是正常的。", "note_zh": "用法1 例（2）"}, {"n": 3, "zh": "胜利总是在真理一边，正义的事业终究会取得胜利。", "note_zh": "用法2 例（1）"}, {"n": 4, "zh": "一个企业的成功是整个团队努力的结果。这个团队当然缺不了管理、技术人才，但同样也缺不了普通一线工人。有再好的管理和技术，产品终究要靠这些普通工人去生产。", "note_zh": "用法2 例（2）"}], "practice_instruction_zh": "练一练：用“终究”改写句子", "practice": [{"n": 1, "zh": "如果一个人一直不愿意变老，那他就永远不会幸福，因为他最后是一定会变老的。\n________", "answer": "如果一个人一直不愿意变老，那他就永远不会幸福，因为他终究会变老的。", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 2, "zh": "借住在朋友这儿当然不是长久之计，还是应该尽快租个房子。\n________", "answer": "借住在朋友这儿终究不是长久之计，还是应该尽快租个房子。", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 3, "zh": "失败毕竟不是好事，但只要从失败中吸取经验教训，坏事也可以变成好事。\n________", "answer": "失败终究不是好事，但只要从失败中吸取经验教训，坏事也可以变成好事。", "answer_ref": {"book": "textbook_answers", "pages": [28]}}]}, {"n": 2, "title_zh": "愈……愈……", "explanation_zh": "“愈……愈……”跟“越……越……”相同。用于书面。", "examples": [{"n": 1, "zh": "愈是经营年画久了，他对年画就愈是热爱。", "note_zh": "课文句"}, {"n": 2, "zh": "机遇的特点之一是转瞬即逝，市场竞争愈激烈愈是如此。"}, {"n": 3, "zh": "一般说来，一个人受的教育愈多、愈好，占有的人类精神文化的财富也就愈多，创造、发展文化的能力也就愈强。而一个民族，教育愈普及，教育的质量愈高，文化发展的速度就愈快，文化水准也就愈高。这也是因为，教育是文化系统中的一个能动要素，是文化发展循环加速机制中的一个内在环节的缘故。"}], "practice_instruction_zh": "练一练：请把下列6个小句组合成3个连贯的语段", "practice": [{"n": 1, "zh": "（1）________", "options": {"A": "一个家庭，愈重视教育，教育的投入愈多", "B": "市场经济是法制经济，愈是发达的市场经济", "C": "经营活动愈是会受到完备的法规约束，从而，在法制的框架内展开充分的公平竞争", "D": "他生就一副挑战式性格，愈是面对成功", "E": "家庭成员的文化水平就愈高，综合素质也就愈高", "F": "愈要为自己设定更高的目标"}, "answer": "A E", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 2, "zh": "（2）________", "options": {"A": "一个家庭，愈重视教育，教育的投入愈多", "B": "市场经济是法制经济，愈是发达的市场经济", "C": "经营活动愈是会受到完备的法规约束，从而，在法制的框架内展开充分的公平竞争", "D": "他生就一副挑战式性格，愈是面对成功", "E": "家庭成员的文化水平就愈高，综合素质也就愈高", "F": "愈要为自己设定更高的目标"}, "answer": "B C", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 3, "zh": "（3）________", "options": {"A": "一个家庭，愈重视教育，教育的投入愈多", "B": "市场经济是法制经济，愈是发达的市场经济", "C": "经营活动愈是会受到完备的法规约束，从而，在法制的框架内展开充分的公平竞争", "D": "他生就一副挑战式性格，愈是面对成功", "E": "家庭成员的文化水平就愈高，综合素质也就愈高", "F": "愈要为自己设定更高的目标"}, "answer": "D F", "answer_ref": {"book": "textbook_answers", "pages": [28]}}]}, {"n": 3, "title_zh": "连年——连续", "title_en": "（二）词语辨析", "explanation_zh": "（二）词语辨析 连年——连续\n共同点：都有“接连不断”的意思。如：他们连年/连续创造了高产纪录。\n不同点：\n连年——1. 接连许多年，只能用于表示“年”的时间，没有其他意思。如：连年大丰收\n连续——1. 一个接一个，可以表示任何时间段内的连续。如：①连续下了三天雨。②他们连续工作了15个小时。\n连年——2.“连年”后面不带数量词语。\n连续——2.“连续”后面可带数量词语。如：他已经连续三天没吃东西了。", "structure_rows": [" | 连年 | 连续", "共同点 | 都有“接连不断”的意思。（两栏合并）", "共同点 | 如：他们连年/连续创造了高产纪录。（两栏合并）", "不同点 | 1. 接连许多年，只能用于表示“年”的时间，没有其他意思。 | 1. 一个接一个，可以表示任何时间段内的连续。", "不同点 | 如：连年大丰收 | 如：①连续下了三天雨。②他们连续工作了15个小时。", "不同点 | 2.“连年”后面不带数量词语。 | 2.“连续”后面可带数量词语。", "不同点 | （与上格合并：“连年”后面不带数量词语。） | 如：他已经连续三天没吃东西了。"], "examples": [{"n": 1, "zh": "他们连年/连续创造了高产纪录。", "note_zh": "共同点"}, {"n": 2, "zh": "连年大丰收", "note_zh": "连年 不同点1"}, {"n": 3, "zh": "连续下了三天雨。", "note_zh": "连续 不同点1 ①"}, {"n": 4, "zh": "他们连续工作了15个小时。", "note_zh": "连续 不同点1 ②"}, {"n": 5, "zh": "他已经连续三天没吃东西了。", "note_zh": "连续 不同点2"}], "practice_instruction_zh": "做一做：选择“连年”或“连续”填空", "practice": [{"n": 1, "zh": "用同样的方法________念下去，直到不看卡片，念十遍不出错为止。", "answer": "连续", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 2, "zh": "人民生活在社会动荡和________战乱中，苦不堪言。", "answer": "连年", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 3, "zh": "屏幕上会________出现几个数字，你要迅速记住它们。", "answer": "连续", "answer_ref": {"book": "textbook_answers", "pages": [28]}}, {"n": 4, "zh": "最近几年来，由于管理混乱、经营不善，导致________亏损。", "answer": "连年", "answer_ref": {"book": "textbook_answers", "pages": [28]}}]}, {"n": 4, "title_zh": "篇章（6）重复关键词，推进主题", "title_en": "（三）篇章修辞", "explanation_zh": "（三）篇章修辞 篇章（6）重复关键词，推进主题\n重复关键词在语篇中起着十分重要的作用，从交际角度讲，重复关键词可以突出某一或某些信息；从篇章结构角度讲，不断重复出现最关键的词语，可使主题不断推进，它是促使篇章连贯，语句流畅的手段之一。", "examples": [{"n": 1, "zh": "有了纸，书写就需要墨水儿，于是有人发明了墨；字画、书信上需要盖章，于是印章开始流行；碑刻、拓印技术被广泛运用，于是有人联想到：这些技术结合起来，不就能印出书来吗！", "note_zh": "课文句"}, {"n": 2, "zh": "我开始每天至少写两千字。没有为“一定要换成稿费”而写，没有读者也写，自己寻找题目，把写作当成生活的一部分。有时，写不出自己想写的东西来，那就写一些无聊的消息稿或整理访问稿，我甚至还愿意接翻译稿，只求有字可写。"}, {"n": 3, "zh": "佩珊！佩珊！我心里难过极了！想到一个人会死，而且会突然地就死，我真是难过极了！我不肯死！我一定不能死！可是我们总有一天要死。"}], "practice_instruction_zh": "练一练：根据文意，填上合适的词语", "practice": [{"n": 1, "zh": "小张的花店跟别人不一样的地方是免费送花，只要是有这种需求的，路近的送，路远的________；大花篮、大花束送，一支两支________；晴天送，雨天________；即使人手不够，小李亲自骑自行车________。", "answer": "送", "answer_ref": {"book": "textbook_answers", "pages": [29]}}]}], "exercises": [{"n": 1, "type_zh": "模仿例子写词语", "instruction_zh": "模仿例子，写出更多的词语", "instruction_en": "Exercises", "items": [{"n": "例", "zh": "文献：文章　文学　文人　作文", "hint_zh": "（文）"}, {"n": 1, "zh": "增添：________", "hint_zh": "（增）", "answer": "增加、增多、增减、增益", "answer_ref": {"book": "textbook_answers", "pages": [29]}}, {"n": 2, "zh": "发财：________", "hint_zh": "（财）", "answer": "财富、财产、财务、财经", "answer_ref": {"book": "textbook_answers", "pages": [29]}}, {"n": 3, "zh": "外行：________", "hint_zh": "（行）", "answer": "行业、行情、行规、行道", "answer_ref": {"book": "textbook_answers", "pages": [29]}}, {"n": 4, "zh": "故乡：________", "hint_zh": "（乡）", "answer": "家乡、乡愁、乡里、乡土", "answer_ref": {"book": "textbook_answers", "pages": [29]}}]}, {"n": 2, "type_zh": "改写句子", "instruction_zh": "用所给词语或结构改写句子", "items": [{"n": 1, "zh": "孩子们很想了解生命是怎么开始的。\n________。", "hint_zh": "（起源）", "answer": "孩子们很想了解生命的起源。", "answer_ref": {"book": "textbook_answers", "pages": [29]}}, {"n": 2, "zh": "看到此情此景，我的脑海里浮现出许多往事。\n________。", "hint_zh": "（联想）", "answer": "看到此情此景，我的脑海里联想起许多往事。", "answer_ref": {"book": "textbook_answers", "pages": [29]}}, {"n": 3, "zh": "一个人的力量毕竟是有限的，还是团结力量大。\n________。", "hint_zh": "（终究）", "answer": "一个人的力量终究是有限的，还是团结力量大。", "answer_ref": {"book": "textbook_answers", "pages": [29]}}, {"n": 4, "zh": "随着孩子的陆续出生，家里增加了不少人口。\n________。", "hint_zh": "（增添）", "answer": "随着孩子的陆续出生，家里增添了不少口人。", "answer_ref": {"book": "textbook_answers", "pages": [29]}}, {"n": 5, "zh": "由于此地涉及国家机密，所以是不允许参观的。\n________。", "hint_zh": "（谢绝）", "answer": "由于此地涉及国家机密，所以谢绝参观。", "answer_ref": {"book": "textbook_answers", "pages": [29]}}, {"n": 6, "zh": "老师曾教导我们：“情况越紧急，越需要沉着冷静。”\n________。", "hint_zh": "（愈……愈……）", "answer": "老师曾教导我们：“情况愈紧急，愈需要沉着冷静。”", "answer_ref": {"book": "textbook_answers", "pages": [29]}}]}, {"n": 3, "type_zh": "选词填空", "instruction_zh": "选择合适的词语填空", "word_bank": [["神态", "手法", "涂抹", "心得", "盛开"], ["确立", "一帆风顺", "借鉴", "信念", "扎实"]], "items": [{"n": 1, "zh": "儿子从小就爱画画儿，从开始的随便________，到现在能画出________逼真的动物，________的花朵……绘画________越来越娴熟。一路走来，经历了许多艰辛，也收获了许多幸福，他愿意与大家一起分享画画儿的________。", "hint_zh": "（神态、手法、涂抹、心得、盛开）", "answer": "涂抹、神态、盛开、手法、心得", "answer_ref": {"book": "textbook_answers", "pages": [29]}}, {"n": 2, "zh": "想要成就一番事业，无论选择哪条路，都不会________的。首先要________自己的目标，给自己打下________的基础，多________别人成功的经验，抱着必胜的________坚持下去，最后的胜利一定属于你。", "hint_zh": "（确立、一帆风顺、借鉴、信念、扎实）", "answer": "一帆风顺、确立、扎实、借鉴、信念", "answer_ref": {"book": "textbook_answers", "pages": [29]}}]}, {"n": 4, "type_zh": "找出重复的关键词", "instruction_zh": "请找出下列语段中重复的关键词", "items": [{"n": 1, "zh": "这泪水，是激动的泪水，兴奋的泪水，喜悦的泪水，收获的泪水。\n________。", "answer": "泪水", "answer_ref": {"book": "textbook_answers", "pages": [30]}}, {"n": 2, "zh": "他是代表全民族的大多数，最正确、最勇敢、最坚决、最忠实、最热忱的空前的民族英雄。\n________。", "answer": "民族", "answer_ref": {"book": "textbook_answers", "pages": [30]}}, {"n": 3, "zh": "一根火柴，它自己熄灭了，却把别人点燃起来，点起了比自己大十倍、百倍、千倍以至数万倍的熊熊大火。\n________。", "answer": "点燃", "answer_ref": {"book": "textbook_answers", "pages": [30]}}, {"n": 4, "zh": "他用心观察着，眼前飞过的一只雁，一只麻雀，一只蝴蝶，一只蜻蜓，他都不放过。\n________。", "answer": "一只", "answer_ref": {"book": "textbook_answers", "pages": [30]}}]}, {"n": 5, "type_zh": "简述课文", "instruction_zh": "根据提示，简述课文主要内容（表格：项目 | 提示）", "items": [{"n": 1, "zh": "年画的起源", "hint_zh": "门神画；兄弟二人；唐宋，门神画内容拓展；清朝，使用“年画”一词"}, {"n": 2, "zh": "木版年画——雕版的发明", "hint_zh": "墨→印章→碑刻、拓印→扩大印章→在版上刷印"}, {"n": 3, "zh": "木版年画——彩色套印", "hint_zh": ""}, {"n": 4, "zh": "木版年画——年画走进百姓生活", "hint_zh": "过年贴年画，年画印制场所，年画内容，年画成了……的载体与工具"}, {"n": 5, "zh": "年画传人张光宁——初次认识", "hint_zh": "春节庙会，布老虎，推销"}, {"n": 6, "zh": "年画传人张光宁——第二印象", "hint_zh": "不像商人，讨论……"}, {"n": 7, "zh": "年画传人张光宁——相识久了", "hint_zh": "出生，长大，从小……，后来……，再接再厉……，不仅如此，……"}, {"n": 8, "zh": "年画传人张光宁——目标和信念", "hint_zh": "传播……，拓展……"}]}, {"n": "扩展", "type_zh": "扩展 词汇：熟悉下列词语的语素义", "instruction_zh": "词汇：熟悉下列词语的语素义", "instruction_en": "Expansion", "items": [{"n": 1, "zh": "回收 | 回：还，返 | 收：收回（利用）"}, {"n": 2, "zh": "开采 | 开：开发 | 采：挖掘（矿物）"}, {"n": 3, "zh": "开除 | 开：使分离 | 除：去掉"}, {"n": 4, "zh": "划分 | 划：把整体分成几部分 | 分：分开"}, {"n": 5, "zh": "请示 | 请：请求 | 示：指示"}, {"n": 6, "zh": "施加 | 施：给予（压力、影响等） | 加：增添"}, {"n": 7, "zh": "玩弄 | 玩：耍弄，使用（不正当的手段方法） | 弄：戏耍"}, {"n": 8, "zh": "应酬 | 应：应付 | 酬：交际往来"}, {"n": 9, "zh": "瞻仰 | 瞻：往前或往上看 | 仰：尊敬仰慕"}, {"n": 10, "zh": "铸造 | 铸：把金属熔化后倒在模子里制成器物 | 造：制作"}, {"n": 11, "zh": "落成 | 落：得到某种结果 | 成：完成，成功"}, {"n": 12, "zh": "配套 | 配：把缺少的补上 | 套：同类的事物合成一组"}]}], "application": [{"title_zh": "写一写", "instruction_zh": "本课介绍了中国的木版年画以及年画传人张光宁。从年画的起源讲到了年画的发展历程，同时给我们描述了一个热爱年画艺术，为年画艺术追求不止，有着远大理想和信念的年画传人。在你们的国家，一定也有具有自己民族特色的绘画艺术和具有代表性的画家，请以“我们的……艺术”为题写一种绘画艺术形式及画家的故事，字数不少于400字。", "instruction_en": "Application"}], "culture": {"title_zh": "课文脚注", "body_zh": "① 唐宋：朝代名。唐：公元618年～公元907年。宋：公元960年～公元1279年。\n② 清朝：朝代名。公元1616年～公元1911年。\n① 明：朝代名。公元1368年～公元1644年。\n① 魏州：地名。在今河北省邯郸市魏县。其传统花布染织技艺至今仍然风格独具。"}}, "workbook": {"ref": {"book": "workbook", "pages": [129, 130, 131, 132, 133, 134, 135, 136]}, "sections": [{"n": "一、听力 第一部分", "type_zh": "听力 第一部分", "instruction_zh": "第1–5题：请选出与所听内容一致的一项。", "items": [{"n": 1, "zh": "", "options": {"A": "螳螂的身体细长", "B": "螳螂的头脑灵活", "C": "螳螂喜欢东张西望", "D": "螳螂骨子里很温柔"}, "transcript_zh": "从外表看，螳螂并不可怕。身躯修长，前胸纤长；长颈上，顶着一个扁三角形的小脑袋；它的颈部是柔软的，能使头向任何方向窥视。它的神态温柔，被人称作“会祈祷的螳螂”。", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [58]}}, {"n": 2, "zh": "", "options": {"A": "先生最为擅长编写历史故事", "B": "先生的文章有许多绝妙之处", "C": "先生文章中的人物都很神奇", "D": "先生读起文章来总是神情感人"}, "transcript_zh": "先生文章的妙处实在难以尽述，就如那文章里涉及的当时的许多人和事，如今读来，又都成了饶有趣味的历史小掌故。先生的文章，针砭时弊，泼辣犀利，绝无时文的吞吞吐吐，读来令人神旺气盛。", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [58]}}, {"n": 3, "zh": "", "options": {"A": "长安在黄河流域", "B": "再冷井水也不会结冰", "C": "黄河流域气候一直较温暖", "D": "公元七、八世纪天气冷到极点"}, "transcript_zh": "东汉末年，中华大地气候又表现出向寒冷转变的迹象，东海、东莱等郡出现水井冰冻厚尺余的现象，渤海湾也有冰封记载。公元七、八世纪，黄河流域气候一度转暖，长安地区的梅花花期又有变长的迹象。", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [58]}}, {"n": 4, "zh": "", "options": {"A": "女人个个都懂得爱护皮肤", "B": "女人从电影中学习美容方法", "C": "精油都是从水果中提炼出来的", "D": "精油出现前人们会用水果美容"}, "transcript_zh": "记得看过的一部电影，女主角将柠檬从中间切开，然后拿起半只直接涂抹颈部，这种利用水果的美容法应该算是精油疗法的雏形了。在提炼精油的高科技还未出现时，女人已经知道如何呵护自己的皮肤了，这让我当时为之一震。", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [59]}}, {"n": 5, "zh": "", "options": {"A": "语言中，基本词汇部分十分稳定", "B": "语言中的词汇只能反映基本概念", "C": "语言中构造新词的材料十分有限", "D": "语言中不断出现构成新词的格式"}, "transcript_zh": "语言中词汇的变化很灵敏，但其基础非常稳固。这表现在两方面：第一，词汇中的基本词汇部分反映交际中最常用的基本概念，它是很不容易变化的。第二，构造新词的材料几乎都是语言中古已有之的，构成新词的格式也是语言中现成的。", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [59]}}]}, {"n": "一、听力 第二部分", "type_zh": "听力 第二部分", "instruction_zh": "第6–10题：请选出正确答案。", "items": [{"n": 6, "zh": "", "options": {"A": "为苏州的水而骄傲", "B": "为苏州艺人多而骄傲", "C": "为苏州是人间天堂而骄傲", "D": "为苏州曾做过都城而骄傲"}, "transcript_zh": "女：请问，为什么要编写《口述“非遗”》这么一本书呢？\n男：大家都知道，每一个苏州人都为自己的城市骄傲。我们骄傲的基础有三点：第一是水，苏州因水而昌盛，水是苏州人的骄傲；第二是人，苏州出人才，古的不说了，当今院士就有130多位；第三就是艺，历史上，苏州有各种各样的工艺。去年联合国给予我们“手工艺与民间艺术之都”的称号，这是实至名归。而工艺，大部分属于非物质文化遗产，但是一些“非遗”项目的现状不容乐观，所以我们组织专家、学者，对非物质文化遗产的传承人、见证人进行采访，目的是留下历史的记录，同时希望有更多的人了解、关注、保护“非遗”。\n女：为什么要采用口述的方式呢？\n男：因为非物质文化遗产的传承人年龄都很大了，80岁以上的有15位，年龄最大的101岁。有两位老人在接受采访不久、成书之前就去世了。应该说，这份历史文献是对“非遗”抢救式的保护，我们心里充满了紧迫感。\n女：苏州“非遗”项目保护的具体办法是什么？\n男：我们采取了区别性的保护办法。对于生存状态好的，进行生产性保护，比如核雕、刺绣；不好的，那些渐行渐远的、濒危的项目，需要去关怀；还有的年代太过久远，由于历史原因已经抢救不活的，进行记忆性保护。\n女：为什么会造成“非遗”今天的困境，大家有过思考吗？\n男：所谓“遗”，就是前人留下来的，不是我们这个时代的东西。所谓“非遗”，是文化的东西，是古人曾经的生活方式。“非遗”建立的基础是农耕文化，可我们今天生活已经发生了巨大的变化。从中国发展的历程来看，我们几乎没有经历一个现代的工业时代，直接进入了信息时代。在社会跳跃式发展的过程中，必然会抛弃一些东西。抛弃什么呢？很显然，就是那些曾经的生活方式，这就形成了中国“非遗”今天所面对的困境。\n问：苏州人最可能会为什么而骄傲？", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [60]}}, {"n": 7, "zh": "", "options": {"A": "非物质文化遗产的文字记录丰富", "B": "非物质文化遗产的研究已很深入", "C": "越来越多的人在关注非物质文化遗产", "D": "中国非物质文化遗产保护的现状堪忧"}, "transcript_zh": "女：请问，为什么要编写《口述“非遗”》这么一本书呢？\n男：大家都知道，每一个苏州人都为自己的城市骄傲。我们骄傲的基础有三点：第一是水，苏州因水而昌盛，水是苏州人的骄傲；第二是人，苏州出人才，古的不说了，当今院士就有130多位；第三就是艺，历史上，苏州有各种各样的工艺。去年联合国给予我们“手工艺与民间艺术之都”的称号，这是实至名归。而工艺，大部分属于非物质文化遗产，但是一些“非遗”项目的现状不容乐观，所以我们组织专家、学者，对非物质文化遗产的传承人、见证人进行采访，目的是留下历史的记录，同时希望有更多的人了解、关注、保护“非遗”。\n女：为什么要采用口述的方式呢？\n男：因为非物质文化遗产的传承人年龄都很大了，80岁以上的有15位，年龄最大的101岁。有两位老人在接受采访不久、成书之前就去世了。应该说，这份历史文献是对“非遗”抢救式的保护，我们心里充满了紧迫感。\n女：苏州“非遗”项目保护的具体办法是什么？\n男：我们采取了区别性的保护办法。对于生存状态好的，进行生产性保护，比如核雕、刺绣；不好的，那些渐行渐远的、濒危的项目，需要去关怀；还有的年代太过久远，由于历史原因已经抢救不活的，进行记忆性保护。\n女：为什么会造成“非遗”今天的困境，大家有过思考吗？\n男：所谓“遗”，就是前人留下来的，不是我们这个时代的东西。所谓“非遗”，是文化的东西，是古人曾经的生活方式。“非遗”建立的基础是农耕文化，可我们今天生活已经发生了巨大的变化。从中国发展的历程来看，我们几乎没有经历一个现代的工业时代，直接进入了信息时代。在社会跳跃式发展的过程中，必然会抛弃一些东西。抛弃什么呢？很显然，就是那些曾经的生活方式，这就形成了中国“非遗”今天所面对的困境。\n问：关于非物质文化遗产，下列哪项正确？", "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [60]}}, {"n": 8, "zh": "", "options": {"A": "优先记忆性保护", "B": "首先保护年代久远的", "C": "尽力救活每一个项目", "D": "根据具体情况区别对待"}, "transcript_zh": "女：请问，为什么要编写《口述“非遗”》这么一本书呢？\n男：大家都知道，每一个苏州人都为自己的城市骄傲。我们骄傲的基础有三点：第一是水，苏州因水而昌盛，水是苏州人的骄傲；第二是人，苏州出人才，古的不说了，当今院士就有130多位；第三就是艺，历史上，苏州有各种各样的工艺。去年联合国给予我们“手工艺与民间艺术之都”的称号，这是实至名归。而工艺，大部分属于非物质文化遗产，但是一些“非遗”项目的现状不容乐观，所以我们组织专家、学者，对非物质文化遗产的传承人、见证人进行采访，目的是留下历史的记录，同时希望有更多的人了解、关注、保护“非遗”。\n女：为什么要采用口述的方式呢？\n男：因为非物质文化遗产的传承人年龄都很大了，80岁以上的有15位，年龄最大的101岁。有两位老人在接受采访不久、成书之前就去世了。应该说，这份历史文献是对“非遗”抢救式的保护，我们心里充满了紧迫感。\n女：苏州“非遗”项目保护的具体办法是什么？\n男：我们采取了区别性的保护办法。对于生存状态好的，进行生产性保护，比如核雕、刺绣；不好的，那些渐行渐远的、濒危的项目，需要去关怀；还有的年代太过久远，由于历史原因已经抢救不活的，进行记忆性保护。\n女：为什么会造成“非遗”今天的困境，大家有过思考吗？\n男：所谓“遗”，就是前人留下来的，不是我们这个时代的东西。所谓“非遗”，是文化的东西，是古人曾经的生活方式。“非遗”建立的基础是农耕文化，可我们今天生活已经发生了巨大的变化。从中国发展的历程来看，我们几乎没有经历一个现代的工业时代，直接进入了信息时代。在社会跳跃式发展的过程中，必然会抛弃一些东西。抛弃什么呢？很显然，就是那些曾经的生活方式，这就形成了中国“非遗”今天所面对的困境。\n问：对苏州“非遗”的保护措施是什么？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [60]}}, {"n": 9, "zh": "", "options": {"A": "它看不见摸不着", "B": "当下农民都在城里", "C": "我们的生活方式改变了", "D": "信息时代的吸引力太大"}, "transcript_zh": "女：请问，为什么要编写《口述“非遗”》这么一本书呢？\n男：大家都知道，每一个苏州人都为自己的城市骄傲。我们骄傲的基础有三点：第一是水，苏州因水而昌盛，水是苏州人的骄傲；第二是人，苏州出人才，古的不说了，当今院士就有130多位；第三就是艺，历史上，苏州有各种各样的工艺。去年联合国给予我们“手工艺与民间艺术之都”的称号，这是实至名归。而工艺，大部分属于非物质文化遗产，但是一些“非遗”项目的现状不容乐观，所以我们组织专家、学者，对非物质文化遗产的传承人、见证人进行采访，目的是留下历史的记录，同时希望有更多的人了解、关注、保护“非遗”。\n女：为什么要采用口述的方式呢？\n男：因为非物质文化遗产的传承人年龄都很大了，80岁以上的有15位，年龄最大的101岁。有两位老人在接受采访不久、成书之前就去世了。应该说，这份历史文献是对“非遗”抢救式的保护，我们心里充满了紧迫感。\n女：苏州“非遗”项目保护的具体办法是什么？\n男：我们采取了区别性的保护办法。对于生存状态好的，进行生产性保护，比如核雕、刺绣；不好的，那些渐行渐远的、濒危的项目，需要去关怀；还有的年代太过久远，由于历史原因已经抢救不活的，进行记忆性保护。\n女：为什么会造成“非遗”今天的困境，大家有过思考吗？\n男：所谓“遗”，就是前人留下来的，不是我们这个时代的东西。所谓“非遗”，是文化的东西，是古人曾经的生活方式。“非遗”建立的基础是农耕文化，可我们今天生活已经发生了巨大的变化。从中国发展的历程来看，我们几乎没有经历一个现代的工业时代，直接进入了信息时代。在社会跳跃式发展的过程中，必然会抛弃一些东西。抛弃什么呢？很显然，就是那些曾经的生活方式，这就形成了中国“非遗”今天所面对的困境。\n问：“非遗”今天困境产生的原因是什么？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [60]}}, {"n": 10, "zh": "", "options": {"A": "苏州的历史很悠久", "B": "苏州自古至今人才济济", "C": "“口述”的方式在今天很时髦", "D": "苏州非物质文化遗产保护迫在眉睫"}, "transcript_zh": "女：请问，为什么要编写《口述“非遗”》这么一本书呢？\n男：大家都知道，每一个苏州人都为自己的城市骄傲。我们骄傲的基础有三点：第一是水，苏州因水而昌盛，水是苏州人的骄傲；第二是人，苏州出人才，古的不说了，当今院士就有130多位；第三就是艺，历史上，苏州有各种各样的工艺。去年联合国给予我们“手工艺与民间艺术之都”的称号，这是实至名归。而工艺，大部分属于非物质文化遗产，但是一些“非遗”项目的现状不容乐观，所以我们组织专家、学者，对非物质文化遗产的传承人、见证人进行采访，目的是留下历史的记录，同时希望有更多的人了解、关注、保护“非遗”。\n女：为什么要采用口述的方式呢？\n男：因为非物质文化遗产的传承人年龄都很大了，80岁以上的有15位，年龄最大的101岁。有两位老人在接受采访不久、成书之前就去世了。应该说，这份历史文献是对“非遗”抢救式的保护，我们心里充满了紧迫感。\n女：苏州“非遗”项目保护的具体办法是什么？\n男：我们采取了区别性的保护办法。对于生存状态好的，进行生产性保护，比如核雕、刺绣；不好的，那些渐行渐远的、濒危的项目，需要去关怀；还有的年代太过久远，由于历史原因已经抢救不活的，进行记忆性保护。\n女：为什么会造成“非遗”今天的困境，大家有过思考吗？\n男：所谓“遗”，就是前人留下来的，不是我们这个时代的东西。所谓“非遗”，是文化的东西，是古人曾经的生活方式。“非遗”建立的基础是农耕文化，可我们今天生活已经发生了巨大的变化。从中国发展的历程来看，我们几乎没有经历一个现代的工业时代，直接进入了信息时代。在社会跳跃式发展的过程中，必然会抛弃一些东西。抛弃什么呢？很显然，就是那些曾经的生活方式，这就形成了中国“非遗”今天所面对的困境。\n问：这段话主要谈的是什么？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [60]}}]}, {"n": "一、听力 第三部分", "type_zh": "听力 第三部分", "instruction_zh": "第11–17题：请选出正确答案。", "items": [{"n": 11, "zh": "", "options": {"A": "让外行大吃一惊", "B": "将魔术与戏曲相结合", "C": "更生动地塑造人物形象", "D": "给演员一个炫耀的机会"}, "transcript_zh": "变脸，这是川剧表演艺术的特殊技巧之一，看过的观众，无不惊叹其神。它是揭示剧中人物内心思想感情的一种浪漫主义手法，把不可见、不可感的抽象的东西变得可见、可感。\n剧作家柳倩认为，“变脸”是感情的象征，许多脸谱已经有它显著的典型特质，说明人物的忠奸邪正，而且有助于强调人物个性，表现感情变化的发展过程，这是四川戏的优点。加之演员能于观众不注意间改变他的脸像，也是一种惊人的技术。\n如今，“变脸”的特技已被其他剧种所采用，而且，已经传到了国外。值得注意的是，为卖弄技艺、讨好观众而滥用变脸的现象也时有发生。\n问：川剧中“变脸”的目的是什么？", "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [61]}}, {"n": 12, "zh": "", "options": {"A": "看起来眼花缭乱", "B": "演员艺高人胆大", "C": "借鉴了京剧脸谱之长", "D": "有助于人物个性的表现"}, "transcript_zh": "变脸，这是川剧表演艺术的特殊技巧之一，看过的观众，无不惊叹其神。它是揭示剧中人物内心思想感情的一种浪漫主义手法，把不可见、不可感的抽象的东西变得可见、可感。\n剧作家柳倩认为，“变脸”是感情的象征，许多脸谱已经有它显著的典型特质，说明人物的忠奸邪正，而且有助于强调人物个性，表现感情变化的发展过程，这是四川戏的优点。加之演员能于观众不注意间改变他的脸像，也是一种惊人的技术。\n如今，“变脸”的特技已被其他剧种所采用，而且，已经传到了国外。值得注意的是，为卖弄技艺、讨好观众而滥用变脸的现象也时有发生。\n问：剧作家柳倩怎样评价“变脸”？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [61]}}, {"n": 13, "zh": "", "options": {"A": "有使用太泛的倾向", "B": "只有川剧掌握了变脸技艺", "C": "变脸技艺在海外并不受欢迎", "D": "有在世界范围内普及的态势"}, "transcript_zh": "变脸，这是川剧表演艺术的特殊技巧之一，看过的观众，无不惊叹其神。它是揭示剧中人物内心思想感情的一种浪漫主义手法，把不可见、不可感的抽象的东西变得可见、可感。\n剧作家柳倩认为，“变脸”是感情的象征，许多脸谱已经有它显著的典型特质，说明人物的忠奸邪正，而且有助于强调人物个性，表现感情变化的发展过程，这是四川戏的优点。加之演员能于观众不注意间改变他的脸像，也是一种惊人的技术。\n如今，“变脸”的特技已被其他剧种所采用，而且，已经传到了国外。值得注意的是，为卖弄技艺、讨好观众而滥用变脸的现象也时有发生。\n问：关于“变脸”的表演现状，下列哪项正确？", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [61]}}, {"n": 14, "zh": "", "options": {"A": "苹果象征恋爱", "B": "苹果象征有毒的东西", "C": "表示对图灵遭遇的同情", "D": "为了纪念“计算机科学之父”"}, "transcript_zh": "对于苹果的商标最初是怎样来的，有很多谣言。其中最盛行的说法是，那被咬掉一口的彩色苹果，是已故伟人阿兰·图灵的杰作。图灵因同性恋遭到排斥后自杀了，可能是食用了带有氰化物的苹果。相信这一说法的人认为苹果公司选择苹果商标是为了纪念“计算机科学之父”。\n其实，这仅仅是一个听起来意义深远的故事，事实上，全是瞎扯。对公司而言，取名叫“苹果”，仅仅是因为斯蒂夫·乔布斯认为这个词听起来不错。乔布斯想出这个名字时，没有任何象征或者暗示牛顿或图灵的意思，如果要问为什么在浩如烟海的词汇中，他偏偏选中了“苹果”，那是因为当时他正处于水果减肥计划当中，觉得这个词听起来“有趣”。而就商标本身而言，商标的设计者罗伯·吉道夫已经多次澄清不是许多人以为的那样，不是为了向图灵或者牛顿或者“水果学问”致敬而设计的。它只是一个苹果。至于为什么被咬了一口，只是为了不让人们把它当成樱桃而已。\n问：关于苹果商标最盛行的说法，下列哪项正确？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [62]}}, {"n": 15, "zh": "", "options": {"A": "乔布斯喜欢", "B": "吃苹果可减肥", "C": "觉得画面有意思", "D": "暗示牛顿的发现"}, "transcript_zh": "对于苹果的商标最初是怎样来的，有很多谣言。其中最盛行的说法是，那被咬掉一口的彩色苹果，是已故伟人阿兰·图灵的杰作。图灵因同性恋遭到排斥后自杀了，可能是食用了带有氰化物的苹果。相信这一说法的人认为苹果公司选择苹果商标是为了纪念“计算机科学之父”。\n其实，这仅仅是一个听起来意义深远的故事，事实上，全是瞎扯。对公司而言，取名叫“苹果”，仅仅是因为斯蒂夫·乔布斯认为这个词听起来不错。乔布斯想出这个名字时，没有任何象征或者暗示牛顿或图灵的意思，如果要问为什么在浩如烟海的词汇中，他偏偏选中了“苹果”，那是因为当时他正处于水果减肥计划当中，觉得这个词听起来“有趣”。而就商标本身而言，商标的设计者罗伯·吉道夫已经多次澄清不是许多人以为的那样，不是为了向图灵或者牛顿或者“水果学问”致敬而设计的。它只是一个苹果。至于为什么被咬了一口，只是为了不让人们把它当成樱桃而已。\n问：事实上，商标确定的理由是什么？", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [62]}}, {"n": 16, "zh": "", "options": {"A": "它仅仅是一个苹果", "B": "它还像一颗大樱桃", "C": "它包含很深的学问", "D": "各种说法都有道理"}, "transcript_zh": "对于苹果的商标最初是怎样来的，有很多谣言。其中最盛行的说法是，那被咬掉一口的彩色苹果，是已故伟人阿兰·图灵的杰作。图灵因同性恋遭到排斥后自杀了，可能是食用了带有氰化物的苹果。相信这一说法的人认为苹果公司选择苹果商标是为了纪念“计算机科学之父”。\n其实，这仅仅是一个听起来意义深远的故事，事实上，全是瞎扯。对公司而言，取名叫“苹果”，仅仅是因为斯蒂夫·乔布斯认为这个词听起来不错。乔布斯想出这个名字时，没有任何象征或者暗示牛顿或图灵的意思，如果要问为什么在浩如烟海的词汇中，他偏偏选中了“苹果”，那是因为当时他正处于水果减肥计划当中，觉得这个词听起来“有趣”。而就商标本身而言，商标的设计者罗伯·吉道夫已经多次澄清不是许多人以为的那样，不是为了向图灵或者牛顿或者“水果学问”致敬而设计的。它只是一个苹果。至于为什么被咬了一口，只是为了不让人们把它当成樱桃而已。\n问：关于商标本身，设计者的说法是什么？", "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [62]}}, {"n": 17, "zh": "", "options": {"A": "图灵彩色苹果画得不错", "B": "世人对科学家都心存敬意", "C": "人们看见苹果就会想到减肥", "D": "苹果商标最盛行的说法无事实根据"}, "transcript_zh": "对于苹果的商标最初是怎样来的，有很多谣言。其中最盛行的说法是，那被咬掉一口的彩色苹果，是已故伟人阿兰·图灵的杰作。图灵因同性恋遭到排斥后自杀了，可能是食用了带有氰化物的苹果。相信这一说法的人认为苹果公司选择苹果商标是为了纪念“计算机科学之父”。\n其实，这仅仅是一个听起来意义深远的故事，事实上，全是瞎扯。对公司而言，取名叫“苹果”，仅仅是因为斯蒂夫·乔布斯认为这个词听起来不错。乔布斯想出这个名字时，没有任何象征或者暗示牛顿或图灵的意思，如果要问为什么在浩如烟海的词汇中，他偏偏选中了“苹果”，那是因为当时他正处于水果减肥计划当中，觉得这个词听起来“有趣”。而就商标本身而言，商标的设计者罗伯·吉道夫已经多次澄清不是许多人以为的那样，不是为了向图灵或者牛顿或者“水果学问”致敬而设计的。它只是一个苹果。至于为什么被咬了一口，只是为了不让人们把它当成樱桃而已。\n问：根据这段话，可以知道什么？", "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [62]}}]}, {"n": "二、阅读 第一部分", "type_zh": "阅读 第一部分", "instruction_zh": "第18–20题：请选出有语病的一项。", "items": [{"n": 18, "zh": "", "options": {"A": "他们是故意捣乱，因为对教师的讲课不感兴趣。", "B": "《引力理论与引力坍缩》被认为是宇宙论研究中里程碑式的著作。", "C": "只要你来，只要你不耍脾气，只要你什么都听我的，其他的咱们都好商量。", "D": "会计以红字表示负数，因此，除上述情况外，不得用红色墨水儿登记账簿。"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 19, "zh": "", "options": {"A": "让咱们团结起来，再接再厉，去争取更大的胜利吧！", "B": "回顾过去，我们豪情满怀；展望未来，我们任重道远。", "C": "人们对居住的追求，不仅是室内的舒适度，而是更关注室外的环境。", "D": "有人向他进言——为保持酒店的档次，应该谢绝那些衣着随便的人入内。"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 20, "zh": "", "options": {"A": "70岁后，他便在自家的屋前摆了个小摊，卖些酒饼和日常生活用品等，生活清心寡欲、无忧无虑。", "B": "反观专制官僚统治形态，那些专制君主与官僚们的社会性格或其阶级关系，仿佛愈研究就愈不可捉摸。", "C": "那个昏睡了一个年的植物人，在妈妈和爸爸的悉心照料下，在医生和护士的精心治疗下，竟然奇迹般地醒过来了。", "D": "森林素有“绿色金子”之称，它可以把二氧化碳转换成氧气；它可以像抽水机一样把地下的水分散发到天空中；因此我们应该多多种树，保护环境。"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第二部分", "type_zh": "阅读 第二部分", "instruction_zh": "第21–23题：选词填空。", "items": [{"n": 21, "zh": "克雷洛夫的寓言________地反映了俄国18世纪末和19世纪初的民主主义进步思想。它不仅描写了当时的现实生活，而且对俄国统治阶级的蛮横专制、官吏的腐败无能、人民的________以及俄罗斯人民最大的灾害——农奴制度，都给以________地讽刺。", "options": {"A": "恰当　苦恼　莫大", "B": "直观　痛楚　浓厚", "C": "深刻　疾苦　辛辣", "D": "科学　烦恼　严酷"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 22, "zh": "调查报告要以大量的调查材料为基础，通过客观事物的真实________来表达作者的主要________，以引起比较广泛的社会________。实事求是的客观性，较为鲜明的思想性，________问题的普遍性，是调查报告的主要特色。", "options": {"A": "确切　任务　支持　把握", "B": "面目　倾向　影响　揭示", "C": "记录　寄托　震荡　联想", "D": "题材　心得　信念　确立"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 23, "zh": "泡沫经济指经济运行________像泡沫一样，繁荣的表面________难逃破灭的________。泡沫经济往往伴随着商品价格的大起大落，但泡沫经济不是一般意义上的商品价格涨落，而是专指由过度投机而导致的商品价格________偏离商品价值、先暴涨后骤跌的现象。", "options": {"A": "状态　终究　结局　严重", "B": "过程　未必　恶果　逐步", "C": "周期　迟早　后果　明显", "D": "态势　反正　下场　连年"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第三部分", "type_zh": "阅读 第三部分", "instruction_zh": "第24–28题：选句填空。\n（24）________：“非物质文化遗产”指被各社区、群体，有时是个人，视为其文化遗产组成部分的各种社会实践、观念表述、表现形式、知识、技能以及相关的工具、实物、手工艺品和文化场所。这种非物质文化遗产世代相传，在各社区和群体适用周围环境以及与自然和历史的互动中，被不断地再创造，（25）________，从而增强对文化多样性和人类创造力的尊重。\n（26）________：“非物质文化遗产”是指各族人民世代相传并视为其文化遗产组成部分的各种传统文化表现形式，（27）________。包括：（一）传统口头文学以及作为其载体的语言；（二）传统美术、书法、音乐、舞蹈、戏剧、曲艺和杂技；（三）传统技艺、医药和历法；（四）传统礼仪、节庆等民俗；（五）传统体育和游艺；（六）其他非物质文化遗产。属于非物质文化遗产组成部分的实物和场所，（28）________，适用《中华人民共和国文物保护法》的有关规定。", "items": [{"n": 24, "zh": "（24）________：“非物质文化遗产”指被各社区、群体，有时是个人，视为其文化遗产组成部分的各种社会实践、观念表述、表现形式、知识、技能以及相关的工具、实物、手工艺品和文化场所。", "options": {"A": "根据联合国《保护非物质文化遗产公约》", "B": "根据《中华人民共和国非物质文化遗产法》规定", "C": "凡属文物的", "D": "为这些社区和群体提供认同感和持续感", "E": "以及与传统文化表现形式相关的实物和场所"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 25, "zh": "这种非物质文化遗产世代相传，在各社区和群体适用周围环境以及与自然和历史的互动中，被不断地再创造，（25）________，从而增强对文化多样性和人类创造力的尊重。", "options": {"A": "根据联合国《保护非物质文化遗产公约》", "B": "根据《中华人民共和国非物质文化遗产法》规定", "C": "凡属文物的", "D": "为这些社区和群体提供认同感和持续感", "E": "以及与传统文化表现形式相关的实物和场所"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 26, "zh": "（26）________：“非物质文化遗产”是指各族人民世代相传并视为其文化遗产组成部分的各种传统文化表现形式，（27）________。", "options": {"A": "根据联合国《保护非物质文化遗产公约》", "B": "根据《中华人民共和国非物质文化遗产法》规定", "C": "凡属文物的", "D": "为这些社区和群体提供认同感和持续感", "E": "以及与传统文化表现形式相关的实物和场所"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 27, "zh": "“非物质文化遗产”是指各族人民世代相传并视为其文化遗产组成部分的各种传统文化表现形式，（27）________。", "options": {"A": "根据联合国《保护非物质文化遗产公约》", "B": "根据《中华人民共和国非物质文化遗产法》规定", "C": "凡属文物的", "D": "为这些社区和群体提供认同感和持续感", "E": "以及与传统文化表现形式相关的实物和场所"}, "answer": "E", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 28, "zh": "属于非物质文化遗产组成部分的实物和场所，（28）________，适用《中华人民共和国文物保护法》的有关规定。", "options": {"A": "根据联合国《保护非物质文化遗产公约》", "B": "根据《中华人民共和国非物质文化遗产法》规定", "C": "凡属文物的", "D": "为这些社区和群体提供认同感和持续感", "E": "以及与传统文化表现形式相关的实物和场所"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第四部分（29–32）", "type_zh": "阅读 第四部分", "instruction_zh": "第29–36题：请选出正确答案。\n29–32.\n宋瓷追求器型简洁，色彩纯净，不张扬、做作，于纯净之中传递美感。“汝、官、哥、定、钧”五大名窑名扬天下，千百年来受文人士大夫的喜爱，为后世推崇。\n汝瓷传世只区区几十件，见一面都很难；官窑器在市场上偶尔还得一见；哥窑器也是如此；钧窑器虽然常见，但现在学术界对钧窑的烧制年代存有争议；所以目前尚能从容细挑的，唯有定窑器。\n我一直想收藏定窑瓷器，喜欢它素洁莹润，白中泛着象牙黄的自然之美，另外还有一点，我个人喜欢素饰的光素器，对花哨的东西不感兴趣，偏偏定窑还以刻工精美闻名。我只能挑挑拣拣，等待机会。\n直到等得我都觉得无望了，机会终于来了，一对日本夫妇要拍卖他们的私人收藏。二人均为医生，年轻之时，勤于医事。二十多年前，开始收藏，持之至今。拍品中的“北宋定窑双鱼纹碗”，细工精刻，起刀流畅，自然灵动，简洁而不失妩媚。釉色偏白略泛牙黄，内外壁光洁。对这样的拍品，我能错过吗！", "items": [{"n": 29, "zh": "宋代瓷器：", "options": {"A": "全部出自五大名窑", "B": "向来为医生所喜爱", "C": "器型简单粗陋，不自然", "D": "体现了文人的审美情趣"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 30, "zh": "“汝、官、哥、定、钧”五大名窑中：", "options": {"A": "汝瓷流传受地区限制", "B": "钧窑器都是新近烧制的", "C": "官窑器、哥窑器数量很少", "D": "定窑器次品多，需认真挑选"}, "answer": "C", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 31, "zh": "“我”想收藏的定窑瓷器，应该是：", "options": {"A": "釉色洁白", "B": "花哨一些", "C": "没有雕刻", "D": "简洁自然"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 32, "zh": "根据最后一段，可以知道：", "options": {"A": "医生又舍不得卖了", "B": "拍品上雕刻有鱼纹", "C": "藏家希望买家是医生", "D": "“我”最终与此次拍品无缘"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}, {"n": "二、阅读 第四部分（33–36）", "type_zh": "阅读 第四部分", "instruction_zh": "33–36.\n唐卡是一种以宗教内容为主的卷轴画，既是赏心悦目的艺术品，又是修行者膜拜的对象，悬挂于家庭佛堂和寺院、庙宇的墙壁或柱梁上，它是匠人的劳动成果，也是艺术家的心灵表达，更是宗教信徒们的修行依托。\n格桑次旦12岁便参加了大昭寺修复工作。瘦小的格桑很勤快，师傅们口渴了，就支使他去买甜茶，累了，就让他来捶捶背。格桑学得很认真，他先跟着老师傅学配色。会配色了，就开始学画画。老师傅给他选了个吉祥的日子，他拿着支毛笔，在一面壁画墙上勾了条线，仪式就完了，这意味着，格桑从那天起就可以画画了。别人午休，格桑从来不休息，干起活来更是干劲十足。大昭寺修复工程完工，格桑配色、装饰画都可以了，虽然没有专门去学画唐卡，但跟着看了三年多，对于制作唐卡的程序也了解得差不多了。\n没有了修复寺庙的活，格桑进了建筑队，先当油漆工，又学木工，20岁时他已经打得一手好家具。藏式家具装饰画非常重要，格桑又能做木工，又会画画，一下子变得很吃香。\n可是格桑还是希望能画唐卡，倒不是想发财，而是因为“画唐卡”在他心目中占据的位置是不可替代的。终于，他有幸做了藏族绘画大师丹巴绕旦的徒弟，并成了画唐卡的高手。再后来，他跟着丹巴老师进了西藏大学艺术系，登上了大学的讲台。如今，格桑有一个自己的工作室，很多人来订制唐卡，一年到头画不完。但格桑最上心的还是教书，他常说“我学画唐卡从来没觉得难，可教的时候觉得很难，我给学生上课非常累，因为有的孩子不用心，总是没有进步，有的时候看着他们的画我就会生气。”", "items": [{"n": 33, "zh": "唐卡是：", "options": {"A": "宗教画", "B": "山水画", "C": "人物画", "D": "静物画"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 34, "zh": "格桑在大昭寺修复工作中：", "options": {"A": "懂得了做事要勤快", "B": "帮别人选吉祥日子", "C": "边工作边跟老师学习", "D": "学会了配色、画装饰画"}, "answer": "D", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 35, "zh": "大昭寺修复工程完工以后，格桑：", "options": {"A": "进了装修队", "B": "学会了木工", "C": "开了个家具店", "D": "吃什么都不香"}, "answer": "B", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}, {"n": 36, "zh": "在格桑心中，觉得最难的是：", "options": {"A": "教学工作", "B": "跟老师学艺", "C": "工作室的活儿", "D": "如期完成唐卡订单"}, "answer": "A", "answer_ref": {"book": "workbook_answers", "pages": [94, 95, 96, 97, 98, 99, 100]}}]}], "answers_ref": {"book": "workbook_answers", "pages": [58, 59, 60, 61, 62, 94, 95, 96, 97, 98, 99, 100]}}, "unclear": ["HSK6-д багшийн ном байхгүй тул teacher талбар орхисон. Сурах бичгийн 练一练/做一做/练习 хариулт BLCUP 课本参考答案 (HSK6 下Answer Textbook.pdf х.28–30)-аас; дасгалын номын 听力 1–17 хариулт, сонсголын бичвэр BLCUP 录音文本及答案 (HSK6下 Recording Text.pdf х.58–62)-аас нэмэв. Дасгалын номын 阅读 18–36 хариулт эдгээр эх сурвалжид хэвлэгдээгүй тул оруулаагүй хэвээр.", "Аудио файлын нэр мэдэгдэхгүй тул audio талбар орхисон. Сурах бичгийн CD тэмдэг: 课文 = 35-1, 生词 = 35-2; дасгалын номын 听力 第一部分 = 35-1, 第二部分 = 35-2, 第三部分 = 35-3.", "Хичээлийн гарчгийн пиньинь (title_pinyin) номд хэвлэгдээгүй — «Zǒujìn mùbǎn niánhuà» гэж стандарт дуудлагаар бичсэн (номоос биш; 木版/年画 生词-д ороогүй). title_en номын гарчгийн доорх «Approaching the woodblock New Year Pictures».", "课文 гарчигт «（1447字）» гэж хэвлэгдсэн. 课文-ийн гарчиг = хичээлийн гарчиг (走近木版年画). Бичвэр 3 дэд гарчигтай (年画的起源 / 木版年画 / 年画传人张光宁) — L22 жишгээр дэд гарчиг бүрийг тусдаа lines мөр болгон оруулсан (мөрийн дугаар 1-ээс: [1, 7, 18]). Зургаар бичсэн бичвэр: дэд гарчиггүй цэг таслалтай нийт тэмдэгт 1429 («——»-г 2 тэмдэгт гэж), зөвхөн ханз 1267; 3 дэд гарчиг (16 тэмдэгт) нэмбэл 1445 — хэвлэсэн 1447-оос 2-оор бага (тоолох аргын ялгаа байж болно; бичвэрийг зурагтай дахин тулгасан). Пиньинь бичвэр хэвлэгдээгүй тул lines.pinyin байхгүй. 11 догол мөр — lines-ийг өгүүлбэрээр хуваасан (ишлэл доторх «。？» дээр хуваагаагүй); догол мөр эхлэх мөрийн дугаар (1-ээс): [2, 3, 5, 8, 9, 12, 14, 19, 26, 29, 33].", "课文-д 4 зүүлтийн (脚注) тэмдэг бий, дугаарлалт хуудас бүрт ①-ээс дахин эхэлнэ: 唐宋① ба 清朝② (PDF х.158), 宋明① (х.159), 魏州① (х.160). lines-д тэмдгийг оруулаагүй (бичвэр цэвэр). Зүүлтийн бичвэрийг textbook.culture-д («课文脚注») хэвлэгдсэн дарааллаар бүтнээр оруулав (①②①① — номд байгаагаар). 清朝-ийн он «公元1616年～公元1911年» гэж хэвлэгдсэн (номд байгаагаар, засаагүй). Энэ хичээлд 文化/俗语 хэсэг байхгүй. 课文-д эх сурвалжийн тэмдэглэл (改编自…) хэвлэгдээгүй.", "课文 доторх зураг (PDF х.159): уран бичлэгтэй цаасан дээр сийлбэртэй оройтой чулуун тамга (印章), улаан тамганы будагны дугуй хайрцаг, цаасан дээр улаан тамганы дардас.", "生词 51 дугаар (1–51) + 34 残次品-ийн доор дугааргүй дэд үг «次品 cìpǐn n. defective product» — L23/L29 жишгээр new_words-д n=34-өөр тусад нь оруулав (нийт 52 бичлэг). * тэмдэгтэй үг байхгүй. 专有名词 хэсэг байхгүй (张光宁、魏州 生词-д ороогүй). Үгийн ай (pos) хэвлэгдээгүй: 11 盖章, 15 烟花爆竹, 23 喜闻乐见, 33 吞吞吐吐, 34 残次品, 43 再接再厉, 50 任重道远, 51 一帆风顺. Пиньинь номд байгаагаар: 11 «gài zhāng», 15 «yānhuā bàozhú», 19 «fā cái», 34 «cáncì pǐn», 45 «quē xí» (зайтай); 23 «xǐwén-lèjiàn», 43 «zàijiē-zàilì», 50 «rènzhòng-dàoyuǎn», 51 «yìfān-fēngshùn» (зураастай); 33 «tūntūntǔtǔ» (зураасгүй); 3 «xiōng’è» (’ тэмдэгтэй); 38 扎实 «zhāshi» (хөнгөн хөг). 20 连年 «v. in successive years…» — үгийн ай ба англи тайлбар зөрж байгаа ч номд байгаагаар.", "热身1 — 6 зурагтай нүд (3+3, мөрөөр уншсан дараалал), зураг бүрийн доор нэр + пиньинь (номд байгаагаар warmup[0].items-д). 热身2 — 4 мөрт хүснэгт (画／展／墨／花 | үгс), warmup[1].items-д мөр мөрөөр.", "注释 (一) 综合注释 2 зүйл (终究、愈……愈……) → grammar 1–2; (二) 词语辨析 连年——连续 (дугааргүй хайрцаг) хүснэгтийг grammar 3 болгон (explanation_zh + structure_rows; хүснэгтэд «2.“连年”后面不带数量词语。» нүд 连续 баганын хоёр мөрийг хамарсан); (三) 篇章修辞 篇章（6）重复关键词，推进主题 (дугааргүй хайрцаг) → grammar 4. Номын улаан өнгөөр хэвлэгдсэн жишээ = 课文-ийн өгүүлбэр → note_zh «课文句» (终究 用法1 (1), 愈……愈…… (1), 篇章 (1)). 终究 — хоёр ■ утга, жишээ тус бүр (1)(2) дугаартай → examples n=1–4, note_zh-д «用法N 例（k）».", "连年——连续 хүснэгтэд «连年/连续», «连年», «连续» гэсэн жишээний үгс хөх өнгөөр тодотгогдсон; «如：连年大丰收» төгсгөлд «。» хэвлэгдээгүй — номд байгаагаар. 做一做 4 өгүүлбэр ❶–❹ дугаартай.", "练一练 (终究) — өгүүлбэр бүрийн доор 1–2 хоосон мөр → zh-д «\\n________». 练一练 (愈……愈……) — A–F 6 хэсэг, доор «（1）（2）（3）» хоосон зай; items 1–3 тус бүрт A–F сонголтыг давтсан. 练一练 (篇章6) — нэг догол, 4 хоосон зай. Энэ догол мөрөнд «小张的花店…» гэж эхлээд «小李亲自骑自行车…» гэж хэвлэгдсэн (нэр зөрүү — номд байгаагаар).", "练习1 模仿例子： доогуур цэгтэй ханз — 例 文献 (文), 增添 (增), 发财 (财), 外行 (行), 故乡 (乡); томруулж шалгаад hint_zh-д. Жишээ мөр «文献：文章 文学 文人 作文» номд хэвлэгдсэн (n=«例»). 练习2 — 6 өгүүлбэр, доор нь хоосон мөр + «。» → zh-д «\\n________。».", "练习3 选词填空： 2 догол, тус бүр 5 хоосон зай + өөрийн 5 үгийн сан (word_bank 2 бүлэг, hint_zh-д давтсан). 练习4 — 4 догол, доор нь хоосон мөр + «。».", "练习5 — номд 3 баганатай хүснэгт (х.165–166 дамнасан): «年画的起源» (1 мөр); «木版年画» → 雕版的发明 / 彩色套印 / 年画走进百姓生活; «年画传人张光宁» → 初次认识 / 第二印象 / 相识久了 / 目标和信念. items.zh-д «木版年画——雕版的发明» гэх мэт нийлүүлж бичсэн. «彩色套印» мөрийн сануулгын нүд номд хоосон → hint_zh «». Сумыг «→» тэмдгээр бичсэн.", "扩展 — «词汇：熟悉下列词语的语素义» салаалсан диаграм, 12 үг 2 баганаар; items-д мөрөөр уншсан дараалал (зүүн→баруун: 回收、开采、开除、划分、请示、施加、玩弄、应酬、瞻仰、铸造、落成、配套). Энэ хэсэгт 做一做 байхгүй. 运用 — зөвхөн «写一写» (400-аас доошгүй ханз, «我们的……艺术»).", "Дасгалын ном (PDF х.129–136) — 听力 1–17 + 阅读 18–36, нийт 36 асуулт. Энэ хичээлд 三、书写 хэсэг байхгүй (дараагийн хуудас х.137 = 第36课). 听力-д зөвхөн сонголт хэвлэгдсэн (асуулт/бичвэр байхгүй) → zh «».", "Дасгалын ном 阅读 18C «只要你不耍脾气» — 800dpi-аар томруулж «耍» гэж баталсан (OCR «要»). 18B «引力坍缩». 20C «那个昏睡了一个年的植物人» — «一个年» гэж хэвлэгдсэн (病句 асуултын сонголт; номд байгаагаар, засаагүй). 19D «进言——» урт зураас.", "Дасгалын ном 阅读 21–23: сонголт бүр 3–4 үгийн багц — options-д «　»-аар холбосон. 22-т «性，________问题» хэсэгт нарийн таслал мэт хэвлэгдсэн — бүтэн өргөнтэй «，» болгосон. 23-т эхний мөрийн төгсгөлийн хоосон зай дараагийн мөрөнд үргэлжилсэн («的______\\n__。») — нэг «________» болгосон.", "Дасгалын ном 阅读 24–28: бичвэр section.instruction_zh-д, сонголт A–E бүх item-д давтсан; 26 ба 27 нэг өгүүлбэрт орсон тул хоёуланд нь тэр өгүүлбэрийг өгсөн. Бичвэрт «（25）», «（27）», «（28）»-ийн өмнөх таслал болон «（一）…（六）»-ийн хоорондох «;» нарийсгасан/хагас өргөнтэй мэт хэвлэгдсэн — бүтэн өргөнтэй «，／；» болгосон. Бичвэрт «在各社区和群体适用周围环境» гэж хэвлэгдсэн (номд байгаагаар). Хажууд нь хоёр хүүхэд луу бүжиглүүлж буй цаасан хайчилбарын (剪纸) зураг.", "Дасгалын ном 阅读 29–32 — бичвэрийн хажууд бүрхүүлтэй, хошуутай цайвар паалантай шаазан данхны (瓷壶) хар цагаан зураг. 33–36 — хажууд нь Буддагийн дүрстэй唐卡-г бийрээр зурж буй эрэгтэйн зураг. 29–36 нэг заавар («第29–36题») — хоёр бичвэрийг тус тусын section-д (29–32, 33–36). 35A «进了装修队» ↔ бичвэрт «进了建筑队» — асуултын сонголт, номд байгаагаар.", "Дасгалын номын 阅读 18–36-ийн хариултыг BLCUP 录音文本及答案 (HSK6下 Recording Text.pdf) төгсгөлийн нэгдсэн 参考答案 хүснэгт (х.94–100)-ээс нэмсэн; 听力 1–17-ийн inline хариулттай тулгасан.", "Номын өөрийн зөрүү: 听力 7-ийн хариулт бичвэрийн дараах inline «答案»-д «B», төгсгөлийн нэгдсэн 参考答案 хүснэгтэд (х.94–100) «D» — inline хувилбарыг answer-т үлдээсэн, засаагүй."], "verified_pages": [157, 158, 159, 160, 161, 162, 163, 164, 165, 166, 167, 129, 130, 131, 132, 133, 134, 135, 136], "schema_version": 1}'::jsonb, 1, 'image_verified')
